function getUIPortraitAssetPath(registryId) {
  return typeof registryId==="string"&&(UI_PORTRAIT_MANIFEST[registryId]||"")||"";
}

function getUIPortraitRegistryId(subject) {
  if (!subject) return null;
  if (typeof subject==="string") return Object.prototype.hasOwnProperty.call(UI_PORTRAIT_MANIFEST,subject)?subject:null;
  const candidates=[subject.registryId,subject.entityId,subject.summonId,subject.sourceEntityId,subject.id].filter(Boolean);
  return candidates.find(id=>Object.prototype.hasOwnProperty.call(UI_PORTRAIT_MANIFEST,id))||null;
}

function resolveUIPortraitProjection(subject) {
  const registryId=getUIPortraitRegistryId(subject);
  if (!registryId) return {registryId:null,path:"",status:"missing_authority",fallbackUsed:false};
  const path=getUIPortraitAssetPath(registryId);
  return path?{registryId,path,status:"active",fallbackUsed:false}:{registryId,path:"",status:"missing_authority",fallbackUsed:false};
}

function getCharacterCardAssetPath(
  assetId
) {

  return (
    assetManifest.characterCards[
      assetId
    ] ||
    ""
  );
}


// =========================================================
// BRICKS 1053–1055 — CANONICAL ENTITY COLLECTIBLE-CARD RESOLVERS
// =========================================================
function getEntityCollectibleCardAssetPath(assetId) {
  return typeof assetId==="string"&&assetManifest.entityCollectibleCards&&assetManifest.entityCollectibleCards[assetId]||"";
}

function getEntityCollectibleOntologyClassification(assetId) {
  return typeof assetId==="string"&&assetManifest.entityCollectibleOntology&&assetManifest.entityCollectibleOntology[assetId]||null;
}

function getEntityCollectibleCardProjection(assetId) {
  const registryId=typeof assetId==="string"?assetId:"";
  const path=getEntityCollectibleCardAssetPath(registryId);
  const ontology=getEntityCollectibleOntologyClassification(registryId);
  const live=typeof ALPHA_PRODUCTION_ENTITY_IDS!=="undefined"&&ALPHA_PRODUCTION_ENTITY_IDS.includes(registryId);
  const registryRecord=registryId&&typeof getEntityDefinition==="function"?getEntityDefinition(registryId):null;
  return {
    registryId,registryType:"Entity",ontologyClassification:ontology,collectibleCard:path,
    collectibleCardStatus:path?"mapped":"missing_authority",
    uiPortrait:getUIPortraitAssetPath(registryId),
    uiPortraitStatus:getUIPortraitAssetPath(registryId)?"active":"missing_authority",
    productionStatus:live?"live":"not_live",registryRecordPresent:!!registryRecord
  };
}

function getHostedEntityAssetPath(assetId) {
  // Compatibility bridge for explicitly authored Story Scene references only.
  // It is intentionally NOT a generic lifecycle/ownership classifier.
  return typeof assetId==="string"&&assetManifest.hostedEntities&&assetManifest.hostedEntities[assetId]||"";
}


// =========================================================
// BRICK 765 — STORY SCENE BACKDROP ASSET PATH BRIDGE
// =========================================================
function getSceneBackdropAssetPath(assetId) {
  return (assetManifest.sceneBackdrops&&assetManifest.sceneBackdrops[assetId]) || "";
}

function registerSceneBackdropAssetPath(assetId,path) {
  if (!assetId||!path) return {success:false,reason:"scene_backdrop_asset_identity_or_path_missing"};
  if (!assetManifest.sceneBackdrops||typeof assetManifest.sceneBackdrops!=="object") assetManifest.sceneBackdrops={};
  assetManifest.sceneBackdrops[String(assetId)]=String(path);
  return {success:true,assetId:String(assetId),path:String(path)};
}


function getUIAssetPath(
  assetId
) {

  return (
    assetManifest.ui[
      assetId
    ] ||
    ""
  );
}


// =========================================================
// BRICK 683 — FIVE ACADEMY COLLECTIBLE CARD ASSET DIAGNOSTIC
// =========================================================
function runAcademyExpansionCardAssetDiagnostics() {
  const expected={
    academy_kurenai:"Assets/Academy Student/academy_kurenai.png",
    academy_iwabee:"Assets/Academy Student/academy_iwabe.png",
    academy_metal_lee:"Assets/Academy Student/academy_metal.png",
    academy_kakashi:"Assets/Academy Student/academy_kakashi.png",
    academy_obito:"Assets/Academy Student/academy_obito.png"
  };
  const ids=Object.keys(expected);
  const result={
    allFiveCardMappingsExact:ids.every(id=>getCharacterCardAssetPath(id)===expected[id]),
    iwabeeMapsPhysicalIwabeFile:getCharacterCardAssetPath("academy_iwabee")==="Assets/Academy Student/academy_iwabe.png",
    metalLeeMapsPhysicalMetalFile:getCharacterCardAssetPath("academy_metal_lee")==="Assets/Academy Student/academy_metal.png",
    registryIdentityIndependentFromFilename:getCharacterCardAssetPath("academy_iwabee").endsWith("academy_iwabe.png")&&getCharacterCardAssetPath("academy_metal_lee").endsWith("academy_metal.png"),
    registryIdsUnchanged:ids.every(id=>typeof characterRegistry!=="undefined"&&!!characterRegistry[id]),
    productionTargetRemains102:typeof ALPHA_PRODUCTION_CHARACTER_IDS!=="undefined"&&typeof ALPHA_PRODUCTION_ENTITY_IDS!=="undefined"&&ALPHA_PRODUCTION_CHARACTER_IDS.length===85&&ALPHA_PRODUCTION_ENTITY_IDS.length===17,
    cardAssetIsNotPortraitAuthority:ids.every(id=>typeof getCharacterCardAssetPath(id)==="string"&&getCharacterCardAssetPath(id).startsWith("Assets/Academy Student/"))
  };
  result.pass=Object.values(result).every(value=>value===true);
  console.table(result);
  return result;
}


// =========================================================
// BRICK 437 — VICTORY ASSET PATH DIAGNOSTIC
// =========================================================
function runVictoryAssetManifestDiagnostics() {
  const path=getUIAssetPath("victory");
  const result={
    manifestEntry:path==="UI/Victory.png",
    uiScoped:typeof path==="string"&&path.startsWith("UI/"),
    noLegacyBackgroundPath:path!=="Backgrounds/Victory.png"
  };
  result.pass=Object.values(result).every(value=>value===true);
  console.table(result);
  return result;
}

