// =========================================================
// CLONE PROGRESSION OBJECT
// =========================================================

function cloneProgressionData(
  data
) {


  if (
    !data ||
    typeof data !==
      "object"
  ) {

    return {};

  }


  return JSON.parse(
    JSON.stringify(
      data
    )
  );

}


