// BRICK 549 — ACQUISITION MASTER DIAGNOSTIC
// =========================================================
function runAcquisitionV1Diagnostics() {
  const state=ensurePlayerAcquisitionState();
  const ownedIds=playerData.characterOwnership&&Array.isArray(playerData.characterOwnership.ownedRegistryIds)?playerData.characterOwnership.ownedRegistryIds:[];
  const result={
    onePersistentOwnedRecordPerVariant:Object.keys(state.ownedCharactersByVariantId).every(variantId=>state.ownedCharactersByVariantId[variantId].ownedCharacterId===createOwnedCharacterIdForVariant(variantId)),
    ownershipSeparateFromIdentity:typeof state.ninjaIdentityVariantId!=="undefined"&&Array.isArray(ownedIds),
    originChoicesExactlyTen:CHRONICLE_ORIGIN_VARIANT_IDS.length===10&&new Set(CHRONICLE_ORIGIN_VARIANT_IDS).size===10&&["academy_hinata","academy_izuno","academy_mirai","academy_menma","academy_kushina","academy_kurenai","academy_iwabee","academy_metal_lee","academy_kakashi","academy_obito"].every(id=>CHRONICLE_ORIGIN_VARIANT_IDS.includes(id)),
    noFreshAutoRoster:createDefaultCharacterOwnershipState().ownedRegistryIds.length===0,
    noFreshAutoEntityGrant:createDefaultPlayerEntityState().ownedEntityIds.length===0,
    academyFormationSeparate:state.academyTeamFormation&&typeof state.academyTeamFormation.completed==="boolean",
    geninTransitionSeparate:state.geninRosterTransition&&typeof state.geninRosterTransition.unlocked==="boolean",
    legacyFirstTeamDeprecated:state.firstTeamFormation&&state.firstTeamFormation.deprecated===true,
    joninAssignmentSeparate:Object.prototype.hasOwnProperty.call(state,"joninLeadershipAssignment")
  };
  result.pass=Object.values(result).every(value=>value===true);
  return result;
}

function getClanManageableRosterCharacters(ownershipState = characterOwnershipRuntimeAuthority) {
  return playerTeam.filter(character =>
    character && character.id && isRuntimeCharacterOwned(character, ownershipState)
  );
}

function createDefaultClanManagementState(ownershipState = characterOwnershipRuntimeAuthority) {
  const defaultIds = getClanManageableRosterCharacters(ownershipState)
    .slice(0, CLAN_TEAM_SLOT_COUNT)
    .map(character => character.id);
  return {
    teamSlots: Array.from({length:CLAN_TEAM_SLOT_COUNT}, (_, index) => defaultIds[index] || null),
    favoriteIds: []
  };
}

function normalizeClanManagementState(savedClan, ownershipState = characterOwnershipRuntimeAuthority) {
  const defaults = createDefaultClanManagementState(ownershipState);
  if (!savedClan || typeof savedClan !== "object") return defaults;
  const manageableIds = new Set(getClanManageableRosterCharacters(ownershipState).map(character => character.id));
  const rawSlots = Array.isArray(savedClan.teamSlots)
    ? savedClan.teamSlots
    : (Array.isArray(savedClan.teamIds) ? savedClan.teamIds : null);
  const teamSlots = [];
  const seen = new Set();
  if (rawSlots) {
    for (let index=0; index<CLAN_TEAM_SLOT_COUNT; index+=1) {
      const characterId = typeof rawSlots[index] === "string" ? rawSlots[index] : null;
      const validId = characterId && manageableIds.has(characterId) && !seen.has(characterId) ? characterId : null;
      teamSlots.push(validId);
      if (validId) seen.add(validId);
    }
  } else {
    teamSlots.push(...defaults.teamSlots);
  }
  const favoriteIds = Array.isArray(savedClan.favoriteIds)
    ? [...new Set(savedClan.favoriteIds.filter(characterId => typeof characterId === "string" && manageableIds.has(characterId)))]
    : [];
  return { teamSlots, favoriteIds };
}



// BRICK 373 — ENTITY CURRENT-STATE SAVE AUTHORITY
// BRICK 374 — ATTACHED SUMMON SAVE AUTHORITY
// BRICK 375 — EXACT-INSTANCE WEAPON ACCLIMATION SAVE AUTHORITY
// =========================================================

function createDefaultEntityCurrentStats() {
  const currentStatsByEntityId = {};
  Object.values(entityRegistry).forEach(entity => {
    if (entity && entity.baseStats) currentStatsByEntityId[entity.id] = cloneCanonicalSevenStats(entity.baseStats);
  });
  return currentStatsByEntityId;
}

function createDefaultPlayerEntityState(options = {}) {
  const legacySeed = options.legacySeedMigration === true;
  return {
    ownedEntityIds: legacySeed ? ["menma_nine_tails"] : [],
    currentStatsByEntityId: createDefaultEntityCurrentStats(),
    attachedSummonByCharacterRegistryId: legacySeed ? { academy_menma:"menma_nine_tails" } : {}
  };
}

function getEntityCurrentStats(entityId) {
  const definition = getEntityDefinition(entityId);
  const saved = playerData && playerData.entities && playerData.entities.currentStatsByEntityId
    ? playerData.entities.currentStatsByEntityId[entityId]
    : null;
  return cloneCanonicalSevenStats(saved || (definition ? definition.baseStats : null));
}

function calculateEntityCurrentPL(entityId) {
  const definition = getEntityDefinition(entityId);
  if (!definition || !definition.baseStats) return null;
  return Math.round(calculateRawPLFromStats(getEntityCurrentStats(entityId)));
}

// =========================================================
// BRICK 421 — ENTITY OWNERSHIP / PERMANENT STAT DEVELOPMENT API
// =========================================================

function grantEntityOwnership(entityId) {
  const entity=getEntityDefinition(entityId);
  if (!entity || !entity.baseStats) return {success:false,reason:"entity_registry_missing_or_reserved"};
  if (!playerData.entities) playerData.entities=createDefaultPlayerEntityState();
  const changed=!playerData.entities.ownedEntityIds.includes(entityId);
  if (changed) playerData.entities.ownedEntityIds.push(entityId);
  if (!playerData.entities.currentStatsByEntityId[entityId]) playerData.entities.currentStatsByEntityId[entityId]=cloneCanonicalSevenStats(entity.baseStats);
  savePlayerData();
  return {success:true,changed,entityId};
}

function increaseEntityStat(entityId, statName, amount) {
  const validStats=["nin","tai","buki","fuin","kin","gen","stamina"];
  if (!validStats.includes(statName)) return {success:false,reason:"invalid_stat"};
  const entity=getEntityDefinition(entityId);
  if (!entity || !entity.baseStats) return {success:false,reason:"entity_registry_missing"};
  if (!playerData.entities || !playerData.entities.ownedEntityIds.includes(entityId)) return {success:false,reason:"entity_not_owned"};
  const delta=Number(amount)||0;
  if (delta===0) return {success:false,reason:"zero_stat_change"};
  const stats=playerData.entities.currentStatsByEntityId[entityId] || cloneCanonicalSevenStats(entity.baseStats);
  stats[statName]=(Number(stats[statName])||0)+delta;
  playerData.entities.currentStatsByEntityId[entityId]=stats;
  savePlayerData();
  return {success:true,entityId,statName,currentValue:stats[statName],currentPL:calculateEntityCurrentPL(entityId)};
}


// =========================================================
// BRICK 916 — SAVEABLE ENCOUNTER RESERVATION RUNTIME
// =========================================================
// Current-state persistence only. Chronicle/history remains in the existing
// activity/evidence authorities. A reservation freezes exact opposition and
// package identity once encounter construction crosses commitment.
function createDefaultEncounterRuntimeState() {
  return {
    sequence:0,
    reservationsByEncounterId:{},
    lastCompletedOccurrenceByEncounterId:{}
  };
}

function normalizeEncounterRuntimeState(savedState) {
  const source=savedState&&typeof savedState==="object"?savedState:{};
  const reservations={};
  const raw=source.reservationsByEncounterId&&typeof source.reservationsByEncounterId==="object"
    ? source.reservationsByEncounterId:{};
  Object.entries(raw).forEach(([encounterId,reservation])=>{
    if (!encounterId||!reservation||typeof reservation!=="object") return;
    if (!reservation.occurrenceId||!reservation.oppositionTemplateId) return;
    reservations[encounterId]={
      encounterId:String(encounterId),
      occurrenceId:String(reservation.occurrenceId),
      oppositionTemplateId:String(reservation.oppositionTemplateId),
      encounterStatePackageId:reservation.encounterStatePackageId?String(reservation.encounterStatePackageId):null,
      selectionMode:reservation.selectionMode?String(reservation.selectionMode):"deterministic",
      contextSnapshot:reservation.contextSnapshot&&typeof reservation.contextSnapshot==="object"?cloneProgressionData(reservation.contextSnapshot):{},
      status:["reserved","started","completed"].includes(reservation.status)?reservation.status:"reserved",
      reservedAt:Number(reservation.reservedAt)||null,
      startedAt:Number(reservation.startedAt)||null,
      completedAt:Number(reservation.completedAt)||null,
      outcome:reservation.outcome?cloneProgressionData(reservation.outcome):null
    };
  });
  const completed=source.lastCompletedOccurrenceByEncounterId&&typeof source.lastCompletedOccurrenceByEncounterId==="object"
    ? cloneProgressionData(source.lastCompletedOccurrenceByEncounterId):{};
  return {
    sequence:Math.max(0,Math.floor(Number(source.sequence)||0)),
    reservationsByEncounterId:reservations,
    lastCompletedOccurrenceByEncounterId:completed
  };
}

// =========================================================
// BRICKS 1175–1180 — ORIGIN CONSEQUENCE PERSISTENCE ENVELOPE
// =========================================================
// Persistent consequence identity is sourceOccurrenceId + consequenceContractId.
// Origin identity is provenance, never the dedupe key.
function createDefaultOriginConsequenceState() {
  return {
    receipts: [],
    committedAddresses: []
  };
}

function normalizeOriginConsequenceState(savedState) {
  const source=savedState&&typeof savedState==="object"?savedState:{};
  const receipts=[];
  const addresses=new Set();

  (Array.isArray(source.receipts)?source.receipts:[]).forEach(raw=>{
    if (!raw||typeof raw!=="object") return;
    const sourceOccurrenceId=typeof raw.sourceOccurrenceId==="string"?raw.sourceOccurrenceId.trim():"";
    const consequenceContractId=typeof raw.consequenceContractId==="string"?raw.consequenceContractId.trim():"";
    if (!sourceOccurrenceId||!consequenceContractId) return;
    const address=createOriginConsequenceAddress(sourceOccurrenceId,consequenceContractId);
    if (addresses.has(address)) return;
    addresses.add(address);
    receipts.push({
      address,
      originVariantId:typeof raw.originVariantId==="string"?raw.originVariantId:"",
      sourceOccurrenceId,
      consequenceContractId,
      rowId:typeof raw.rowId==="string"?raw.rowId:"",
      exclusivityFamily:typeof raw.exclusivityFamily==="string"?raw.exclusivityFamily:null,
      qualificationFacts:raw.qualificationFacts&&typeof raw.qualificationFacts==="object"?cloneProgressionData(raw.qualificationFacts):{},
      payload:raw.payload&&typeof raw.payload==="object"?cloneProgressionData(raw.payload):{},
      consumer:typeof raw.consumer==="string"?raw.consumer:"",
      causalAncestry:Array.isArray(raw.causalAncestry)?cloneProgressionData(raw.causalAncestry):[],
      committed:true,
      committedAt:Number(raw.committedAt)||null
    });
  });

  return {
    receipts,
    committedAddresses:[...addresses]
  };
}


// =========================================================
// BRICKS 5500–5508 — WORLD MAP V2 SAVEABLE PRESENTATION STATE
// =========================================================
// This state owns only map-projection continuity. It does not grant travel,
// discovery Knowledge, event eligibility, village access or secret identity.
// The seven current high-profile secret reservations intentionally begin in
// KNOWN_UNKNOWN_LOCKED and remain there until another owning system supplies
// an exact reveal/access consequence.
function createDefaultWorldMapRuntimeState() {
  return {
    secretProjectionByAddress:{
      "world:S01":{state:"KNOWN_UNKNOWN_LOCKED"},
      "world:S02":{state:"KNOWN_UNKNOWN_LOCKED"},
      "world:S03":{state:"KNOWN_UNKNOWN_LOCKED"},
      "world:S04":{state:"KNOWN_UNKNOWN_LOCKED"},
      "world:S05":{state:"KNOWN_UNKNOWN_LOCKED"},
      "world:S06":{state:"KNOWN_UNKNOWN_LOCKED"},
      "world:S07":{state:"KNOWN_UNKNOWN_LOCKED"}
    }
  };
}

function normalizeWorldMapRuntimeState(savedState) {
  const defaults=createDefaultWorldMapRuntimeState();
  const source=savedState&&typeof savedState==="object"&&!Array.isArray(savedState)?savedState:{};
  const raw=source.secretProjectionByAddress&&typeof source.secretProjectionByAddress==="object"&&!Array.isArray(source.secretProjectionByAddress)
    ? source.secretProjectionByAddress
    : {};
  const secretProjectionByAddress={};
  Object.keys(defaults.secretProjectionByAddress).forEach(address=>{
    const candidate=raw[address]&&typeof raw[address]==="object"?raw[address]:{};
    // No reveal predicate is yet implemented for this family. Fail closed.
    secretProjectionByAddress[address]={state:"KNOWN_UNKNOWN_LOCKED"};
    void candidate;
  });
  return {secretProjectionByAddress};
}

function ensureWorldMapRuntimeState() {
  if (!playerData.worldMapRuntime||typeof playerData.worldMapRuntime!=="object"||Array.isArray(playerData.worldMapRuntime)) {
    playerData.worldMapRuntime=createDefaultWorldMapRuntimeState();
  }
  playerData.worldMapRuntime=normalizeWorldMapRuntimeState(playerData.worldMapRuntime);
  return playerData.worldMapRuntime;
}

function createDefaultPlayerData() {
  const characterOwnership = createDefaultCharacterOwnershipState();
  setCharacterOwnershipRuntimeAuthority(characterOwnership);
  return {
    ryo: 0,
    exp: 0,
    inventory: [],
    battlePouch: normalizeBattlePouchSelection(null),
    characterOwnership: characterOwnership,
    acquisition: createDefaultAcquisitionState(),
    specialistQualifications: createDefaultSpecialistQualificationState(),
    clan: createDefaultClanManagementState(characterOwnership),
    entities: createDefaultPlayerEntityState(),
    weaponAcclimation: {},
    activityHistory: [],
    // BRICKS 1860–1864 — stable Chronicle participant life/custody/injury facts.
    // This is independent of observer-safe presentation labels.
    participantChronicleState: createDefaultParticipantChronicleState(),
    // BRICKS 1690–1694 — world/event observer state is durable player state.
    // It is separate from activityHistory: discovery/actionability/tracking/resolution
    // are current authoritative dimensions, while history records committed occurrences.
    worldEventRuntime: createDefaultWorldEventRuntimeState(),
    // BRICKS 5500–5508 — saveable World Map v2 projection continuity.
    worldMapRuntime: createDefaultWorldMapRuntimeState(),
    // BRICK 916 — committed encounter reservation/current-state identity.
    encounterRuntime: createDefaultEncounterRuntimeState(),
    // BRICK 742 — STORY SCENE RUNTIME IS SAVEABLE CURRENT STATE, NOT HISTORY
    storySceneRuntime: createDefaultStorySceneRuntimeState(),
    // BRICKS 1175–1180 — machine-addressed Origin consequence receipts.
    originConsequences: createDefaultOriginConsequenceState(),
    progression: createDefaultRunProgression(),
    characters: createDefaultCharacterProgression(),
    collections: {
      specialNinja: [],
      bloodlines: []
    }
  };
}


// =========================================================
// NORMALIZE PLAYER COLLECTIONS
// =========================================================

function normalizePlayerCollections(
  savedCollections
) {


  const source =
    savedCollections &&
    typeof savedCollections ===
      "object"

      ? savedCollections

      : {};


  return {

    specialNinja:
      normalizeInheritanceCollection(
        source.specialNinja
      ),

    bloodlines:
      normalizeInheritanceCollection(
        source.bloodlines
      )

  };

}


// =========================================================
// NORMALIZE SAVED RUN PROGRESSION
// =========================================================

function normalizeSavedRunProgression(
  savedProgression
) {


  const defaults =
    createDefaultRunProgression();


  if (
    !savedProgression ||
    typeof savedProgression !==
      "object"
  ) {

    return defaults;

  }


  const currentDifficulty =
    getShinobiDifficulty(
      savedProgression.currentDifficulty
    )
      ? savedProgression.currentDifficulty
      : defaults.currentDifficulty;


  const highestDifficultyUnlocked =
    getShinobiDifficulty(
      savedProgression.highestDifficultyUnlocked
    )
      ? savedProgression.highestDifficultyUnlocked
      : defaults.highestDifficultyUnlocked;


  return {

    currentDifficulty:
      currentDifficulty,

    highestDifficultyUnlocked:
      highestDifficultyUnlocked,

    legacyCycle:
      Math.max(
        0,
        Math.floor(
          Number(
            savedProgression.legacyCycle
          ) || 0
        )
      ),

    completedDifficulties:
      Array.isArray(
        savedProgression.completedDifficulties
      )
        ? savedProgression.completedDifficulties.filter(
            difficultyId =>
              !!getShinobiDifficulty(
                difficultyId
              )
          )
        : [],

    runCompleted:
      savedProgression.runCompleted ===
      true

  };

}

// =========================================================
// NORMALIZE DISCIPLINE PROGRESSION
// =========================================================

function normalizeDisciplineProgression(
  savedProgression
) {


  const defaults =
    createDefaultDisciplineProgression();


  const source =
    savedProgression &&
    typeof savedProgression ===
      "object"
      ? savedProgression
      : {};


  const normalized = {};


  Object.keys(
    defaults
  ).forEach(
    disciplineId => {


      const savedRecord =
        source[
          disciplineId
        ] || {};


      const level =
        Math.max(
          1,
          Math.floor(
            Number(
              savedRecord.level
            ) || 1
          )
        );


      const rawStatLevelApplied =
        savedRecord.statLevelApplied;


      const statLevelApplied =
        Number.isFinite(
          Number(
            rawStatLevelApplied
          )
        )
          ? Math.max(
              1,
              Math.min(
                level,
                Math.floor(
                  Number(
                    rawStatLevelApplied
                  )
                )
              )
            )
          : 1;


      normalized[
        disciplineId
      ] = {

        level:
          level,

        exp:
          Math.max(
            0,
            Number(
              savedRecord.exp
            ) || 0
          ),

        statLevelApplied:
          statLevelApplied

      };

    }
  );


  return normalized;

}


// NORMALIZE SAVED CHARACTER PROGRESSION
// =========================================================

function normalizeSavedCharacterProgression(
  savedCharacters
) {


  const defaults =
    createDefaultCharacterProgression();


  const source =
    savedCharacters &&
    typeof savedCharacters ===
      "object"
      ? savedCharacters
      : {};


  const normalized = {};


  Object.keys(
    defaults
  ).forEach(
    characterId => {


      const defaultCharacter =
        defaults[
          characterId
        ];


      const savedCharacter =
        source[
          characterId
        ] || {};


      const savedStats =
        savedCharacter.stats &&
        typeof savedCharacter.stats ===
          "object"
          ? savedCharacter.stats
          : {};


      const normalizedStats = {
        ...defaultCharacter.stats
      };


      Object.keys(
        normalizedStats
      ).forEach(
        stat => {


          if (
            typeof savedStats[
              stat
            ] ===
              "number"
          ) {

            normalizedStats[
              stat
            ] =
              savedStats[
                stat
              ];

          }

        }
      );


      normalized[
        characterId
      ] = {

        stats:
          normalizedStats,

        permanentPLBonus:
          typeof savedCharacter
            .permanentPLBonus ===
            "number"

            ? savedCharacter
                .permanentPLBonus

            : defaultCharacter
                .permanentPLBonus,

        disciplineProgression:
          normalizeDisciplineProgression(
            savedCharacter
              .disciplineProgression
          ),

        weaponSpecializations:
          savedCharacter
            .weaponSpecializations &&
          typeof savedCharacter
            .weaponSpecializations ===
            "object"

            ? cloneProgressionData(
                savedCharacter
                  .weaponSpecializations
              )

            : cloneProgressionData(
                defaultCharacter
                  .weaponSpecializations
              )

      };

    }
  );


  return normalized;

}


// =========================================================


// =========================================================
// BRICK 376 — ENTITY SAVE NORMALIZATION
// BRICK 377 — ATTACHMENT VALIDATION / MIGRATION
// BRICK 378 — ACCLIMATION MUTUAL-EXCLUSIVITY NORMALIZATION
// =========================================================

function normalizePlayerEntityState(savedEntities, options = {}) {
  const defaults = createDefaultPlayerEntityState(options);
  const source = savedEntities && typeof savedEntities === "object" ? savedEntities : {};
  const ownedEntityIds = Array.isArray(source.ownedEntityIds)
    ? [...new Set(source.ownedEntityIds.filter(entityId => typeof entityId === "string" && !!getEntityDefinition(entityId)))]
    : [...defaults.ownedEntityIds];
  const currentStatsByEntityId = {};
  Object.entries(defaults.currentStatsByEntityId).forEach(([entityId, baseStats]) => {
    const saved = source.currentStatsByEntityId && source.currentStatsByEntityId[entityId];
    const stats = cloneCanonicalSevenStats(baseStats);
    if (saved && typeof saved === "object") {
      Object.keys(stats).forEach(stat => {
        if (typeof saved[stat] === "number" && Number.isFinite(saved[stat])) stats[stat] = saved[stat];
      });
    }
    currentStatsByEntityId[entityId] = stats;
  });
  const attached = {};
  const rawAttached = source.attachedSummonByCharacterRegistryId && typeof source.attachedSummonByCharacterRegistryId === "object"
    ? source.attachedSummonByCharacterRegistryId
    : defaults.attachedSummonByCharacterRegistryId;
  Object.entries(rawAttached).forEach(([registryId, entityId]) => {
    const entity = getEntityDefinition(entityId);
    if (getCharacterRegistryEntry(registryId) && isAttachableSummonEntity(entity)) {
      attached[registryId] = entityId;
    }
  });
  return { ownedEntityIds, currentStatsByEntityId, attachedSummonByCharacterRegistryId: attached };
}

function normalizeWeaponAcclimationState(savedState) {
  const source = savedState && typeof savedState === "object" ? savedState : {};
  const normalized = {};
  Object.entries(source).forEach(([registryId, instanceMap]) => {
    if (!getCharacterRegistryEntry(registryId) || !instanceMap || typeof instanceMap !== "object") return;
    normalized[registryId] = {};
    Object.entries(instanceMap).forEach(([instanceId, record]) => {
      if (!instanceId || !record || typeof record !== "object") return;
      if (record.state === "unfamiliar") {
        normalized[registryId][instanceId] = { state:"unfamiliar", severity:null };
      } else if (record.state === "reacclimating" && ["minor","major","fundamental"].includes(record.severity)) {
        normalized[registryId][instanceId] = { state:"reacclimating", severity:record.severity };
      }
    });
  });
  return normalized;
}



// =========================================================
// LOAD PLAYER DATA
// =========================================================

// =========================================================
// BRICK 379 — OWNERSHIP-AWARE SAVE LOAD
// BRICK 380 — ENTITY / ACCLIMATION SAVE LOAD
// =========================================================

function loadPlayerData() {
  const savedData = localStorage.getItem(PLAYER_SAVE_KEY);
  if (!savedData) {
    console.log("No existing player save found.");
    const defaults = createDefaultPlayerData();
    setCharacterOwnershipRuntimeAuthority(defaults.characterOwnership);
    return defaults;
  }
  try {
    const parsedData = JSON.parse(savedData);
    console.log("Player save loaded:", parsedData);

    // POST-1994 — mixed-era save repair.
    // Fresh/current saves always own an explicit characterOwnership field, even
    // when intentionally empty. Older Alpha saves may already contain the newer
    // acquisition object while still lacking characterOwnership entirely. The old
    // gate only checked !parsedData.acquisition, which stranded those saves with
    // zero manageable My Clan characters and therefore no legal Battle START.
    // Missing ownership schema is the migration signal; explicit empty ownership
    // remains authoritative and is never auto-seeded.
    const ownershipSchemaMissing = !Object.prototype.hasOwnProperty.call(parsedData,"characterOwnership");
    const acquisitionMigration = parsedData.acquisition && parsedData.acquisition.migration && typeof parsedData.acquisition.migration === "object"
      ? parsedData.acquisition.migration
      : null;
    const preservedLegacyVariantIds = acquisitionMigration && acquisitionMigration.source === "pre_acquisition_alpha_seed" && Array.isArray(acquisitionMigration.preservedVariantIds)
      ? acquisitionMigration.preservedVariantIds.filter(registryId=>typeof registryId === "string" && !!getCharacterRegistryEntry(registryId))
      : [];
    const explicitOwnershipIds = parsedData.characterOwnership && Array.isArray(parsedData.characterOwnership.ownedRegistryIds)
      ? parsedData.characterOwnership.ownedRegistryIds
      : [];
    const repairPreservedLegacyOwnership = !ownershipSchemaMissing && explicitOwnershipIds.length === 0 && preservedLegacyVariantIds.length > 0;
    const legacySeedMigration = ownershipSchemaMissing;
    const ownershipLoadSource = repairPreservedLegacyOwnership
      ? {ownedRegistryIds:[...preservedLegacyVariantIds]}
      : (parsedData.characterOwnership || (legacySeedMigration ? {ownedRegistryIds:[...LEGACY_ALPHA_SEED_CHARACTER_REGISTRY_IDS]} : null));
    const characterOwnership = normalizeCharacterOwnershipState(ownershipLoadSource);
    setCharacterOwnershipRuntimeAuthority(characterOwnership);
    hydrateOwnedProductionRuntimeCharacters(characterOwnership);
    const acquisition = normalizeAcquisitionState(parsedData.acquisition,characterOwnership,{legacySeedMigration});
    const normalizedActivityHistory = normalizeActivityHistoryForChronicleContinuity(parsedData.activityHistory,acquisition);
    return {
      ryo: Number(parsedData.ryo) || 0,
      exp: Number(parsedData.exp) || 0,
      inventory: Array.isArray(parsedData.inventory) ? parsedData.inventory : [],
      battlePouch: normalizeBattlePouchSelection(parsedData.battlePouch),
      characterOwnership: characterOwnership,
      acquisition: acquisition,
      specialistQualifications: normalizeSpecialistQualificationState(parsedData.specialistQualifications),
      clan: normalizeClanManagementState(parsedData.clan, characterOwnership),
      entities: normalizePlayerEntityState(parsedData.entities,{legacySeedMigration}),
      weaponAcclimation: normalizeWeaponAcclimationState(parsedData.weaponAcclimation),
      activityHistory: normalizedActivityHistory,
      // BRICKS 1860–1864 — restore stable participant life/custody/injury facts.
      participantChronicleState: normalizeParticipantChronicleState(parsedData.participantChronicleState),
      // BRICKS 1690–1694 — restore independent World/Event dimensions.
      // Old saves with no worldEventRuntime receive the empty schema; malformed
      // dimension tables are normalized without inventing discovery or resolution.
      worldEventRuntime: normalizeWorldEventRuntimeState(parsedData.worldEventRuntime),
      // BRICKS 5500–5508 — restore World Map projection state without inventing reveal/access.
      worldMapRuntime: normalizeWorldMapRuntimeState(parsedData.worldMapRuntime),
      // BRICK 921 — preserve reserved/started encounter identity across reload.
      encounterRuntime: normalizeEncounterRuntimeState(parsedData.encounterRuntime),
      // BRICK 742 — restore current scene continuation state without inventing a story ledger.
      storySceneRuntime: normalizeStorySceneRuntimeState(parsedData.storySceneRuntime),
      originConsequences: normalizeOriginConsequenceState(parsedData.originConsequences),
      progression: normalizeSavedRunProgression(parsedData.progression),
      characters: normalizeSavedCharacterProgression(parsedData.characters),
      collections: normalizePlayerCollections(parsedData.collections)
    };
  } catch (error) {
    console.log("Player save could not be loaded:", error);
    const defaults = createDefaultPlayerData();
    setCharacterOwnershipRuntimeAuthority(defaults.characterOwnership);
    return defaults;
  }
}



// =========================================================
// ACTIVE PLAYER DATA
// =========================================================

let playerData =
  loadPlayerData();



// =========================================================
// RESTORE CHARACTER PROGRESSION FROM SAVE
// =========================================================
//
// Canonical PL migration:
//
// Old saves stored absolute character.stats values.
//
// Base Stats have now been recalibrated for the universal
// Peak / Core / Breadth PL model.
//
// To preserve player training without restoring obsolete
// stat baselines:
//
// - discipline level is preserved
// - discipline EXP is preserved
// - statLevelApplied is preserved
// - weapon specialisation is preserved
// - natural stats are rebuilt from NEW Base Stats
//
// =========================================================

function syncCharacterProgressionFromSave() {


  if (
    !playerData.characters ||
    typeof playerData.characters !==
      "object"
  ) {

    playerData.characters =
      createDefaultCharacterProgression();

  }


  playerTeam.forEach(
    character => {


      const savedCharacter =
        playerData.characters[
          character.id
        ];


      if (!savedCharacter) {

        return;

      }


      // =========================================
      // RESTORE DISCIPLINE PROGRESSION FIRST
      // =========================================

      character.disciplineProgression =
        normalizeDisciplineProgression(
          savedCharacter
            .disciplineProgression
        );


      // =========================================
      // REBUILD NATURAL CURRENT STATS
      // =========================================
      //
      // Base Stat
      // +
      // already-earned discipline stat levels.
      //
      // Old absolute saved stats are deliberately
      // not restored.
      // =========================================

      Object.keys(
        character.baseStats
      ).forEach(
        stat => {


          const progression =
            character
              .disciplineProgression[
                stat
              ];


          const appliedLevel =
            progression
              ? Math.max(
                  1,
                  Math.floor(
                    Number(
                      progression
                        .statLevelApplied
                    ) || 1
                  )
                )
              : 1;


          const levelsAboveBase =
            Math.max(
              0,
              appliedLevel - 1
            );


          const statGainPerLevel =
            getDisciplineStatGainPerLevel(
              stat
            );


          character.stats[
            stat
          ] =
            (
              Number(
                character.baseStats[
                  stat
                ]
              ) || 0
            )
            +
            (
              levelsAboveBase *
              statGainPerLevel
            );

        }
      );


      // =========================================
      // LEGACY DIRECT PL BONUS RETIRED
      // =========================================

      character.permanentPLBonus =
        0;


      // =========================================
      // RESTORE WEAPON SPECIALIZATIONS
      // =========================================

      character.weaponSpecializations =
        cloneProgressionData(
          savedCharacter
            .weaponSpecializations
        );

    }
  );


  console.log(
    "Character progression restored against canonical Base Stats."
  );

}


// =========================================================
// COPY RUNTIME CHARACTER PROGRESSION TO SAVE
// =========================================================

function syncRuntimeProgressionToPlayerData() {


  if (
    !playerData.characters ||
    typeof playerData.characters !==
      "object"
  ) {

    playerData.characters = {};

  }


  playerTeam.forEach(
    character => {


      playerData.characters[
        character.id
      ] = {

        stats: {
          ...character.stats
        },

        permanentPLBonus:
          Number(
            character.permanentPLBonus
          ) || 0,

        disciplineProgression:
          normalizeDisciplineProgression(
            character
              .disciplineProgression
          ),

        weaponSpecializations:
          cloneProgressionData(
            character.weaponSpecializations
          )

      };

    }
  );

}

// =========================================================
// APPLY SAVED CHARACTER PROGRESSION NOW
// =========================================================

syncCharacterProgressionFromSave();





// =========================================================
// BRICK 109 — SAVE PLAYER DATA
// =========================================================

function savePlayerData() {


  // =========================================
  // SYNC CHARACTER PROGRESSION
  // =========================================


  syncRuntimeProgressionToPlayerData();



  // =========================================
  // SYNC ACTIVITY HISTORY
  // =========================================


  if (
    typeof activityHistory !==
      "undefined" &&
    Array.isArray(
      activityHistory
    )
  ) {


    playerData.activityHistory =
      activityHistory;


  }



  // =========================================
  // SAVE PLAYER DATA
  // =========================================


  localStorage.setItem(
    PLAYER_SAVE_KEY,
    JSON.stringify(
      playerData
    )
  );



  console.log(
    "Player save updated:",
    playerData
  );


}


// =========================================================
// CREATE INVENTORY ITEM ID
// =========================================================

function createInventoryItemId(
  itemName
) {


  return String(
    itemName
  )
    .toLowerCase()
    .trim()

    // =========================================
    // REMOVE APOSTROPHES
    // Captain's becomes Captains
    // =========================================

    .replace(
      /['’]/g,
      ""
    )

    // =========================================
    // CONVERT SPACES / SYMBOLS
    // TO UNDERSCORES
    // =========================================

    .replace(
      /[^a-z0-9]+/g,
      "_"
    )

    // =========================================
    // REMOVE OUTER UNDERSCORES
    // =========================================

    .replace(
      /^_+|_+$/g,
      ""
    );

}


// =========================================================
// ADD ITEM TO INVENTORY
// =========================================================

function addItemToInventory(
  item
) {


  if (
    !item ||
    !item.name
  ) {

    console.log(
      "Invalid inventory item:",
      item
    );


    return;

  }



  // =========================================
  // FIND ITEM DATABASE ENTRY
  // =========================================

  const generatedId =
    item.id ||
    createInventoryItemId(
      item.name
    );


  const definition =
    getItemDefinition(
      generatedId
    );



  // =========================================
  // BUILD INVENTORY ITEM DATA
  // =========================================

  const inventoryItemData = {

    id:
      generatedId,

    name:
      definition
        ? definition.name
        : item.name,

    type:
      definition
        ? definition.type
        : "misc",

    rarity:
      definition
        ? definition.rarity
        : (
            item.rarity ||
            "Common"
          ),

    stackable:
      definition
        ? definition.stackable
        : true

  };



  // =========================================
  // STACKABLE ITEMS
  // =========================================

  if (
    inventoryItemData.stackable
  ) {


    const existingItem =
      playerData.inventory.find(
        inventoryItem =>
          inventoryItem.id ===
          inventoryItemData.id
      );


    if (existingItem) {


      existingItem.quantity =
        (
          existingItem.quantity ||
          0
        ) +
        1;


      console.log(
        `${inventoryItemData.name} increased to ×${existingItem.quantity}`
      );


      return;

    }

  }



  // =========================================
  // CREATE NEW INVENTORY ENTRY
  // =========================================

  const newInventoryItem = {

    id:
      inventoryItemData.id,

    name:
      inventoryItemData.name,

    type:
      inventoryItemData.type,

    rarity:
      inventoryItemData.rarity,

    quantity:
      1

  };



  // =========================================
  // NON-STACKABLE ITEM INSTANCE
  // =========================================

  if (
    !inventoryItemData.stackable
  ) {


    newInventoryItem.instanceId =
      `${inventoryItemData.id}_${Date.now()}_${Math.floor(
        Math.random() *
        100000
      )}`;

  }



  // =========================================
  // EQUIPMENT DATA
  // =========================================

  if (
    definition &&
    definition.type ===
      "weapon"
  ) {


    newInventoryItem.weaponClass =
      definition.weaponClass;


    newInventoryItem.equipmentSlot =
      definition.equipmentSlot;


    newInventoryItem.equippedBy =
      null;

  }



  playerData.inventory.push(
    newInventoryItem
  );


  console.log(
    `New item obtained: ${newInventoryItem.name}`
  );

}


// =========================================================
// BRICK 340 — INVENTORY STACK QUANTITY AUTHORITY
// =========================================================
//
// Battle Items consume the real persistent Inventory stack.
// No Battle-only quantity copy exists.
//
// =========================================================

function getInventoryStackByItemId(
  itemId
) {


  if (
    !itemId ||
    !playerData ||
    !Array.isArray(
      playerData.inventory
    )
  ) {

    return null;
  }


  return (
    playerData.inventory.find(
      item =>
        item &&
        item.id ===
          itemId &&
        !item.instanceId
    ) ||
    null
  );
}


function getInventoryStackQuantity(
  itemId
) {


  const stack =
    getInventoryStackByItemId(
      itemId
    );


  return stack
    ? Math.max(
        0,
        Math.floor(
          Number(
            stack.quantity
          ) || 0
        )
      )
    : 0;
}


function consumeInventoryStackQuantity(
  itemId,
  amount = 1
) {


  const definition =
    getItemDefinition(
      itemId
    );


  const stack =
    getInventoryStackByItemId(
      itemId
    );


  const quantity =
    Math.max(
      1,
      Math.floor(
        Number(
          amount
        ) || 1
      )
    );


  if (
    !definition ||
    definition.stackable !==
      true ||
    !stack
  ) {

    return {

      success:
        false,

      reason:
        "inventory_stack_unavailable"

    };
  }


  const before =
    getInventoryStackQuantity(
      itemId
    );


  if (
    before <
      quantity
  ) {

    return {

      success:
        false,

      reason:
        "insufficient_inventory_quantity",

      quantityBefore:
        before

    };
  }


  stack.quantity =
    before -
    quantity;


  return {

    success:
      true,

    itemId:
      itemId,

    quantityBefore:
      before,

    quantityAfter:
      stack.quantity

  };
}


function restoreInventoryStackQuantity(
  itemId,
  amount = 1
) {


  const stack =
    getInventoryStackByItemId(
      itemId
    );


  if (
    !stack
  ) {

    return false;
  }


  const quantity =
    Math.max(
      1,
      Math.floor(
        Number(
          amount
        ) || 1
      )
    );


  stack.quantity =
    getInventoryStackQuantity(
      itemId
    ) +
    quantity;


  return true;
}


// =========================================================
// BRICK 157 — BATTLE CHRONICLE RESULT
// BRICK 611 — STABLE ENCOUNTER-ENEMY CHRONICLE AUTHORITY
// BRICK 642 — ACTIVE KONOHA OCCURRENCE SCOPE
// =========================================================
//
// Converts completed Battle state into
// Chronicle-compatible history data.
//
// =========================================================


function createBattleChronicleResult() {


  const encounterEnemy=
    getBattleEncounterEnemy();


  if (
    !currentBattle ||
    !encounterEnemy ||
    !currentBattle.rewards ||
    currentBattle.battleOver !==
      true
  ) {


    return null;


  }


  const rewards =
    currentBattle.rewards;


  const itemRewards = [

    ...(
      Array.isArray(
        rewards.items
      )
        ? rewards.items
        : []
    ),

    ...(
      Array.isArray(
        rewards.rareDrops
      )
        ? rewards.rareDrops
        : []
    )

  ].map(
    item => ({


      id:
        item.id ||
        createInventoryItemId(
          item.name
        ),


      name:
        item.name,


      rarity:
        item.rarity ||
        "Common",


      amount:
        1


    })
  );


  return {


    historyScope:
      getCurrentChronicleOccurrenceHistoryScope("battle"),


    type:
      "battle",


    battleId:
      currentBattle.battleId,


    activity:
      "battle",


    encounterId:
      currentBattle.encounterId,


    enemyId:
      encounterEnemy.id,


    enemyName:
      encounterEnemy.name,


    character:
      currentBattle.characterId,


    success:
      true,


    finishingShinobi:
      rewards.finishingShinobi ||
      null,


    mvp:
      rewards.mvp
        ? {
            ...rewards.mvp
          }
        : null,


    rewards: {


      exp:
        Number(
          rewards.exp
        ) || 0,


      ryo:
        Number(
          rewards.ryo
        ) || 0,


      items:
        itemRewards,


      progression:
        []


    },


    timestamp:
      currentBattle.completedAt ||
      Date.now()


  };


}

// =========================================================
// BRICK 158 — BATTLE CHRONICLE RECORD
// =========================================================
//
// Persists one completed Battle exactly once.
//
// =========================================================


function recordBattleChronicle() {


  const result =
    createBattleChronicleResult();


  if (
    !result ||
    !result.battleId
  ) {


    console.log(
      "Battle Chronicle result unavailable."
    );


    return false;


  }


  const duplicate =
    getActivityHistory()
      .some(
        entry =>
          entry &&
          entry.type ===
            "battle" &&
          entry.battleId ===
            result.battleId
      );


  if (
    duplicate ||
    currentBattle.completionRecorded ===
      true
  ) {


    console.log(
      "Battle Chronicle already recorded:",
      result.battleId
    );


    currentBattle.completionRecorded =
      true;


    return true;


  }


  activityHistory.push(
    result
  );


  currentBattle.completionRecorded =
    true;


  syncActivityHistory();


  console.log(
    "Battle Chronicle recorded:",
    result
  );


  return true;


}

// =========================================================
// BRICK 159 — ENCOUNTER-AWARE BATTLE REWARD CLAIM
// =========================================================
//
// Canonical Battle victory payout.
//
// Handles:
//
// - Duplicate claim protection
// - Ryō
// - EXP
// - Common items
// - Rare items
// - Battle Chronicle
// - Persistence
//
// =========================================================


function claimCurrentBattleRewards() {


  const rewards =
    currentBattle.rewards;


  if (
    !rewards ||
    !rewards.generated
  ) {


    console.log(
      "No battle rewards available to claim."
    );


    return false;


  }


  if (
    rewards.claimed ===
      true
  ) {


    console.log(
      "Battle rewards have already been claimed."
    );


    return false;


  }


  // =========================================
  // RYO
  // =========================================


  playerData.ryo +=
    Number(
      rewards.ryo
    ) || 0;


  // =========================================
  // EXP
  // =========================================


  playerData.exp +=
    Number(
      rewards.exp
    ) || 0;


  // =========================================
  // COMMON ITEMS
  // =========================================


  if (
    Array.isArray(
      rewards.items
    )
  ) {


    rewards.items.forEach(
      item => {


        addItemToInventory(
          item
        );


      }
    );


  }


  // =========================================
  // RARE ITEMS
  // =========================================


  if (
    Array.isArray(
      rewards.rareDrops
    )
  ) {


    rewards.rareDrops.forEach(
      item => {


        addItemToInventory(
          item
        );


      }
    );


  }


  // =========================================
  // CLAIM STATE
  // =========================================


  rewards.claimed =
    true;


  currentBattle.claimedAt =
    Date.now();


  // =========================================
  // CHRONICLE
  // =========================================


  const chronicleRecorded =
    recordBattleChronicle();


  if (
    !chronicleRecorded
  ) {


    console.warn(
      "Battle rewards claimed but Chronicle recording failed."
    );


  }


  // =========================================
  // SAVE
  // =========================================


  savePlayerData();
  saveTestState();


  console.log(
    "================================="
  );


  console.log(
    "BATTLE REWARDS CLAIMED"
  );


  console.log(
    `Ryō: ${playerData.ryo}`
  );


  console.log(
    `EXP: ${playerData.exp}`
  );


  console.log(
    "Battle Chronicle:",
    chronicleRecorded
  );


  console.log(
    "================================="
  );


  return true;


}


// =========================================================
// PLAYER EQUIPMENT SYSTEM
// =========================================================

function getPlayerCharacter(
  characterId
) {


  return (
    playerTeam.find(
      character =>
        character.id ===
        characterId
    ) ||
    null
  );

}



// =========================================================
// BRICK 849 — EXACT-INSTANCE PLAYER EQUIP SELECTION
// BRICK 850 — BATTLE-TIME EQUIPMENT MUTATION LOCK
// =========================================================

function isEquipmentMutationLockedByBattle() {
  return !!(
    typeof currentBattle!=="undefined" &&
    currentBattle &&
    currentBattle.active===true &&
    currentBattle.battleOver!==true
  );
}

function findAvailableEquipment(instanceId) {
  if (!instanceId || !playerData || !Array.isArray(playerData.inventory)) return null;
  return playerData.inventory.find(item=>
    item &&
    item.instanceId===instanceId &&
    item.type==="weapon" &&
    !item.equippedBy
  ) || null;
}

function getAvailableEquipmentInstancesByItemId(itemId) {
  if (!itemId || !playerData || !Array.isArray(playerData.inventory)) return [];
  return playerData.inventory.filter(item=>
    item &&
    item.id===itemId &&
    item.type==="weapon" &&
    !!item.instanceId &&
    !item.equippedBy
  );
}

function equipItemToCharacter(instanceId, characterId) {
  if (isEquipmentMutationLockedByBattle()) {
    console.log("Equipment cannot be changed during an active unresolved Battle.");
    return false;
  }

  const character=getPlayerCharacter(characterId);
  if (!character) {
    console.log("Character not found:",characterId);
    return false;
  }

  const item=findAvailableEquipment(instanceId);
  if (!item) {
    console.log("No unequipped weapon instance available:",instanceId);
    return false;
  }

  const definition=getItemDefinition(item.id);
  if (!definition || definition.type!=="weapon" || definition.equipmentSlot!=="weapon") {
    console.log("Item cannot be equipped:",item.name);
    return false;
  }

  if (!Array.isArray(character.equipment)) character.equipment=[];

  // Alpha owns one weapon slot. Replacement is never implicit.
  const existingWeapon=character.equipment.find(equipment=>equipment&&equipment.slot==="weapon")||null;
  if (existingWeapon) {
    console.log(`${character.name} already has a weapon equipped.`);
    console.log("Unequip the current weapon first.");
    return false;
  }

  // Exact inventory instance is the equip identity. An itemId is not sufficient.
  if (!item.instanceId || item.instanceId!==instanceId || item.equippedBy) return false;

  item.equippedBy=character.id;
  character.equipment.push({instanceId:item.instanceId,itemId:item.id,slot:"weapon"});
  savePlayerData();
  console.log(`${item.name} equipped by ${character.name}.`);
  return true;
}

function unequipCharacterWeapon(characterId) {
  if (isEquipmentMutationLockedByBattle()) {
    console.log("Equipment cannot be changed during an active unresolved Battle.");
    return false;
  }

  const character=getPlayerCharacter(characterId);
  if (!character) {
    console.log("Character not found:",characterId);
    return false;
  }
  if (!Array.isArray(character.equipment)||character.equipment.length===0) {
    console.log(`${character.name} has no equipment.`);
    return false;
  }

  const equippedWeapon=character.equipment.find(equipment=>equipment&&equipment.slot==="weapon")||null;
  if (!equippedWeapon) {
    console.log(`${character.name} has no weapon equipped.`);
    return false;
  }

  const inventoryItem=playerData.inventory.find(item=>item&&item.instanceId===equippedWeapon.instanceId)||null;
  if (inventoryItem) inventoryItem.equippedBy=null;
  character.equipment=character.equipment.filter(equipment=>equipment&&equipment.instanceId!==equippedWeapon.instanceId);
  savePlayerData();
  console.log(`${character.name}'s weapon has been unequipped.`);
  return true;
}


// =========================================================
// RESTORE EQUIPMENT FROM PLAYER SAVE
// =========================================================

function syncCharacterEquipmentFromSave() {


  // =========================================
  // CLEAR RUNTIME EQUIPMENT
  // =========================================

  playerTeam.forEach(
    character => {

      character.equipment =
        [];

    }
  );


  if (
    !Array.isArray(
      playerData.inventory
    )
  ) {

    playerData.inventory =
      [];

  }


  const usedInstanceIds =
    new Set();


  const occupiedSlots =
    new Set();


  let repairedSave =
    false;


  // =========================================
  // VALIDATE + RESTORE SAVED EQUIPMENT
  // =========================================

  playerData.inventory.forEach(
    item => {


      if (
        !item ||
        item.type !==
          "weapon"
      ) {

        return;

      }


      if (!item.equippedBy) {

        return;

      }


      // =========================================
      // VALID CHARACTER
      // =========================================

      const character =
        getPlayerCharacter(
          item.equippedBy
        );


      if (!character) {


        console.warn(
          "Invalid equipped character removed:",
          item.equippedBy,
          item.name
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // VALID ITEM DEFINITION
      // =========================================

      const definition =
        getItemDefinition(
          item.id
        );


      if (
        !definition ||
        definition.type !==
          "weapon"
      ) {


        console.warn(
          "Invalid equipped weapon definition:",
          item.id
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // VALID INSTANCE ID
      // =========================================

      if (!item.instanceId) {


        console.warn(
          "Equipped weapon missing instanceId:",
          item.name
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // DUPLICATE INSTANCE PROTECTION
      // =========================================

      if (
        usedInstanceIds.has(
          item.instanceId
        )
      ) {


        console.warn(
          "Duplicate equipped item instance removed:",
          item.instanceId
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      const slot =
        definition.equipmentSlot ||
        item.equipmentSlot ||
        "weapon";


      const slotKey =
        `${character.id}:${slot}`;


      // =========================================
      // ONE ITEM PER SLOT
      // =========================================

      if (
        occupiedSlots.has(
          slotKey
        )
      ) {


        console.warn(
          `${character.name} had multiple items in ${slot}. Extra item unequipped:`,
          item.name
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // NORMALIZE INVENTORY EQUIPMENT DATA
      // =========================================

      item.weaponClass =
        definition.weaponClass;


      item.equipmentSlot =
        slot;


      // =========================================
      // RESTORE RUNTIME EQUIPMENT
      // =========================================

      character.equipment.push({

        instanceId:
          item.instanceId,

        itemId:
          item.id,

        slot:
          slot

      });


      usedInstanceIds.add(
        item.instanceId
      );


      occupiedSlots.add(
        slotKey
      );

    }
  );


  // =========================================
  // RE-SAVE ONLY IF REPAIRS WERE REQUIRED
  // =========================================

  if (repairedSave) {


    console.warn(
      "Equipment save contained invalid data and was repaired."
    );


    savePlayerData();

  }


  console.log(
    "Character equipment restored."
  );

}


// =========================================================
// DEVELOPMENT EQUIPMENT VIEW
// =========================================================
//
// Equipment presentation uses Effective state.
//
// Current PL remains persistent progression.
// Effective PL reflects equipment and other contextual
// stat effects.
//
// =========================================================

function showEquipmentData() {


  const equipmentView =
    playerTeam.map(
      character => {


        const weapon =
          character.equipment.find(
            equipment =>
              equipment.slot ===
              "weapon"
          );


        const inventoryItem =
          weapon
            ? playerData.inventory.find(
                item =>
                  item.instanceId ===
                  weapon.instanceId
              )
            : null;


        const definition =
          inventoryItem
            ? getItemDefinition(
                inventoryItem.id
              )
            : null;


        const rawBonuses =
          getRawEquipmentStatBonuses(
            character
          );


        const naturalProficiency =
          getNaturalWeaponProficiency(
            character
          );


        const activeProficiency =
          getWeaponProficiency(
            character
          );


        const signatureMultiplier =
          getSignatureWeaponAffinityMultiplier(
            character,
            definition
          );


        const finalBonuses =
          getEquipmentStatBonuses(
            character
          );


        const effectiveStats =
          getDevelopedEffectiveCharacterStats(
            character
          );


        return {

          character:
            character.name,

          weapon:
            inventoryItem
              ? inventoryItem.name
              : "—",

          weaponClass:
            definition &&
            definition.weaponClass
              ? definition.weaponClass
              : "—",

          naturalBuki:
            character.stats.buki,

          rawBukiBonus:
            rawBonuses.buki,

          naturalTier:
            naturalProficiency.name,

          activeTier:
            activeProficiency.name,

          activeScore:
            activeProficiency.proficiencyBuki,

          proficiencyMult:
            `${activeProficiency.multiplier.toFixed(
              2
            )}x`,

          signatureMult:
            `${signatureMultiplier.toFixed(
              2
            )}x`,

          finalBukiBonus:
            finalBonuses.buki,

          effectiveBuki:
            effectiveStats.buki,

          currentPL:
            calculateCurrentPL(
              character
            ),

          effectivePL:
            calculateEffectivePL(
              character
            )

        };

      }
    );


  console.table(
    equipmentView
  );

}


// =========================================================
// EQUIPMENT PHASE DIAGNOSTICS
// =========================================================

function runEquipmentPhaseDiagnostics() {


  console.log(
    "========================================"
  );


  console.log(
    "SHINOBI CHRONICLES — EQUIPMENT DIAGNOSTICS"
  );


  console.log(
    "========================================"
  );


  const results =
    [];


  // =========================================
  // PLAYER SAVE STRUCTURE
  // =========================================

  results.push({

    test:
      "Inventory exists",

    pass:
      Array.isArray(
        playerData.inventory
      )

  });


  results.push({

    test:
      "Character progression exists",

    pass:
      !!(
        playerData.characters &&
        typeof playerData.characters ===
          "object"
      )

  });


  // =========================================
  // INVENTORY INTEGRITY
  // =========================================

  const instanceIds =
    new Set();


  let duplicateInstanceIds =
    false;


  let invalidEquippedCharacter =
    false;


  let invalidEquippedDefinition =
    false;


  playerData.inventory.forEach(
    item => {


      if (
        item.instanceId
      ) {


        if (
          instanceIds.has(
            item.instanceId
          )
        ) {

          duplicateInstanceIds =
            true;

        }


        instanceIds.add(
          item.instanceId
        );

      }


      if (
        item.equippedBy &&
        !getPlayerCharacter(
          item.equippedBy
        )
      ) {

        invalidEquippedCharacter =
          true;

      }


      if (
        item.equippedBy &&
        !getItemDefinition(
          item.id
        )
      ) {

        invalidEquippedDefinition =
          true;

      }

    }
  );


  results.push({

    test:
      "No duplicate item instances",

    pass:
      !duplicateInstanceIds

  });


  results.push({

    test:
      "No invalid equipped character IDs",

    pass:
      !invalidEquippedCharacter

  });


  results.push({

    test:
      "No missing equipped item definitions",

    pass:
      !invalidEquippedDefinition

  });


  // =========================================
  // CHARACTER EQUIPMENT INTEGRITY
  // =========================================

  let duplicateSlots =
    false;


  let invalidRuntimeEquipment =
    false;


  playerTeam.forEach(
    character => {


      const slots =
        new Set();


      character.equipment.forEach(
        equipment => {


          if (
            slots.has(
              equipment.slot
            )
          ) {

            duplicateSlots =
              true;

          }


          slots.add(
            equipment.slot
          );


          const inventoryItem =
            playerData.inventory.find(
              item =>
                item.instanceId ===
                equipment.instanceId
            );


          if (
            !inventoryItem ||
            inventoryItem.equippedBy !==
              character.id
          ) {

            invalidRuntimeEquipment =
              true;

          }

        }
      );

    }
  );


  results.push({

    test:
      "No duplicate character equipment slots",

    pass:
      !duplicateSlots

  });


  results.push({

    test:
      "Runtime equipment matches inventory",

    pass:
      !invalidRuntimeEquipment

  });


  // =========================================
  // CALCULATION HEALTH
  // =========================================

  let validEffectiveStats =
    true;


  let validPowerLevels =
    true;


  let validProficiencies =
    true;


  playerTeam.forEach(
    character => {


      const effectiveStats =
        getEffectiveCharacterStats(
          character
        );


      Object.values(
        effectiveStats
      ).forEach(
        value => {


          if (
            !Number.isFinite(
              Number(value)
            )
          ) {

            validEffectiveStats =
              false;

          }

        }
      );


      const pl =
        calculateCurrentPL(
          character
        );


      if (
        !Number.isFinite(
          pl
        )
      ) {

        validPowerLevels =
          false;

      }


      const proficiency =
        getWeaponProficiency(
          character
        );


      if (
        !Number.isFinite(
          proficiency.multiplier
        ) ||
        !Number.isFinite(
          proficiency.proficiencyBuki
        )
      ) {

        validProficiencies =
          false;

      }

    }
  );


  results.push({

    test:
      "Effective stats are valid",

    pass:
      validEffectiveStats

  });


  results.push({

    test:
      "Power levels are valid",

    pass:
      validPowerLevels

  });


  results.push({

    test:
      "Weapon proficiency is valid",

    pass:
      validProficiencies

  });


  // =========================================
  // SPECIALIZATION SAVE HEALTH
  // =========================================

  let specializationDataValid =
    true;


  playerTeam.forEach(
    character => {


      const specializations =
        character.weaponSpecializations ||
        {};


      Object.values(
        specializations
      ).forEach(
        specialization => {


          const normalized =
            normalizeWeaponSpecializationRecord(
              specialization
            );


          if (
            !Number.isFinite(
              normalized.level
            ) ||
            !Number.isFinite(
              normalized.exp
            )
          ) {

            specializationDataValid =
              false;

          }

        }
      );

    }
  );


  results.push({

    test:
      "Weapon specialization data valid",

    pass:
      specializationDataValid

  });


  // =========================================
  // DISPLAY RESULTS
  // =========================================

  console.table(
    results
  );


  const failedTests =
    results.filter(
      result =>
        !result.pass
    );


  if (
    failedTests.length ===
      0
  ) {


    console.log(
      "✅ EQUIPMENT PHASE PASSED ALL DIAGNOSTICS"
    );

  }
  else {


    console.warn(
      `❌ EQUIPMENT PHASE HAS ${failedTests.length} FAILED TEST(S)`
    );


    console.table(
      failedTests
    );

  }


  console.log(
    "========================================"
  );


  showEquipmentData();


  return (
    failedTests.length ===
    0
  );

}


// =========================================================
// DISCIPLINE EXP REQUIREMENT
// =========================================================

function getDisciplineExpRequired(
  level
) {


  const safeLevel =
    Math.max(
      1,
      Math.floor(
        Number(level) || 1
      )
    );


  return (
    50 +
    (
      safeLevel - 1
    ) * 25
  );

}


// =========================================================
// GET CHARACTER DISCIPLINE PROGRESSION
// =========================================================

function getCharacterDisciplineProgression(
  characterId,
  disciplineId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return null;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return null;

  }


  character.disciplineProgression =
    normalizeDisciplineProgression(
      character
        .disciplineProgression
    );


  return (
    character
      .disciplineProgression[
        disciplineId
      ]
  );

}


// =========================================================
// GET DISCIPLINE STAT GAIN PER LEVEL
// =========================================================

function getDisciplineStatGainPerLevel(
  disciplineId
) {


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {

    return 0;

  }


  // =========================================
  // CURRENT BALANCE RULE
  // =========================================
  //
  // Every discipline training level gained
  // permanently increases its natural stat
  // by +1.
  //
  // This helper exists so balancing can be
  // changed later in one place.
  //
  // =========================================

  return 1;

}


// =========================================================
// APPLY PENDING DISCIPLINE STAT GROWTH
// =========================================================

function applyPendingDisciplineStatGrowth(
  characterId,
  disciplineId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return null;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return null;

  }


  const progression =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  if (!progression) {

    return null;

  }


  if (
    !Number.isFinite(
      Number(
        progression.statLevelApplied
      )
    )
  ) {

    progression.statLevelApplied =
      1;

  }


  let statPointsGained =
    0;


  const statGainPerLevel =
    getDisciplineStatGainPerLevel(
      disciplineId
    );


  while (
    progression.statLevelApplied <
      progression.level
  ) {


    progression.statLevelApplied +=
      1;


    character.stats[
      disciplineId
    ] =
      (
        Number(
          character.stats[
            disciplineId
          ]
        ) || 0
      ) +
      statGainPerLevel;


    statPointsGained +=
      statGainPerLevel;

  }


  if (
    statPointsGained >
      0
  ) {


    console.log(
      `${character.name} gained +${statPointsGained} permanent ${discipline.name}.`
    );

  }


  return {

    statPointsGained:
      statPointsGained,

    stat:
      character.stats[
        disciplineId
      ],

    statLevelApplied:
      progression.statLevelApplied

  };

}


// =========================================================
// PROCESS DISCIPLINE LEVEL UPS
// =========================================================

function processDisciplineLevelUps(
  characterId,
  disciplineId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return null;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return null;

  }


  const progression =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  if (!progression) {

    return null;

  }


  let levelsGained =
    0;


  let expRequired =
    getDisciplineExpRequired(
      progression.level
    );


  while (
    progression.exp >=
      expRequired
  ) {


    progression.exp -=
      expRequired;


    progression.level +=
      1;


    levelsGained +=
      1;


    console.log(
      `${character.name}'s ${discipline.name} Training reached Level ${progression.level}!`
    );


    expRequired =
      getDisciplineExpRequired(
        progression.level
      );

  }


  const statGrowth =
    applyPendingDisciplineStatGrowth(
      characterId,
      disciplineId
    );


  return {

    levelsGained:
      levelsGained,

    level:
      progression.level,

    exp:
      progression.exp,

    expToNext:
      getDisciplineExpRequired(
        progression.level
      ),

    statPointsGained:
      statGrowth
        ? statGrowth.statPointsGained
        : 0,

    stat:
      character.stats[
        disciplineId
      ]

  };

}


// =========================================================
// VALIDATE DISCIPLINE TRAINING SOURCE
// =========================================================

function isValidDisciplineTrainingSource(
  disciplineId,
  source
) {


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {

    return false;

  }


  return (
    discipline.trainingSource ===
    source
  );

}

// =========================================================
// BRICK 128 — PLAYER LOOP ACTIVITY TYPES
// =========================================================
//
// Aligns Player Loop requests with
// the canonical Activity Engine.
//
// Handles:
// - Practical training
// - Exams
// - Missions
// - Battles
//
// =========================================================


const PLAYER_ACTIVITY_TYPES = {


  TRAINING:
    "training",


  PRACTICAL:
    "practical",


  BATTLE:
    "battle",


  MISSION:
    "mission",


  EXAM:
    "exam"


};


// =========================================================
// BRICK 129 — EXECUTE PLAYER ACTIVITY
// =========================================================
//
// Entry point for Player Loop activity requests.
//
// Delegates execution to the canonical
// Activity Engine.
//
// =========================================================


function executePlayerActivity(
  activityRequest
) {


  if (
    !activityRequest ||
    typeof activityRequest !==
      "object"
  ) {


    console.log(
      "Invalid player activity request."
    );


    return false;


  }



  if (
    !Object.values(
      PLAYER_ACTIVITY_TYPES
    ).includes(
      activityRequest.type
    )
  ) {


    console.log(
      "Unknown player activity:",
      activityRequest.type
    );


    return false;


  }



  console.log(
    "PLAYER ACTIVITY START:",
    activityRequest
  );



  const result =
    processPlayerActivity(
      activityRequest
    );



  if (
    !result
  ) {


    console.log(
      "Player activity failed."
    );


    return false;


  }



  console.log(
    "PLAYER ACTIVITY COMPLETE:",
    result
  );



  return result;


}

// =========================================================
// BRICK 130 — PROCESS PLAYER ACTIVITY
// BRICK 311 — BATTLE ACTIVITY PHASE BOUNDARY
// BRICK 555 — MISSION ACTIVITY PHASE BOUNDARY
// =========================================================
//
// Routes Player Loop requests into
// the registered Activity Engine.
//
// Location/opportunity availability and actual completion are
// explicitly different lifecycle phases for Battle and Mission.
//
// Merely entering a Battle or Mission location must NEVER
// execute completion rewards / progression / history.
//
// =========================================================

function processPlayerActivity(
  activityRequest
) {


  switch (
    activityRequest.type
  ) {


    // =========================================
    // TRAINING UI AVAILABILITY REQUEST
    // =========================================

    case PLAYER_ACTIVITY_TYPES.TRAINING:


      if (
        activityRequest.stage ===
          "available"
      ) {


        return {

          success:
            true,

          type:
            "training_available",

          location:
            activityRequest.location ||
            null,

          activityId:
            activityRequest.activityId ||
            null,

          message:
            "Training opportunity available."

        };
      }


      console.log(
        "Direct legacy training execution is disabled."
      );


      return false;


    // =========================================
    // PRACTICAL
    // =========================================

    case PLAYER_ACTIVITY_TYPES.PRACTICAL:


      return startRegisteredActivity(
        "practical",
        activityRequest.characterId
      );


    // =========================================
    // BATTLE
    // =========================================

    case PLAYER_ACTIVITY_TYPES.BATTLE:


      // =======================================
      // LOCATION / OPPORTUNITY PHASE
      // =======================================

      if (
        activityRequest.stage ===
          "available"
      ) {


        return {

          success:
            true,

          type:
            "battle_available",

          location:
            activityRequest.location ||
            null,

          encounterId:
            activityRequest.encounterId ||
            null,

          message:
            "Battle opportunity available."

        };
      }


      // =======================================
      // EXPLICIT COMPLETION PHASE ONLY
      // =======================================

      if (
        activityRequest.stage !==
          "completion"
      ) {


        console.log(
          "Battle Activity execution requires an explicit lifecycle stage."
        );


        return false;
      }


      if (
        !activityRequest.characterId
      ) {


        console.log(
          "Battle completion requires a character ID."
        );


        return false;
      }


      return startRegisteredActivity(
        "battle",
        activityRequest.characterId
      );


    // =========================================
    // MISSION
    // BRICK 555 — EXPLICIT MISSION LIFECYCLE
    // =========================================

    case PLAYER_ACTIVITY_TYPES.MISSION:


      // =======================================
      // LOCATION / OPPORTUNITY PHASE
      // =======================================

      if (
        activityRequest.stage ===
          "available"
      ) {


        return {

          success:
            true,

          type:
            "mission_available",

          location:
            activityRequest.location ||
            null,

          missionId:
            activityRequest.missionId ||
            null,

          message:
            "Mission opportunity available."

        };
      }


      // =======================================
      // EXPLICIT COMPLETION PHASE ONLY
      // =======================================

      if (
        activityRequest.stage !==
          "completion"
      ) {


        console.log(
          "Mission Activity execution requires an explicit lifecycle stage."
        );


        return false;
      }


      if (
        !activityRequest.characterId
      ) {


        console.log(
          "Mission completion requires a character ID."
        );


        return false;
      }


      return startRegisteredActivity(
        "mission",
        activityRequest.characterId
      );


    // =========================================
    // EXAM
    // =========================================

    case PLAYER_ACTIVITY_TYPES.EXAM:


      return startRegisteredActivity(
        "exam",
        activityRequest.characterId
      );


    default:


      console.log(
        "Unknown activity type:",
        activityRequest.type
      );


      return false;

  }

}

// =========================================================
// BRICK 313 — BATTLE ACTIVITY BOUNDARY DIAGNOSTIC
// =========================================================

function runBattleActivityBoundaryDiagnostics() {


  const availability =
    processPlayerActivity({

      type:
        PLAYER_ACTIVITY_TYPES.BATTLE,

      stage:
        "available",

      location:
        "diagnostic_location"

    });


  const invalidCompletion =
    processPlayerActivity({

      type:
        PLAYER_ACTIVITY_TYPES.BATTLE,

      stage:
        "completion"

    });


  const battleActivity =
    getActivityData(
      "battle"
    );


  const result = {


    availabilityAccepted:
      !!(
        availability &&
        availability.success ===
          true
      ),


    availabilityIsNotCompletion:
      !!(
        availability &&
        availability.type ===
          "battle_available"
      ),


    completionWithoutCharacterRejected:
      invalidCompletion ===
        false,


    registeredBattleStillExists:
      !!battleActivity,


    registeredBattleNotAutoExecuted:
      !!(
        availability &&
        availability.type !==
          "battle"
      )

  };


  result.pass =
    Object.values(
      result
    ).every(
      value =>
        value ===
        true
    );


  console.table(
    result
  );


  return result;
}



// =========================================================
// ADD DISCIPLINE EXP
// =========================================================

function addDisciplineExp(
  characterId,
  disciplineId,
  amount,
  source
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return false;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return false;

  }


  if (
    !isValidDisciplineTrainingSource(
      disciplineId,
      source
    )
  ) {


    console.log(
      `${discipline.name} EXP cannot be gained from ${source}.`
    );


    console.log(
      `Required source: ${discipline.trainingSource}`
    );


    return false;

  }


  const expAmount =
    Math.floor(
      Number(amount)
    );


  if (
    !Number.isFinite(
      expAmount
    ) ||
    expAmount <= 0
  ) {


    console.log(
      "Invalid discipline EXP amount:",
      amount
    );


    return false;

  }


  const progression =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  if (!progression) {

    return false;

  }


  // =========================================
  // AWARD EXP
  // =========================================

  progression.exp +=
    expAmount;


  console.log(
    `${character.name} gained +${expAmount} ${discipline.name} EXP from ${source}.`
  );


  // =========================================
  // PROCESS LEVEL UPS + STAT GROWTH
  // =========================================

  const levelResult =
    processDisciplineLevelUps(
      characterId,
      disciplineId
    );


  if (!levelResult) {

    return false;

  }


  // =========================================
  // SAVE RESULT
  // =========================================

  savePlayerData();


  console.log(
    `${discipline.name} Training Level: ${levelResult.level}`
  );


  console.log(
    `${discipline.name} EXP: ${levelResult.exp} / ${levelResult.expToNext}`
  );


  if (
    levelResult.levelsGained >
      0
  ) {


    console.log(
      `${discipline.name} Levels Gained: +${levelResult.levelsGained}`
    );

  }


  if (
    levelResult.statPointsGained >
      0
  ) {


    console.log(
      `${discipline.name} Permanent Stat Gain: +${levelResult.statPointsGained}`
    );

  }


  return true;

}


// =========================================================
// BRICK 20 — SHINOBI DISCIPLINE DIAGNOSTICS
// =========================================================

function runDisciplinePhaseDiagnostics() {


  console.log(
    "========================================"
  );


  console.log(
    "SHINOBI CHRONICLES — DISCIPLINE DIAGNOSTICS"
  );


  console.log(
    "========================================"
  );


  const results =
    [];


  const expectedDisciplines = [
    "nin",
    "tai",
    "buki",
    "fuin",
    "kin",
    "gen",
    "stamina"
  ];


  // =========================================
  // DISCIPLINE DEFINITIONS EXIST
  // =========================================

  const allDisciplinesExist =
    expectedDisciplines.every(
      disciplineId =>
        !!getShinobiDiscipline(
          disciplineId
        )
    );


  results.push({

    test:
      "All seven disciplines exist",

    pass:
      allDisciplinesExist

  });


  // =========================================
  // CORRECT TRAINING SOURCES
  // =========================================

  const expectedSources = {

    nin:
      "exam",

    tai:
      "practical",

    buki:
      "practical",

    fuin:
      "exam",

    kin:
      "battle",

    gen:
      "exam",

    stamina:
      "practical"

  };


  const validSources =
    expectedDisciplines.every(
      disciplineId => {


        const definition =
          getShinobiDiscipline(
            disciplineId
          );


        return (
          definition &&
          definition.trainingSource ===
            expectedSources[
              disciplineId
            ]
        );

      }
    );


  results.push({

    test:
      "Training sources are correct",

    pass:
      validSources

  });


  // =========================================
  // KINJUTSU BATTLE ONLY
  // =========================================

  results.push({

    test:
      "Kinjutsu is battle-only",

    pass:
      (
        isValidDisciplineTrainingSource(
          "kin",
          "battle"
        ) === true &&
        isValidDisciplineTrainingSource(
          "kin",
          "exam"
        ) === false &&
        isValidDisciplineTrainingSource(
          "kin",
          "practical"
        ) === false
      )

  });


  // =========================================
  // CHARACTER DISCIPLINE HEALTH
  // =========================================

  let progressionValid =
    true;


  let runtimeSaveMatch =
    true;


  let statsValid =
    true;


  playerTeam.forEach(
    character => {


      const runtimeProgression =
        normalizeDisciplineProgression(
          character
            .disciplineProgression
        );


      const savedCharacter =
        playerData.characters &&
        playerData.characters[
          character.id
        ];


      const savedProgression =
        savedCharacter
          ? normalizeDisciplineProgression(
              savedCharacter
                .disciplineProgression
            )
          : null;


      expectedDisciplines.forEach(
        disciplineId => {


          const record =
            runtimeProgression[
              disciplineId
            ];


          if (
            !record ||
            !Number.isFinite(
              Number(
                record.level
              )
            ) ||
            record.level < 1 ||
            !Number.isFinite(
              Number(
                record.exp
              )
            ) ||
            record.exp < 0 ||
            !Number.isFinite(
              Number(
                record.statLevelApplied
              )
            ) ||
            record.statLevelApplied < 1 ||
            record.statLevelApplied >
              record.level
          ) {

            progressionValid =
              false;

          }


          if (
            !Number.isFinite(
              Number(
                character.stats[
                  disciplineId
                ]
              )
            )
          ) {

            statsValid =
              false;

          }


          if (
            !savedProgression ||
            JSON.stringify(
              runtimeProgression[
                disciplineId
              ]
            ) !==
            JSON.stringify(
              savedProgression[
                disciplineId
              ]
            )
          ) {

            runtimeSaveMatch =
              false;

          }

        }
      );

    }
  );


  results.push({

    test:
      "Discipline progression is valid",

    pass:
      progressionValid

  });


  results.push({

    test:
      "Permanent discipline stats are valid",

    pass:
      statsValid

  });


  results.push({

    test:
      "Runtime discipline data matches save",

    pass:
      runtimeSaveMatch

  });


  // =========================================
  // EXP CURVE HEALTH
  // =========================================

  let expCurveValid =
    true;


  for (
    let level = 1;
    level <= 100;
    level += 1
  ) {


    const required =
      getDisciplineExpRequired(
        level
      );


    if (
      !Number.isFinite(
        required
      ) ||
      required <= 0
    ) {

      expCurveValid =
        false;

      break;

    }

  }


  results.push({

    test:
      "Discipline EXP curve is valid",

    pass:
      expCurveValid

  });


  // =========================================
  // DISPLAY
  // =========================================

  console.table(
    results
  );


  const failedTests =
    results.filter(
      result =>
        !result.pass
    );


  if (
    failedTests.length ===
      0
  ) {


    console.log(
      "✅ DISCIPLINE PHASE PASSED ALL DIAGNOSTICS"
    );

  }
  else {


    console.warn(
      `❌ DISCIPLINE PHASE HAS ${failedTests.length} FAILED TEST(S)`
    );


    console.table(
      failedTests
    );

  }


  console.log(
    "========================================"
  );


  return (
    failedTests.length ===
    0
  );

}


