// =========================================================
// RUN ONE CHRONICLE REGRESSION SUITE
// =========================================================

function runChronicleRegressionSuite(
  suite
) {


  if (
    !suite ||
    typeof suite.runner !==
      "function"
  ) {


    return {

      id:
        suite &&
        suite.id

          ? suite.id

          : "unknown",

      name:
        suite &&
        suite.name

          ? suite.name

          : "Unknown Suite",

      pass:
        false,

      error:
        "Diagnostic runner does not exist."

    };

  }


  try {


    const result =
      suite.runner();


    return {

      id:
        suite.id,

      name:
        suite.name,

      pass:
        result ===
        true,

      error:
        null

    };

  }
  catch (error) {


    console.error(
      `❌ CHRONICLE REGRESSION SUITE CRASHED: ${suite.name}`,
      error
    );


    return {

      id:
        suite.id,

      name:
        suite.name,

      pass:
        false,

      error:
        error &&
        error.message

          ? error.message

          : String(
              error
            )

    };

  }

}


// =========================================================
// BUILD CHRONICLE REGRESSION SUMMARY ROW
// =========================================================

function buildChronicleRegressionSummaryRow(
  result
) {


  return {

    system:
      result.name,

    status:
      result.pass ===
        true

        ? "✅ PASS"

        : "❌ FAIL",

    error:
      result.error ||
      "—"

  };

}


// =========================================================
// BRICK 90 — MASTER REGRESSION
