// =========================================================
// BRICK 391 — OWNERSHIP / FORMATION-AWARE BATTLE LAUNCH
// BRICK 392 — SOURCE-PACKAGE RUNTIME INITIALIZATION
// BRICK 393 — ATTACHED-SUMMON RUNTIME SNAPSHOT
// BRICK 603 — PARTICIPANT-BACKED ENEMY LAUNCH
// =========================================================

function startEncounter(enemyId, characterId = null, encounterId = null, constructedOccurrence = null) {
  console.log("START ENCOUNTER FIRED:", enemyId);
  const occurrenceParticipant=constructedOccurrence&&constructedOccurrence.success===true&&constructedOccurrence.participant
    ? constructedOccurrence.participant
    : null;
  const enemy=occurrenceParticipant||enemyDatabase[enemyId];
  if (!enemy) { console.log("Enemy not found"); return false; }

  const formationValidation=validateCurrentClanFormationAgainstConstraint();
  if (!formationValidation.valid) {
    console.log("Current My Clan formation does not satisfy the active formation context:",formationValidation);
    return false;
  }

  const formationQueue=getPersistentClanBattleQueueSlots();
  const startCharacterId=formationQueue[0]||null;
  const activePlayer=startCharacterId?getPlayerCharacter(startCharacterId):null;
  if (!activePlayer) { console.log("No owned shinobi is assigned to My Clan START."); return false; }
  if (characterId&&characterId!==activePlayer.id) {
    console.log(`Battle launch character override "${characterId}" ignored; My Clan START "${activePlayer.id}" owns Current Actor order.`);
  }

  selectedEnemy=enemy;
  currentBattle.active=true;
  currentBattle.battleId=createBattleInstanceId();
  currentBattle.encounterId=encounterId;
  currentBattle.encounterOccurrenceId=constructedOccurrence&&constructedOccurrence.reservation?constructedOccurrence.reservation.occurrenceId:null;
  currentBattle.oppositionTemplateId=enemy.oppositionTemplateId||enemyId||enemy.id||null;
  currentBattle.encounterStatePackageId=enemy.encounterStatePackageId||null;
  currentBattle.characterId=activePlayer.id;
  currentBattle.encounterEnemy=enemy;
  setBattleEnemyParticipants([enemy]);
  currentBattle.enemy=enemy;
  currentBattle.deployment=createBattleDeployment(enemy);
  currentBattle.activePlayer=getBattleDeploymentParticipant("player",1)||activePlayer;
  syncBattleActiveEnemyFromDeployment();
  currentBattle.lastDamage=0;
  currentBattle.battleOver=false;
  currentBattle.completedAt=null;
  currentBattle.claimedAt=null;
  currentBattle.completionRecorded=false;
  currentBattle.outcome=null;
  currentBattle.defeat=null;
  // BRICK 738 — every ordinary Battle starts caller-neutral.
  // A story/event wrapper may attach a fresh returnContext immediately after launch.
  currentBattle.returnContext=null;
  currentBattle.observerSafeResultContext=null;
  currentBattle.unknownOperativeConfrontation=null;
  currentBattle.mission7SanitisationEncounter=null;
  currentBattle.battleLog=[`${enemy.name} appears!`,`${currentBattle.activePlayer.name} prepares for battle.`];

  initializeBattleContributionRecordsFromDeployment();
  currentBattle.rewards={generated:false,claimed:false,ryo:0,exp:0,items:[],rareDrops:[],finishingShinobi:null,mvp:null};
  const generatedBattlePower=calculateBattlePower(enemy,"standard");
  currentBattle.enemyPower=generatedBattlePower;
  currentBattle.enemyMaxPower=generatedBattlePower;

  initializeBattleSourcePackageRuntime();
  initializeBattleRemainingPLFromDeployment({preserveExistingEnemyPower:true});
  initializeBattlePouchFromPreparedSelection();
  initializeBattleAttachedSummonRuntimeFromDeployment();
  initializeBattleDedicatedVariantRuntimePackages();
  initializeBattleKisoganStartsActiveFromDeployment();

  if (encounterId&&currentBattle.encounterOccurrenceId) {
    markEncounterReservationStarted(encounterId,currentBattle.encounterOccurrenceId);
  }

  console.log("BATTLE INSTANCE CREATED:",currentBattle.battleId);
  console.log("CURRENT BATTLE:",currentBattle);
  openOverlay("combat");
  return currentBattle;
}

// =========================================================
// BRICK 318 — ACADEMY PILOT EQUIPMENT PREPARATION
// =========================================================
//
// Uses existing Inventory / Equipment authorities.
//
// Mirai equips one authoritative Kunai instance.
// Shuriken Set remains an available persistent weapon set.
// Ninja Wire remains an available persistent tool.
//
// =========================================================

function prepareAcademyPilotBattleEquipment() {


  grantAcademyPilotEquipmentPrerequisites();


  const mirai =
    getPlayerCharacter(
      "academy_mirai"
    );


  if (
    !mirai
  ) {

    console.log(
      "Academy Mirai is not registered."
    );


    return false;
  }


  const currentWeapon =
    getBattleEquippedWeaponExecutionContext(
      mirai
    );


  if (
    currentWeapon &&
    currentWeapon.weaponClass !==
      "Kunai"
  ) {


    const unequipped =
      unequipCharacterWeapon(
        mirai.id
      );


    if (
      !unequipped
    ) {

      return false;
    }
  }


  const refreshedWeapon =
    getBattleEquippedWeaponExecutionContext(
      mirai
    );


  if (
    !refreshedWeapon ||
    refreshedWeapon.weaponClass !==
      "Kunai"
  ) {


    const availableKunaiInstance =
      getAvailableEquipmentInstancesByItemId("kunai")[0] || null;

    const equipped =
      availableKunaiInstance
        ? equipItemToCharacter(
            availableKunaiInstance.instanceId,
            mirai.id
          )
        : false;


    if (
      !equipped
    ) {

      return false;
    }
  }


  savePlayerData();


  return {

    mirai:
      mirai,

    kunai:
      getBattleEquippedWeaponExecutionContext(
        mirai
      ),

    shuriken:
      getBattleAvailablePersistentThrowingWeaponContext(
        mirai,
        [
          "Shuriken"
        ]
      ),

    ninjaWire:
      getBattleInventoryToolContext(
        "ninja_wire"
      )

  };
}


// =========================================================
// BRICK 315 / 318 — LOAD ACADEMY PILOT INTO LIVE BATTLE
// BRICK 604 — PRESERVE PARTICIPANT-BACKED ENEMY DEPLOYMENT
// =========================================================
//
// IMPORTANT:
//
// This does NOT launch a Battle.
//
// Use the real world path:
// Land of Fire → Bandit Hideout → encounter.
//
// Once Combat is open, this function replaces only the
// Battle-local deployment snapshot with the Academy pilot.
//
// =========================================================

function loadAcademyPilotBattleDeployment() {


  if (
    !currentBattle.active ||
    currentBattle.battleOver ||
    !currentBattle.enemy
  ) {


    console.log(
      "Start a live Battle before loading the Academy pilot."
    );


    return false;
  }


  const participants =
    getAcademyBattlePilotParticipants();


  if (
    participants.length !==
      ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS.length
  ) {


    console.log(
      "Academy pilot characters are not fully registered.",
      participants
    );


    return false;
  }


  // Development pilot prerequisite only: the production acquisition flow does not
  // auto-grant Menma's Entity to fresh players.
  if (!playerData.entities.ownedEntityIds.includes("menma_nine_tails")) {
    grantEntityOwnership("menma_nine_tails");
  }
  if (getAttachedSummonIdForCharacter("academy_menma")!=="menma_nine_tails") {
    attachEntitySummonToCharacter("academy_menma","menma_nine_tails");
  }

  const equipment =
    prepareAcademyPilotBattleEquipment();


  if (
    !equipment
  ) {

    console.log(
      "Academy pilot equipment preparation failed."
    );


    return false;
  }


  const preservedEnemyParticipantIds =
    currentBattle.deployment &&
    currentBattle.deployment.enemy &&
    Array.isArray(currentBattle.deployment.enemy.slots)
      ? currentBattle.deployment.enemy.slots
          .map(slot => slot && slot.participantId)
          .filter(Boolean)
      : getBattleEnemyParticipantIds();


  currentBattle.deployment = {

    player: {
      slots: createBattleDeploymentSlots(
        ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS
      )
    },

    enemy: {
      slots: createBattleDeploymentSlots(
        preservedEnemyParticipantIds.length > 0
          ? preservedEnemyParticipantIds
          : getBattleEnemyParticipantIds()
      )
    },

    transitionCounter: 0,
    lastTransition: null
  };


  syncBattleActiveEnemyFromDeployment();


  currentBattle.characterId =
    ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS[
      0
    ];


  syncBattleActivePlayerFromDeployment();


  initializeBattleContributionRecordsFromDeployment();


  initializeBattleSourcePackageRuntime();


  initializeBattleRemainingPLFromDeployment({

    preserveExistingEnemyPower:
      true

  });


  initializeBattleAttachedSummonRuntimeFromDeployment();

  initializeBattleDedicatedVariantRuntimePackages();


  currentBattle.battleLog = [

    `${currentBattle.enemy.name} appears!`,

    `${currentBattle.activePlayer.name} prepares for battle.`,

    "Academy Battle pilot deployed."

  ];


  saveTestState();


  openOverlay(
    "combat"
  );


  return {

    success:
      true,

    participantIds:
      [
        ...ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS
      ],

    equipment:
      equipment

  };
}

// =========================================================
// BRICK 319 — ACADEMY PILOT DEPLOYMENT DIAGNOSTIC
// =========================================================
//
// Validates:
//
// - five Academy pilot identities exist
// - supplied compatibility Base PL matches canonical
//   rounded Base-PL calculation
// - ordinary roster visibility follows explicit ownership, not pilot metadata
// - explicit Academy deployment order is correct
// - Hinata begins in Active Slot 1
// - Battle contribution state is scoped to deployed pilot
//
// =========================================================

function runAcademyPilotDeploymentDiagnostics() {


  const participants =
    getAcademyBattlePilotParticipants();


  const normalIds =
    createInitialBattlePlayerParticipantIds();


  const currentPilotIds =
    currentBattle.deployment &&
    currentBattle.deployment.player &&
    Array.isArray(
      currentBattle.deployment.player.slots
    )

      ? currentBattle.deployment.player.slots
          .map(
            slot =>
              slot.participantId
          )
          .filter(
            participantId =>
              !!participantId
          )

      : [];


  const expectedPL = {

    academy_hinata:
      8,

    academy_izuno:
      9,

    academy_mirai:
      9,

    academy_menma:
      10,

    academy_kushina:
      12

  };


  const result = {


    fivePilotCharactersRegistered:
      participants.length ===
      5,


    suppliedBasePLMatchesFormula:
      participants.every(
        character => {


          const expected =
            expectedPL[
              character.id
            ];


          return (
            calculateBasePL(
              character
            ) ===
              expected
            &&
            Number(
              character.basePL
            ) ===
              expected
          );
        }
      ),


    ownershipNotPilotFlagControlsRoster:
      ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS.every(
        characterId =>
          getClanManageableRosterCharacters().some(character => character.id === characterId)
      ),


    livePilotDeploymentLoaded:
      ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS.every(
        (
          characterId,
          index
        ) =>
          currentPilotIds[
            index
          ] ===
          characterId
      ),


    hinataIsActiveSlotOne:
      !!(
        currentBattle.activePlayer &&
        currentBattle.activePlayer.id ===
          "academy_hinata"
      ),


    contributionsScopedToPilot:
      Object.keys(
        currentBattle.contributions ||
        {}
      ).length ===
        5 &&
      ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS.every(
        characterId =>
          !!currentBattle
            .contributions[
              characterId
            ]
      )

  };


  result.pass =
    Object.values(
      result
    ).every(
      value =>
        value ===
        true
    );


  console.table(
    result
  );


  return result;
}


//=========================================================
// BRICK 300 — WITHDRAWAL / QUEUE TRANSITION AUTHORITY
// BRICK 329 — ZERO REMAINING PL WITHDRAWAL INTEGRATION
// BRICK 606 — SLOT-AWARE PLAYER / ENEMY QUEUE ADVANCE
// =========================================================
//
// Removing any deployed slot compacts only the slots after it.
// A2 loss therefore shifts A3→A2 and R1→A3 while A1 remains.
// A1 loss preserves the original 2→1 / 3→2 / 4→3 queue.
//
// =========================================================

function getBattleDeploymentParticipantSlotNumber(side,participantId) {
  const deployment=currentBattle.deployment;
  const slots=deployment&&deployment[side]&&Array.isArray(deployment[side].slots)?deployment[side].slots:[];
  const index=slots.findIndex(slot=>slot&&slot.participantId===participantId);
  return index>=0?index+1:null;
}

function hasBattleDeploymentSuccessor(side,slotNumber) {
  const deployment=currentBattle.deployment;
  const slots=deployment&&deployment[side]&&Array.isArray(deployment[side].slots)?deployment[side].slots:[];
  return slots.some(slot=>slot&&Number(slot.slotNumber)>Number(slotNumber)&&!!slot.participantId);
}

function hasBattleDeploymentParticipants(side) {
  const deployment=currentBattle.deployment;
  const slots=deployment&&deployment[side]&&Array.isArray(deployment[side].slots)?deployment[side].slots:[];
  return slots.some(slot=>slot&&!!slot.participantId);
}

function canWithdrawActiveBattleFighter() {
  if (!currentBattle.active||currentBattle.battleOver||!currentBattle.deployment) return false;
  const activeSlot=getBattleDeploymentSlot("player",1);
  return !!(activeSlot&&activeSlot.participantId&&hasBattleDeploymentSuccessor("player",1));
}

function advanceBattleDeploymentQueue(side,participantId,reason="zero_remaining_battle_pl",options={}) {
  if (!currentBattle.deployment||!currentBattle.deployment[side]) return false;
  const slots=currentBattle.deployment[side].slots;
  if (!Array.isArray(slots)) return false;
  const removedIndex=slots.findIndex(slot=>slot&&slot.participantId===participantId);
  if (removedIndex<0) return false;
  const removedSlot=removedIndex+1;
  if (options.requireSuccessor===true&&!hasBattleDeploymentSuccessor(side,removedSlot)) return false;

  const participant=getBattleParticipantByIdentity(side,participantId);
  const withdrawnCardProjection=getBattleActiveCardProjection(side,participant);
  const withdrawnPortraitProjection=participant
    ? (side==="player"?resolveUIPortraitProjection(participant):resolveBattleEnemyPortraitProjection(participant))
    : {path:""};
  const withdrawnPresentation=participant?{
    id:participant.id||participantId,
    name:participant.name||participant.id||participantId,
    cardPath:withdrawnCardProjection.path||"",
    portraitPath:withdrawnPortraitProjection.path||""
  }:null;
  const runtimeCleanup=cleanupBattleParticipantRuntimeState(side,participantId,reason);
  const movements=[];

  for (let sourceIndex=removedIndex+1;sourceIndex<slots.length;sourceIndex+=1) {
    const source=slots[sourceIndex];
    if (!source||!source.participantId) continue;
    const fromSlot=sourceIndex+1;
    const toSlot=sourceIndex;
    let movementType="queue_advance";
    if (fromSlot>=5&&toSlot<=4) movementType="reserve_promotion";
    else if (toSlot<=4) movementType="next_queue_advance";
    movements.push({participantId:source.participantId,fromSlot,toSlot,movementType});
  }

  for (let index=removedIndex;index<slots.length-1;index+=1) {
    slots[index].participantId=slots[index+1].participantId||null;
  }
  slots[slots.length-1].participantId=null;

  const deployment=currentBattle.deployment;
  deployment.transitionCounter=(Number(deployment.transitionCounter)||0)+1;
  const replacementParticipantId=slots[removedIndex]&&slots[removedIndex].participantId?slots[removedIndex].participantId:null;
  const transition={
    id:`battle_deployment_${Date.now()}_${deployment.transitionCounter}`,
    type:"withdrawal_queue_advance",
    side,
    reason,
    withdrawnParticipantId:participantId,
    vacatedSlot:removedSlot,
    replacementParticipantId,
    movements,
    withdrawnPresentation,
    runtimeCleanup,
    createdAt:Date.now()
  };
  deployment.lastTransition=transition;

  if (side==="player") {
    syncBattleActivePlayerFromDeployment();
    if (typeof clearBattleActionSelectionForActorChange==="function") clearBattleActionSelectionForActorChange();
  }
  if (side==="enemy") syncBattleActiveEnemyFromDeployment();

  if (participant&&Array.isArray(currentBattle.battleLog)) {
    const prefix=side==="enemy"?"Enemy ":"";
    currentBattle.battleLog.push(`${prefix}${participant.name||participant.id} left Slot ${removedSlot} (${reason}).`);
  }

  const promotion=movements.find(movement=>movement.movementType==="reserve_promotion")||null;
  if (promotion&&Array.isArray(currentBattle.battleLog)) {
    const promoted=getBattleParticipantByIdentity(side,promotion.participantId);
    const queueLabel=getClanBattleQueueSlotLabel(promotion.toSlot);
    if (promoted) currentBattle.battleLog.push(`${promoted.name||promoted.id} advanced from Reserve to ${queueLabel}.`);
  }

  recordBattleEvidence({
    eventType:"battle_participant_withdrawn",
    actorRef:createBattleParticipantRef(side,participantId),
    data:{reason,side,vacatedSlot:removedSlot,replacementParticipantId,movements}
  });

  setTimeout(()=>{
    if (currentBattle.deployment&&currentBattle.deployment.lastTransition&&currentBattle.deployment.lastTransition.id===transition.id) {
      currentBattle.deployment.lastTransition=null;
    }
  },760);

  return transition;
}

function withdrawActiveBattleFighter(options={}) {
  if (!canWithdrawActiveBattleFighter()) {
    console.log("No valid Battle deployment successor is available.");
    return false;
  }
  const activeSlot=getBattleDeploymentSlot("player",1);
  const transition=advanceBattleDeploymentQueue("player",activeSlot.participantId,options&&options.reason?options.reason:"manual_withdrawal",{requireSuccessor:true});
  if (!transition) return false;
  const active=currentBattle.activePlayer;
  if (active&&Array.isArray(currentBattle.battleLog)) currentBattle.battleLog.push(`${active.name} advances to Active Slot 1.`);
  saveTestState();
  openOverlay("combat");
  return transition;
}

function advanceBattleParticipantAtZeroPL(side,participantId) {
  return advanceBattleDeploymentQueue(side,participantId,"zero_remaining_battle_pl",{requireSuccessor:false});
}

// =========================================================
// BATTLE CONTRIBUTION SYSTEM
// =========================================================

function recordBattleContribution(
  fighter,
  damage,
  attackType
) {


  if (
    !fighter ||
    !currentBattle.contributions
  ) {

    return;
  }


  const contribution =
    currentBattle.contributions[
      fighter.id
    ];


  if (
    !contribution
  ) {

    return;
  }


  contribution.damage =
    Number(
      contribution.damage
    ) || 0;


  contribution.attacks =
    Number(
      contribution.attacks
    ) || 0;


  const disciplineDamageKeys = {

    nin:
      "ninjutsuDamage",

    tai:
      "taijutsuDamage",

    gen:
      "genjutsuDamage",

    buki:
      "bukijutsuDamage",

    fuin:
      "fuinjutsuDamage",

    kin:
      "kinjutsuDamage"

  };


  Object.values(
    disciplineDamageKeys
  ).forEach(
    key => {


      contribution[
        key
      ] =
        Number(
          contribution[
            key
          ]
        ) || 0;
    }
  );


  contribution.damage +=
    Number(
      damage
    ) || 0;


  contribution.attacks +=
    1;


  const disciplineDamageKey =
    disciplineDamageKeys[
      attackType
    ] ||
    null;


  if (
    disciplineDamageKey
  ) {


    contribution[
      disciplineDamageKey
    ] +=
      Number(
        damage
      ) || 0;
  }
}


function calculateBattleMVP() {


  const contributions =
    Object.values(
      currentBattle.contributions || {}
    );


  if (
    contributions.length === 0
  ) {

    return null;

  }


  const totalDamage =
    contributions.reduce(
      (
        total,
        fighter
      ) =>
        total +
        fighter.damage,
      0
    );


  if (
    totalDamage <= 0
  ) {

    return null;

  }


  const winner =
    contributions.reduce(
      (
        best,
        fighter
      ) => {

        if (
          !best ||
          fighter.damage >
          best.damage
        ) {

          return fighter;

        }


        return best;

      },
      null
    );


  return {

    id:
      winner.id,

    name:
      winner.name,

    power:
      winner.power,

    damage:
      winner.damage,

    attacks:
      winner.attacks,

    percentage:
      Math.round(
        (
          winner.damage /
          totalDamage
        ) *
        100
      )

  };

}


// =========================================================
// BATTLE REWARD SYSTEM
// =========================================================

function randomRewardNumber(
  min,
  max
) {

  return Math.floor(
    Math.random() *
    (max - min + 1)
  ) + min;

}



function rollRewardChance(
  chance
) {

  const roll =
    Math.random() * 100;


  return roll < chance;

}



function generateBattleRewards(
  enemy,
  finishingShinobi
) {


  // BRICK 1033 — Controlled Field Readiness opposition grants no separate
  // Ryo/EXP/item/material reward. Victory claim lifecycle still receives an
  // explicit zero-value entitlement so CLAIM != CONTINUE remains intact.
  if (currentBattle&&currentBattle.returnContext&&currentBattle.returnContext.type==="field_readiness_assessment"&&currentBattle.encounterId===FIELD_READINESS_ALPHA_WORLD_AUTHORITY.encounter.encounterId) {
    currentBattle.rewards={generated:true,claimed:false,ryo:0,exp:0,items:[],rareDrops:[],finishingShinobi:finishingShinobi?finishingShinobi.name:null,fieldReadinessNoAdditionalReward:true};
    return currentBattle.rewards;
  }

  // =========================================
  // SAFETY CHECK
  // Never generate the same rewards twice
  // =========================================

  if (
    currentBattle.rewards.generated
  ) {

    console.log(
      "Rewards already generated"
    );

    return currentBattle.rewards;

  }


  const rewardTable =
    enemy.rewards;


  if (!rewardTable) {

    console.log(
      "Enemy has no reward table:",
      enemy.name
    );

    return currentBattle.rewards;

  }


  // =========================================
  // RYO
  // =========================================

  const ryo =
    randomRewardNumber(
      rewardTable.ryo.min,
      rewardTable.ryo.max
    );


  // =========================================
  // EXP
  // =========================================

  const exp =
    randomRewardNumber(
      rewardTable.exp.min,
      rewardTable.exp.max
    );


  // =========================================
  // COMMON ITEM DROPS
  // =========================================

  const items = [];


  rewardTable.commonDrops.forEach(
    drop => {

      if (
        rollRewardChance(
          drop.chance
        )
      ) {

        items.push({

          name:
            drop.name,

          rarity:
            drop.rarity,

          chance:
            drop.chance

        });

      }

    }
  );


  // =========================================
  // RARE ITEM DROPS
  // =========================================

  const rareDrops = [];


  rewardTable.rareDrops.forEach(
    drop => {

      if (
        rollRewardChance(
          drop.chance
        )
      ) {

        rareDrops.push({

          name:
            drop.name,

          rarity:
            drop.rarity,

          chance:
            drop.chance

        });

      }

    }
  );


  // =========================================
  // STORE FINAL RESULT
  // =========================================

  currentBattle.rewards = {

    generated: true,

    ryo:
      ryo,

    exp:
      exp,

    items:
      items,

    rareDrops:
      rareDrops,

    finishingShinobi:
      finishingShinobi
        ? finishingShinobi.name
        : null

  };


  console.log(
    "BATTLE REWARDS:",
    currentBattle.rewards
  );


  return currentBattle.rewards;

}


