// =========================================================
// 3. GLOBAL OVERLAY SYSTEM
// =========================================================

function openOverlay(type) {


  // =====================================================
  // BRICK 750 — STORY SCENE IS A PRESENTATION LAYER
  // =====================================================
  // Dialogue overlays the current environment/map rather than replacing it.
  // The underlying overlay type remains authoritative so Battle can return to
  // the same scene/environment without manufacturing a separate story page.
  if (type === "story_scene") {
    saveTestState();
    return renderStoryScenePresentationLayer();
  }

  // BRICK 962 — ordinary surfaces cannot bypass the mandatory Academy Team
  // Formation journey or its post-commit CONTINUE boundary.
  if (isAcademyTeamFormationJourneyBlockingFreePlay()) {
    openAcademyTeamFormationUI({showChronicleBegins:false});
    return {success:false,reason:getAcademyTeamFormationJourneyBlockReason(ensurePlayerAcquisitionState())};
  }

  // BRICKS 1034–1038 — Promotion recognition does not bypass the mandatory
  // Genin Roster Transition. Only its owning/resume surfaces remain reachable.
  if (isGeninRosterTransitionPending()&&!['genin_roster_transition','arena','arena_promotion','field_readiness_assessment'].includes(type)) {
    openGeninRosterTransitionUI();
    return {success:false,reason:'genin_roster_transition_required'};
  }

  if (typeof hideStoryScenePresentationLayer === "function") {
    hideStoryScenePresentationLayer({preserveRuntime:true});
  }

  currentOverlayType =
    type;


  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  const container =
    document.getElementById(
      "overlay-content-container"
    );


  if (overlay) {
    overlay.classList.toggle(
      "my-clan-adaptive-open",
      type === "clan" || type === "roster"
    );
  }

  if (overlay) {
    overlay.classList.toggle(
      "shinobi-record-open",
      type === "shinobi_record"
    );
  }


  if (
    !overlay ||
    !container
  ) {

    return;
  }


  // =========================================
  // BRICK 295 — BATTLE LIVE CANVAS MODE
  // =========================================
  //
  // Combat reuses the existing global overlay authority.
  // Only presentation changes while the live Battle screen
  // is open. Other overlay types remain unchanged.
  //
  // =========================================

  overlay.classList.toggle(
    "battle-live-open",
    type === "combat"
  );


  saveTestState();


  overlay.style.display =
    "flex";


  switch (type) {


    case "clan":

      renderClanOverlay(
        container
      );

      break;


    case "village":

      renderVillageOverlay(
        container
      );

      break;


    case "missions":

      renderGenericOverlay(
        container,
        "MISSION BOARD",
        "Choose story missions, side missions and regional assignments."
      );

      break;


    // BRICKS 6500–7299 — live Shinobi Record / Codex shell.
    case "shinobi_record":

      renderShinobiRecordOverlay(
        container
      );

      break;


    // =====================================================
    // BRICK 900 — ALPHA ARENA MAIN NAVIGATION OWNER
    // BRICK 901 — PROMOTION SURFACE ROUTE
    // =====================================================
    case "arena":

      renderArenaMainOverlay(
        container
      );

      break;


    case "arena_promotion":

      renderArenaPromotionOverlay(
        container
      );

      break;


    case "field_readiness_assessment":

      renderFieldReadinessAssessmentOverlay(
        container
      );

      break;


    // BRICK 932 — separate post-Promotion roster transition consumer.
    case "genin_roster_transition":

      renderGeninRosterTransitionOverlay(
        container
      );

      break;


    case "battle":

      renderBattleOverlay(
        container
      );

      break;


    case "combat":

      renderCombatOverlay(
        container
      );

      break;


    case "victory":

      renderVictoryOverlay(
        container
      );

      break;


    // BRICK 736 — GENERIC DIALOGUE / STORY SCENE CONSUMER
    case "story_scene":

      renderStorySceneOverlay(
        container
      );

      break;


    case "training":

      renderTrainingOverlay(
        container
      );

      break;


    case "events":

      renderGenericOverlay(
        container,
        "WORLD EVENTS",
        "Limited-time regional encounters and special rewards will appear here."
      );

      break;


    case "roster":

      // =========================================
      // BRICK 356 — LEGACY ROSTER ROUTE
      // =========================================
      //
      // YOUR CLAN is now the sole character-management surface.
      // Keep this route as a compatibility redirect only.
      //
      // =========================================

      currentOverlayType =
        "clan";

      renderClanOverlay(
        container
      );

      break;


    case "shop":

      renderGenericOverlay(
        container,
        "SPECIAL SHOP",
        "Purchase rare scrolls, equipment and special items."
      );

      break;


    case "exams":

      renderGenericOverlay(
        container,
        "SHINOBI EXAMS",
        "Take rank exams to progress through the shinobi hierarchy."
      );

      break;


    case "practical":

      renderGenericOverlay(
        container,
        "PRACTICAL TRAINING",
        "Complete tactical tests and practical shinobi exercises."
      );

      break;


    case "group":

      renderGenericOverlay(
        container,
        "GROUP",
        "Manage squads, teams and future clan-based activities."
      );

      break;


    case "defend":

      renderGenericOverlay(
        container,
        "VILLAGE DEFENCE",
        "Defend your territory from invading rogue shinobi and hostile factions."
      );

      break;


    case "kage":

      renderGenericOverlay(
        container,
        "KAGE",
        "Endgame leadership systems and Kage-level responsibilities."
      );

      break;


    default:

      renderGenericOverlay(
        container,
        "SYSTEM ACTIVE",
        "This Shinobi Chronicles module is currently under development."
      );

      break;
  }
}


// =========================================================
// 4. CLOSE / BACK OVERLAY
// =========================================================

function closeOverlay() {


  // =====================================================
  // BRICK 751 — STORY LAYER CLOSE AUTHORITY
  // =====================================================
  // Escape/back cannot close the environment underneath an active dialogue.
  // The current authored beat decides whether presentation close is legal.
  if (typeof isStoryScenePresentationVisible === "function" && isStoryScenePresentationVisible()) {
    const result=exitActiveStoryScene({reason:"presentation_close"});
    if (!result || result.success !== true) {
      console.log("Story scene presentation remains open:", result && result.reason ? result.reason : "close_not_authorised");
    }
    return;
  }


  // =========================================
  // BRICK 868 — VICTORY SCREEN CLOSE LOCK
  // =========================================
  // Closing/dismissing Victory is not a substitute for either CLAIM or
  // CONTINUE. The explicit two-stage lifecycle remains authoritative.
  if (
    currentOverlayType ===
    "victory"
  ) {
    console.log(
      currentBattle.rewards&&currentBattle.rewards.claimed===true
        ? "Victory remains open until CONTINUE is chosen."
        : "Victory remains open until rewards are CLAIMED, then CONTINUE is chosen."
    );
    return;
  }


  // =========================================
  // COMBAT
  // Return to encounter selection
  // =========================================

  if (
    currentOverlayType ===
    "combat"
  ) {


    // BRICKS 1719–1722 — any authored caller-owned Battle cannot be abandoned
    // through generic overlay close. Story, assessment, regional hotspot and
    // mission-area hotspot callers all keep their continuation envelope.
    if (
      currentBattle.active === true &&
      currentBattle.battleOver !== true &&
      currentBattle.returnContext
    ) {
      console.log("Caller-owned Battle is still active; use Battle actions/Withdraw rather than discarding its continuation context.");
      return;
    }


    currentBattle.active =
      false;


    openOverlay(
      "battle"
    );


    return;

  }


  // =========================================
  // STORY SCENE
  // Return through the scene's authored caller context.
  // =========================================
  if (currentOverlayType === "story_scene") {
    exitActiveStoryScene({reason:"presentation_close"});
    return;
  }


  // =========================================
  // BATTLE / LOCATION SCREEN
  // Return to current region map
  // =========================================

  if (
    currentOverlayType ===
      "battle" &&
    selectedRegionKey
  ) {


    openRegionHub(
      selectedRegionKey
    );


    return;

  }


  // =========================================
  // OTHER REGION SUB-SCREENS
  // =========================================

  if (
    selectedRegionKey &&
    currentOverlayType !==
      "region"
  ) {


    openRegionHub(
      selectedRegionKey
    );


    return;

  }


  // =========================================
  // REGION MAP
  // Return to world map
  // =========================================

  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  if (!overlay) {

    return;

  }


  overlay.style.display =
    "none";


  overlay.classList.remove(
    "region-map-open"
  );

  overlay.classList.remove(
    "my-clan-adaptive-open"
  );


  currentOverlayType =
    null;


  selectedRegionKey =
    null;


  selectedLocationNode =
    null;


  saveTestState();

}


// =========================================================
// BRICK 155 — DEVELOPMENT BATTLE STATE SAVE
// BRICK 607 — ENEMY PARTICIPANT IDENTITY SAVE
// =========================================================
//
// Preserves Battle / Encounter context across refreshes.
//
// BRICK 299:
// - deployment
//
// BRICKS 302–304:
// - transient Battle state
// - Conditions
// - action sequence
// - structured Battle evidence
//
// =========================================================

function saveTestState() {


  const state = {

    overlayType:
      currentOverlayType,


    regionKey:
      selectedRegionKey,

    // BRICKS 1569–1574 — contained mission-area UI/caller persistence.
    missionAreaId:
      selectedMissionAreaId,

    missionAreaReturnContext:
      normalizePresentationReturnContext(selectedMissionAreaReturnContext),

    hotspotId:
      selectedHotspotId,

    opportunityId:
      selectedOpportunityId,


    locationId:
      selectedLocationNode
        ? selectedLocationNode.id
        : null,


    enemyId:
      selectedEnemy
        ? selectedEnemy.id
        : null,


    enemyParticipantIds:
      getBattleEnemyParticipantIds(),


    battleId:
      currentBattle.battleId,


    encounterId:
      currentBattle.encounterId,


    characterId:
      currentBattle.characterId,


    enemyPower:
      currentBattle.enemyPower,


    enemyMaxPower:
      currentBattle.enemyMaxPower,


    activePlayerId:
      currentBattle.activePlayer
        ? currentBattle.activePlayer.id
        : null,


    deployment:
      getBattleDeploymentSaveState(),


    runtime:
      currentBattle.battleId
        ? getBattleRuntimeSaveState()
        : null,


    lastDamage:
      currentBattle.lastDamage,


    battleOver:
      currentBattle.battleOver,


    completedAt:
      currentBattle.completedAt,


    claimedAt:
      currentBattle.claimedAt,


    completionRecorded:
      currentBattle
        .completionRecorded ===
        true,


    outcome:
      currentBattle.outcome
        ? cloneBattleRuntimeValue(currentBattle.outcome)
        : null,


    defeat:
      currentBattle.defeat
        ? cloneBattleRuntimeValue(currentBattle.defeat)
        : null,


    // BRICK 742 — preserve caller routing across refresh without copying
    // authored scene definitions or hidden story truth into Battle state.
    battleReturnContext:
      normalizeBattleReturnContext(currentBattle.returnContext),


    observerSafeResultContext:
      currentBattle.observerSafeResultContext
        ? cloneBattleRuntimeValue(currentBattle.observerSafeResultContext)
        : null,

    // BRICKS 1908–1912 — confrontation caller/objective state survives refresh.
    unknownOperativeConfrontation:
      currentBattle.unknownOperativeConfrontation
        ? cloneBattleRuntimeValue(currentBattle.unknownOperativeConfrontation)
        : null,

    // POST-1995 / BRICKS 1995–2074 — Mission 7 sanitisation-trio caller,
    // evidence-target and source-owned state survives refresh without
    // manufacturing World/Object persistence.
    mission7SanitisationEncounter:
      currentBattle.mission7SanitisationEncounter
        ? cloneBattleRuntimeValue(currentBattle.mission7SanitisationEncounter)
        : null,

    // Mission 5 Female Operator exact caller / encounter state.
    mission5FemaleOperatorEncounter:
      currentBattle.mission5FemaleOperatorEncounter
        ? cloneBattleRuntimeValue(currentBattle.mission5FemaleOperatorEncounter)
        : null,


    battleLog:
      currentBattle.battleLog,


    rewards:
      currentBattle.rewards,


    contributions:
      currentBattle.contributions ||
      {}

  };


  sessionStorage.setItem(
    "shinobiTestState",
    JSON.stringify(
      state
    )
  );
}

