registerAlphaFieldReadinessWorldOpportunities();

function syncFieldReadinessWorldOpportunityState(attempt,{save=true}={}) {
  FIELD_READINESS_WORLD_OPPORTUNITY_IDS.forEach(id=>{
    const definition=getRegisteredWorldEventOpportunity(id);
    const projectable=!!(attempt&&attempt.status==="in_progress"&&definition&&typeof definition.evaluateProjection==="function"&&definition.evaluateProjection());
    setWorldEventLifecycle(id,{projectable},{save:false});
    setOpportunityDiscovery(id,{level:projectable?"discovered":"undiscovered"},{save:false});
    setOpportunityTracking(id,{tracked:projectable,leadState:projectable?"active_assessment":null,mandatory:projectable},{save:false});
  });
  if (save) savePlayerData();
  return true;
}

function openFieldReadinessWorldMap() {
  const attempt=getFieldReadinessAttempt();
  if (!attempt||attempt.status!=="in_progress") return {success:false,reason:"assessment_attempt_not_active"};
  syncFieldReadinessWorldOpportunityState(attempt,{save:false});
  closeOverlay();
  openRegionHub("fire");
  return {success:true,destination:"fire_region_map",attemptId:attempt.attemptId,currentNode:ensureFieldReadinessWorldState(attempt).currentNode};
}

function getOpportunityDiscoveryLevel(definition) {
  const state=getWorldEventDimensionState("observerDiscoveryByOpportunityId",definition.opportunityId);
  return String(state.level||definition.defaultDiscoveryLevel||"undiscovered");
}

function shouldProjectOpportunityForObserver(definition) {
  if (definition&&typeof definition.revealPredicate==="function") {
    const revealed=definition.revealPredicate({definition,playerData,runtime:ensureWorldEventRuntimeState()});
    if (revealed!==true) return false;
  }
  if (definition&&typeof definition.evaluateProjection==="function"&&definition.evaluateProjection()!==true) return false;
  const discoveryLevel=getOpportunityDiscoveryLevel(definition);
  const worldState=definition.eventId?getWorldEventDimensionState("worldLifecycleByEventId",definition.eventId):{};
  if (worldState.projectable===false) return false;
  if (["rumoured","partially_known","discovered","investigated","known"].includes(discoveryLevel)) return true;
  return definition.presentation&&definition.presentation.showUnknownMarker===true;
}

// =========================================================
// BRICK 943 — TRANSITION-RESOLUTION ACTIVITY EXCEPTION
// BRICK 948 — OPERATIONAL GENIN CONTENT REQUIREMENT ADAPTER
// =========================================================
function isGeninRosterTransitionResolutionInteraction(definition,action) {
  if (!definition||!action) return false;
  if (definition.geninRosterTransitionResolution===true||action.geninRosterTransitionResolution===true) return true;
  if (action.progressionGateException==="genin_roster_transition") return true;
  const transition=getGeninRosterTransitionState();
  const snapshot=transition.candidateSnapshot;
  const recruitmentVariantId=action&&action.recruitment&&action.recruitment.variantId||null;
  if (snapshot&&action.kind==="recruit"&&recruitmentVariantId) {
    return [...snapshot.teammateCandidateVariantIds,...snapshot.joninLeaderCandidateVariantIds].includes(recruitmentVariantId);
  }
  return false;
}

function requiresOperationalGeninProgression(definition,action) {
  return !!(definition&&definition.requiresOperationalGenin===true||action&&action.requiresOperationalGenin===true);
}

function evaluateOpportunityActionAvailability(definition,action) {
  if (!definition||!action) return {available:false,reason:"interaction_missing",reasonVisible:false};
  if (isGeninRosterTransitionPending()&&!isGeninRosterTransitionResolutionInteraction(definition,action)) return {available:false,reason:"genin_roster_transition_required",reasonVisible:true};
  if (requiresOperationalGeninProgression(definition,action)&&!isOperationalGeninProgressionAvailable()) return {available:false,reason:"operational_genin_required",reasonVisible:true};
  const override=getWorldEventDimensionState("actionabilityByOpportunityId",definition.opportunityId);
  if (override.available===false) return {available:false,reason:override.reason||"unavailable",reasonVisible:override.reasonVisible===true};
  if (Array.isArray(override.legalActionIds)&&!override.legalActionIds.includes(action.id)) return {available:false,reason:override.reason||"action_unavailable",reasonVisible:override.reasonVisible===true};
  if (typeof action.evaluateAvailability==="function") {
    const evaluated=action.evaluateAvailability({definition,playerData,currentBattle});
    if (evaluated===false) return {available:false,reason:"requirements_not_met",reasonVisible:false};
    if (evaluated&&typeof evaluated==="object") return {available:evaluated.available!==false,reason:evaluated.reason||null,reasonVisible:evaluated.reasonVisible===true};
  }
  return {available:true,reason:null,reasonVisible:false};
}

function createObserverSafeOpportunityProjection(definition) {
  if (!definition||!shouldProjectOpportunityForObserver(definition)) return null;
  const discovery=getWorldEventDimensionState("observerDiscoveryByOpportunityId",definition.opportunityId);
  const level=getOpportunityDiscoveryLevel(definition);
  const isKnown=level!=="undiscovered"&&level!=="unknown";
  const tracking=getWorldEventDimensionState("trackingByOpportunityId",definition.opportunityId);
  const resolution=getWorldEventDimensionState("resolutionByOpportunityId",definition.opportunityId);
  const actionability=getWorldEventDimensionState("actionabilityByOpportunityId",definition.opportunityId);
  const presentation=definition.presentation||{};
  const label=isKnown?(discovery.label||presentation.label||"Unknown"):"???";
  const summary=isKnown?(discovery.summary||presentation.summary||""):"";
  const family=isKnown?(discovery.family||presentation.family||"Unknown"):"Unknown";
  // Category is observer-safe presentation metadata only. It never grants,
  // resolves, reveals, or forces the authored interaction.
  const category=isKnown?normalizeWorldOpportunityCategory(presentation.category||"OTHER"):"UNKNOWN";
  const legalActions=definition.interactions.map(action=>{
    const availability=evaluateOpportunityActionAvailability(definition,action);
    return {
      actionId:action.id,
      label:action.label||String(action.kind||"INTERACT").toUpperCase(),
      kind:action.kind||"custom",
      available:availability.available,
      knownBlocker:availability.available?null:(availability.reasonVisible?availability.reason:null)
    };
  }).filter(action=>action.available||action.knownBlocker);

  return {
    hotspot_id:definition.hotspotId,
    location_id:definition.locationId,
    event_id:definition.eventId,
    opportunity_id:definition.opportunityId,
    presentation_family:family,
    opportunity_category:category,
    mission_area_id:definition.missionAreaId||null,
    known_label:label,
    known_summary:summary,
    discovery:{level,rumoured:level==="rumoured"||level==="partially_known",known:isKnown},
    actionability:{available:actionability.available!==false,known_blocker:actionability.reasonVisible===true?(actionability.reason||null):null},
    legal_actions:legalActions,
    tracking:{tracked:tracking.tracked===true,lead_state:tracking.leadState||null,mandatory:tracking.mandatory===true},
    resolution:{known_state:resolution.visibleState||null},
    anchor:{x:Number((definition.anchor||{}).x)||0,y:Number((definition.anchor||{}).y)||0},
    icon:presentation.icon||"",
    source_kind:definition.sourceKind
  };
}

function groupObserverSafeOpportunityHotspots(definitions,{regionKey=null}={}) {
  const projected=(Array.isArray(definitions)?definitions:[])
    .map(createObserverSafeOpportunityProjection)
    .filter(Boolean);
  const groups=new Map();
  projected.forEach(opportunity=>{
    if (!groups.has(opportunity.hotspot_id)) groups.set(opportunity.hotspot_id,[]);
    groups.get(opportunity.hotspot_id).push(opportunity);
  });
  return [...groups.entries()].map(([hotspotId,opportunities])=>{
    const firstKnown=opportunities.find(item=>item.known_label!=="???")||opportunities[0];
    const location=regionKey?getWorldRegionLocation(regionKey,firstKnown.location_id):null;
    return {
      hotspotId,
      locationId:firstKnown.location_id,
      anchor:firstKnown.anchor,
      icon:firstKnown.icon||(location&&location.icon)||"",
      presentationFamily:opportunities.every(item=>item.presentation_family===opportunities[0].presentation_family)?opportunities[0].presentation_family:"Chronicle Event",
      knownLabel:firstKnown.known_label,
      knownSummary:firstKnown.known_summary,
      aggregationCount:opportunities.length,
      opportunityIds:opportunities.map(item=>item.opportunity_id),
      opportunities
    };
  });
}

function getRegionHotspotProjections(regionKey,region=worldRegions[regionKey]) {
  return groupObserverSafeOpportunityHotspots(getWorldOpportunityDefinitionsForRegion(regionKey,region),{regionKey});
}

function getMissionAreaHotspotProjections(areaId) {
  return groupObserverSafeOpportunityHotspots(getWorldOpportunityDefinitionsForMissionArea(areaId));
}

function getMissionAreaHotspotProjection(areaId,hotspotId) {
  return getMissionAreaHotspotProjections(areaId).find(hotspot=>hotspot.hotspotId===hotspotId)||null;
}

function getHotspotProjection(regionKey,hotspotOrLocationId) {
  const projections=getRegionHotspotProjections(regionKey,worldRegions[regionKey]);
  return projections.find(hotspot=>hotspot.hotspotId===hotspotOrLocationId||hotspot.locationId===hotspotOrLocationId)||null;
}

function selectHotspotOpportunity(opportunityId) {
  selectedOpportunityId=opportunityId||null;
  selectedOpportunityActionFeedback=null;
  if (currentOverlayType==="mission_area"&&selectedMissionAreaId&&getLocalMissionAreaDefinition(selectedMissionAreaId)) {
    renderLocalMissionAreaUI(selectedMissionAreaId);
  } else if (selectedRegionKey&&worldRegions[selectedRegionKey]) {
    renderRegionHubUI(selectedRegionKey,worldRegions[selectedRegionKey]);
  }
  return getSelectedOpportunityProjection();
}

function getSelectedOpportunityProjection() {
  if (!selectedOpportunityId) return null;
  const hotspot=currentOverlayType==="mission_area"&&selectedMissionAreaId
    ? getMissionAreaHotspotProjection(selectedMissionAreaId,selectedHotspotId)
    : (selectedRegionKey?getHotspotProjection(selectedRegionKey,selectedHotspotId):null);
  return hotspot?hotspot.opportunities.find(item=>item.opportunity_id===selectedOpportunityId)||null:null;
}

function getOpportunityDefinitionIncludingLegacy(opportunityId) {
  const registered=getRegisteredWorldEventOpportunity(opportunityId);
  if (registered) return registered;
  if (!selectedRegionKey) return null;
  const region=worldRegions[selectedRegionKey];
  return getWorldOpportunityDefinitionsForRegion(selectedRegionKey,region).find(def=>def.opportunityId===opportunityId)||null;
}

function getClanQueueReadModel() {
  return getPersistentClanBattleQueueSlots().map((characterId,index)=>{
    const character=characterId?getPlayerCharacter(characterId):null;
    return {slot:index+1,label:CLAN_BATTLE_QUEUE_SLOT_DEFINITIONS[index]?CLAN_BATTLE_QUEUE_SLOT_DEFINITIONS[index].label:`SLOT ${index+1}`,characterId:characterId||null,name:character?character.name:null};
  });
}

function evaluateRecruitmentOpportunity(definition,action) {
  const recruitment=action&&action.recruitment;
  if (!recruitment||!recruitment.variantId) return {eligible:false,reason:"recruitment_authority_missing"};
  if (!getCharacterRegistryEntry(recruitment.variantId)) return {eligible:false,reason:"character_registry_missing"};
  if (isCharacterRegistryOwned(recruitment.variantId)) return {eligible:false,reason:"character_already_owned"};
  if (typeof recruitment.evaluateEligibility==="function") {
    const result=recruitment.evaluateEligibility({definition,playerData});
    if (result===false) return {eligible:false,reason:"recruitment_requirements_not_met"};
    if (result&&typeof result==="object"&&result.eligible===false) return result;
  }
  return {eligible:true};
}

function commitRecruitmentOpportunity(definition,action) {
  const eligibility=evaluateRecruitmentOpportunity(definition,action);
  if (!eligibility.eligible) return {success:false,reason:eligibility.reason||"recruitment_ineligible"};
  const recruitment=action.recruitment;
  const result=commitCharacterAcquisition({
    variantId:recruitment.variantId,
    route:recruitment.route||"world_event_recruitment",
    sourceEventId:definition.eventId||definition.opportunityId,
    context:{opportunityId:definition.opportunityId,locationId:definition.locationId,...(recruitment.context||{})},
    provenance:recruitment.provenance||{},
    linkedChronicleEvidenceIds:recruitment.linkedChronicleEvidenceIds||[]
  });
  if (result.success&&recruitment.resolutionPatch) setOpportunityResolution(definition.opportunityId,recruitment.resolutionPatch);
  return result;
}


// =========================================================
// BRICKS 1490–1495 — WORLD OPPORTUNITY BATTLE CALLER CONTEXT
// =========================================================
// Ordinary regional/map opportunities reuse the same Battle caller contract
// already used by Story Scene and Field Readiness callers.
//
// Location != hotspot != opportunity.
// Caller restoration preserves the selected mission-area context only; it does
// not commit a next encounter, reveal hidden truth, or resolve an opportunity.
// =========================================================
function createWorldOpportunityPresentationReturnContext(definition,action=null) {
  if (!definition||!definition.hotspotId||!definition.opportunityId) return null;
  const common={
    locationId:definition.locationId?String(definition.locationId):null,
    hotspotId:String(definition.hotspotId),
    opportunityId:String(definition.opportunityId),
    eventId:definition.eventId?String(definition.eventId):null,
    sourceActionId:action&&action.id?String(action.id):null
  };
  if (definition.missionAreaId) {
    return {type:"mission_area_hotspot",missionAreaId:String(definition.missionAreaId),regionKey:definition.regionKey?String(definition.regionKey):null,...common};
  }
  if (!definition.regionKey) return null;
  return {type:"region_hotspot",regionKey:String(definition.regionKey),...common};
}

function createWorldOpportunityBattleReturnContext(definition,action=null) {
  return createWorldOpportunityPresentationReturnContext(definition,action);
}

function attachWorldOpportunityBattleReturnContext(returnContext) {
  if (!currentBattle||!currentBattle.battleId) {
    return {success:false,reason:"battle_not_active_for_return_context"};
  }
  if (!returnContext||typeof returnContext!=="object") {
    return {success:false,reason:"battle_return_context_missing"};
  }
  currentBattle.returnContext=cloneBattleRuntimeValue(returnContext);
  currentBattle.observerSafeResultContext=null;
  saveTestState();
  return {
    success:true,
    battleId:currentBattle.battleId,
    returnContext:cloneBattleRuntimeValue(currentBattle.returnContext)
  };
}

function routeWorldOpportunityInteraction(opportunityId,actionId) {
  const acquisitionState=ensurePlayerAcquisitionState();
  if (isAcademyTeamFormationJourneyBlockingFreePlay(acquisitionState)) {
    return {success:false,reason:getAcademyTeamFormationJourneyBlockReason(acquisitionState)};
  }
  const definition=getOpportunityDefinitionIncludingLegacy(opportunityId);
  if (!definition) return {success:false,reason:"opportunity_missing"};
  const action=definition.interactions.find(item=>item.id===actionId);
  if (!action) return {success:false,reason:"interaction_missing"};
  if (isGeninRosterTransitionPending()&&!isGeninRosterTransitionResolutionInteraction(definition,action)) return {success:false,reason:"genin_roster_transition_required"};
  const availability=evaluateOpportunityActionAvailability(definition,action);
  if (!availability.available) return {success:false,reason:availability.reason||"interaction_unavailable"};

  let result={success:false,reason:"interaction_route_unhandled"};
  switch (action.kind) {
    case "battle": {
      const queue=getPersistentClanBattleQueueSlots();
      const startCharacterId=queue[0]||null;
      if (!startCharacterId) return {success:false,reason:"clan_start_slot_empty"};

      // BRICKS 1496–1499 — preserve the exact regional hotspot caller before
      // leaving the Event Drawer. An authored explicit returnContext may
      // override the default, but no path is inferred from UI sequence.
      const battleReturnContext=
        action.returnContext&&typeof action.returnContext==="object"
          ? cloneProgressionData(action.returnContext)
          : createWorldOpportunityBattleReturnContext(definition,action);
      if (!battleReturnContext) return {success:false,reason:"world_opportunity_return_context_missing"};

      // Authored Encounter identity owns occurrence selection/reservation when supplied.
      // This preserves exact opposition identity, provenance and retry semantics.
      const encounterId=action.encounterId||null;
      if (encounterId) {
        if (!getEncounterData(encounterId)) return {success:false,reason:"battle_encounter_authority_missing"};
        const encounterContext={
          sourceKind:"world_opportunity",
          regionKey:definition.regionKey,
          locationId:definition.locationId,
          opportunityId:definition.opportunityId,
          missionAreaId:definition.missionAreaId||null,
          eventId:definition.eventId||null,
          ...(action.encounterContext&&typeof action.encounterContext==="object"
            ? cloneProgressionData(action.encounterContext)
            : {})
        };
        const started=startEncounterActivity(encounterId,startCharacterId,encounterContext);
        if (!started) {
          result={success:false,reason:"battle_launch_failed"};
          break;
        }
        const attached=attachWorldOpportunityBattleReturnContext(battleReturnContext);
        result=attached.success
          ? {success:true,type:"battle",encounterId,returnContext:attached.returnContext}
          : attached;
        break;
      }

      // Compatibility path for genuinely enemy-bound authored actions that have
      // no Encounter definition. This is not legacy map metadata inference.
      const enemyId=action.enemyId||action.encounterRef||null;
      if (!enemyId) return {success:false,reason:"battle_encounter_authority_missing"};
      const battle=startEncounter(enemyId,startCharacterId,definition.eventId||definition.opportunityId);
      if (!battle) {
        result={success:false,reason:"battle_launch_failed"};
        break;
      }
      const attached=attachWorldOpportunityBattleReturnContext(battleReturnContext);
      result=attached.success
        ? {success:true,type:"battle",battle,returnContext:attached.returnContext}
        : attached;
      break;
    }
    case "recruit":
      result=commitRecruitmentOpportunity(definition,action);
      break;
    // BRICK 737 — WORLD OPPORTUNITY → GENERIC STORY SCENE
    case "story_scene": {
      const sceneId=action.sceneId||action.storySceneId||null;
      if (!sceneId) return {success:false,reason:"story_scene_id_missing"};
      const resolvedSceneContext=typeof action.sceneContextResolver==="function"
        ? action.sceneContextResolver({definition,action,playerData,currentBattle,queue:getClanQueueReadModel()})
        : (action.sceneContext||{});
      if (!resolvedSceneContext||typeof resolvedSceneContext!=="object"||Array.isArray(resolvedSceneContext)) return {success:false,reason:"story_scene_context_invalid"};
      result=startStoryScene(sceneId,{
        entryBeatId:action.entryBeatId||null,
        sourceOpportunityId:definition.opportunityId,
        sourceEventId:definition.eventId,
        returnContext:action.returnContext||createWorldOpportunityPresentationReturnContext(definition,action),
        context:resolvedSceneContext
      });
      break;
    }
    case "mission_area": {
      const areaId=action.missionAreaId||action.areaId||null;
      if (!areaId) return {success:false,reason:"mission_area_id_missing"};
      const caller=action.returnContext||createWorldOpportunityPresentationReturnContext(definition,action);
      result=openLocalMissionArea(areaId,{returnContext:caller});
      break;
    }
    case "navigation":
      result={success:!!openOverlay(action.overlayType||"village"),type:"navigation"};
      if (!result.success) result.success=true; // openOverlay is presentation and may return undefined.
      break;
    case "activity": {
      const activity=executePlayerActivity({type:action.activityType||"training",stage:action.activityStage||"available",location:definition.locationId,missionId:action.missionId||null});
      if (action.overlayType) openOverlay(action.overlayType);
      result={success:activity!==false,type:"activity",activity};
      break;
    }
    case "narrative":
      // BRICK 737 — authored narrative opportunities may opt into the same
      // reusable Story Scene runtime without changing their interaction family.
      if (action.sceneId||action.storySceneId) {
        const resolvedSceneContext=typeof action.sceneContextResolver==="function"
          ? action.sceneContextResolver({definition,action,playerData,currentBattle,queue:getClanQueueReadModel()})
          : (action.sceneContext||{});
        if (!resolvedSceneContext||typeof resolvedSceneContext!=="object"||Array.isArray(resolvedSceneContext)) return {success:false,reason:"story_scene_context_invalid"};
        result=startStoryScene(action.sceneId||action.storySceneId,{
          entryBeatId:action.entryBeatId||null,
          sourceOpportunityId:definition.opportunityId,
          sourceEventId:definition.eventId,
          returnContext:action.returnContext||createWorldOpportunityPresentationReturnContext(definition,action),
          context:resolvedSceneContext
        });
        break;
      }
      if (typeof action.resolve==="function") result=action.resolve({definition,action,playerData,currentBattle,queue:getClanQueueReadModel()})||{success:false,reason:"interaction_resolver_no_result"};
      else result={success:false,reason:"interaction_resolver_missing"};
      break;
    case "investigation":
    case "shop":
    case "training":
    case "travel":
    case "discovery":
    case "character":
    case "custom":
      if (typeof action.resolve==="function") result=action.resolve({definition,action,playerData,currentBattle,queue:getClanQueueReadModel()})||{success:false,reason:"interaction_resolver_no_result"};
      else result={success:false,reason:"interaction_resolver_missing"};
      break;
    default:
      result={success:false,reason:"interaction_route_unknown"};
  }

  if (result&&result.success===true&&action.resolutionPatch) setOpportunityResolution(definition.opportunityId,action.resolutionPatch);
  if (result&&result.success===true&&typeof action.onCommitted==="function") action.onCommitted({definition,action,result});
  return result;
}

function refreshActiveWorldOpportunityPresentation() {
  if (currentOverlayType==="mission_area"&&selectedMissionAreaId&&getLocalMissionAreaDefinition(selectedMissionAreaId)) {
    renderLocalMissionAreaUI(selectedMissionAreaId);
    return {success:true,type:"mission_area"};
  }
  if (currentOverlayType==="region"&&selectedRegionKey&&worldRegions[selectedRegionKey]) {
    renderRegionHubUI(selectedRegionKey,worldRegions[selectedRegionKey]);
    return {success:true,type:"region"};
  }
  return {success:false,reason:"world_opportunity_presentation_not_active"};
}

function getWorldOpportunityActionFailurePresentation(reason) {
  switch (String(reason||"")) {
    case "clan_start_slot_empty":
      return {
        title:"BATTLE ORDER REQUIRED",
        detail:"Assign an owned shinobi to START in My Clan before entering Battle.",
        clanRoute:true
      };
    case "battle_launch_failed":
      return {
        title:"BATTLE COULD NOT START",
        detail:"Your current My Clan formation is not legal for this Battle context.",
        clanRoute:true
      };
    case "academy_team_formation_required":
    case "academy_team_formation_continue_required":
      return {title:"TEAM FORMATION REQUIRED",detail:"Complete the Academy Team Formation journey before entering free-play Battle.",clanRoute:false};
    case "genin_roster_transition_required":
      return {title:"ROSTER TRANSITION REQUIRED",detail:"Complete the required Genin roster transition before entering Battle.",clanRoute:false};
    default:
      return {title:"ACTION UNAVAILABLE",detail:String(reason||"The selected action could not be completed.").replaceAll("_"," ").toUpperCase(),clanRoute:false};
  }
}

function executeSelectedOpportunityAction(actionId) {
  if (!selectedOpportunityId) return {success:false,reason:"opportunity_not_selected"};
  const opportunityIdAtInvocation=selectedOpportunityId;
  const result=routeWorldOpportunityInteraction(selectedOpportunityId,actionId);

  if (result&&result.success===true) {
    selectedOpportunityActionFeedback=null;
    // startEncounter() switches currentOverlayType to combat synchronously.
    // Only repaint the originating World presentation when the action stayed on it.
    if (currentOverlayType==="region"||currentOverlayType==="mission_area") {
      refreshActiveWorldOpportunityPresentation();
    }
    return result;
  }

  selectedOpportunityActionFeedback={
    opportunityId:opportunityIdAtInvocation,
    actionId:String(actionId||""),
    reason:result&&result.reason?String(result.reason):"interaction_route_failed"
  };
  if (currentOverlayType==="region"||currentOverlayType==="mission_area") {
    refreshActiveWorldOpportunityPresentation();
  }
  return result;
}

function renderRegionEventDrawer(regionKey) {
  if (!selectedHotspotId) return "";
  const hotspot=getHotspotProjection(regionKey,selectedHotspotId);
  if (!hotspot) return "";
  const selected=hotspot.opportunities.find(item=>item.opportunity_id===selectedOpportunityId)||hotspot.opportunities[0]||null;
  if (!selected) return "";
  selectedOpportunityId=selected.opportunity_id;
  const hasBattle=selected.legal_actions.some(action=>action.kind==="battle");
  const queue=hasBattle?getClanQueueReadModel():[];

  return `
    <aside class="region-event-drawer" style="position:absolute;right:2.5%;top:13%;width:min(390px,34vw);max-height:72%;overflow:auto;z-index:40;background:rgba(6,10,16,.95);border:1px solid rgba(203,161,79,.72);box-shadow:0 16px 45px rgba(0,0,0,.55);padding:16px;color:#e9dfc8;">
      <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;">
        <div><small style="opacity:.68;letter-spacing:.12em;">${selected.presentation_family}${selected.opportunity_category&&selected.opportunity_category!=="OTHER"?` • ${selected.opportunity_category.replaceAll("_"," ")}`:""}</small><h3 style="margin:4px 0 6px;">${selected.known_label}</h3></div>
        <button type="button" onclick="closeRegionEventDrawer()" aria-label="Close event drawer">✕</button>
      </div>
      ${selected.known_summary?`<p style="margin:6px 0 12px;line-height:1.45;">${selected.known_summary}</p>`:""}
      ${hotspot.aggregationCount>1?`<div style="margin:10px 0;"><small>OPPORTUNITIES AT THIS HOTSPOT</small><div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:6px;">${hotspot.opportunities.map(item=>`<button type="button" onclick="selectHotspotOpportunity('${item.opportunity_id}')" ${item.opportunity_id===selected.opportunity_id?'disabled':''}>${item.known_label}</button>`).join("")}</div></div>`:""}
      ${selected.tracking.tracked?`<div style="margin:8px 0;font-size:12px;">TRACKED${selected.tracking.mandatory?" • STORY":""}${selected.tracking.lead_state?` • ${selected.tracking.lead_state}`:""}</div>`:""}
      ${selected.actionability.known_blocker?`<div style="margin:8px 0;color:#d9b56f;">${selected.actionability.known_blocker}</div>`:""}
      ${selectedOpportunityActionFeedback&&selectedOpportunityActionFeedback.opportunityId===selected.opportunity_id?(()=>{const feedback=getWorldOpportunityActionFailurePresentation(selectedOpportunityActionFeedback.reason);return `<div style="margin:10px 0;padding:10px;border:1px solid rgba(215,79,59,.72);background:rgba(78,18,14,.34);"><strong style="display:block;color:#f0b36a;font-size:12px;letter-spacing:.08em;">${feedback.title}</strong><div style="margin-top:5px;font-size:12px;line-height:1.4;color:#e6d8c2;">${feedback.detail}</div>${feedback.clanRoute?`<button type="button" onclick="openOverlay('clan')" style="margin-top:8px;">OPEN MY CLAN</button>`:""}</div>`;})():""}
      ${hasBattle?`<div style="margin:12px 0;padding:10px;border:1px solid rgba(255,255,255,.12);"><small>MY CLAN BATTLE ORDER</small>${queue.map(slot=>`<div style="display:flex;justify-content:space-between;font-size:12px;margin-top:4px;"><span>${slot.label}</span><strong>${slot.name||"—"}</strong></div>`).join("")}</div>`:""}
      <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;">
        ${selected.legal_actions.length?selected.legal_actions.map(action=>`<button type="button" onclick="executeSelectedOpportunityAction('${action.actionId}')" ${action.available?'':'disabled'}>${action.label}</button>`).join(""):`<span style="opacity:.66;font-size:12px;">No authored interaction is currently available.</span>`}
      </div>
    </aside>
  `;
}

function closeRegionEventDrawer() {
  selectedHotspotId=null;
  selectedOpportunityId=null;
  selectedOpportunityActionFeedback=null;
  if (currentOverlayType==="mission_area"&&selectedMissionAreaId) renderLocalMissionAreaUI(selectedMissionAreaId);
  else if (selectedRegionKey&&worldRegions[selectedRegionKey]) renderRegionHubUI(selectedRegionKey,worldRegions[selectedRegionKey]);
}

// =========================================================
// BRICKS 1533–1568 — LOCAL MISSION-AREA PRESENTATION CONSUMER
// =========================================================
// Reuses region hotspot CSS, Event Drawer semantics, observer-safe opportunity
// projection, action resolvers, Story Scene callers and Battle callers.
// No legacy activity-icon mechanics are restored.
// =========================================================
function openLocalMissionArea(areaId,{returnContext=null,hotspotId=null,opportunityId=null,restoring=false}={}) {
  const area=getLocalMissionAreaDefinition(areaId);
  if (!area) return {success:false,reason:"mission_area_missing"};
  if (!area.mapImage) return {success:false,reason:"mission_area_map_missing"};
  if (!restoring&&isAcademyTeamFormationJourneyBlockingFreePlay()) return {success:false,reason:getAcademyTeamFormationJourneyBlockReason(ensurePlayerAcquisitionState())};
  if (!restoring&&isGeninRosterTransitionPending()) return {success:false,reason:"genin_roster_transition_required"};

  // =======================================================
  // BRICKS 1605–1608 — REUSABLE MISSION-AREA ENTRY CONTRACT
  // =======================================================
  // Content may predicate legitimate entry and commit idempotent entry-side
  // World/history state without creating a second event engine. Restoring an
  // already-open area never re-runs the entry contract.
  if (!restoring&&typeof area.evaluateEntry==="function") {
    const evaluated=area.evaluateEntry({
      area,
      returnContext:returnContext&&typeof returnContext==="object"?cloneProgressionData(returnContext):null,
      playerData,
      runtime:ensureWorldEventRuntimeState()
    });
    if (evaluated===false) return {success:false,reason:"mission_area_entry_ineligible"};
    if (evaluated&&typeof evaluated==="object"&&evaluated.available===false) {
      return {success:false,reason:evaluated.reason||"mission_area_entry_ineligible"};
    }
  }
  if (!restoring&&typeof area.onEnter==="function") {
    const entered=area.onEnter({
      area,
      returnContext:returnContext&&typeof returnContext==="object"?cloneProgressionData(returnContext):null,
      playerData,
      runtime:ensureWorldEventRuntimeState()
    });
    if (entered===false) return {success:false,reason:"mission_area_entry_commit_failed"};
    if (entered&&typeof entered==="object"&&entered.success===false) return entered;
  }

  currentOverlayType="mission_area";
  selectedMissionAreaId=area.areaId;
  selectedMissionAreaReturnContext=returnContext&&typeof returnContext==="object"?cloneProgressionData(returnContext):(area.returnContext?cloneProgressionData(area.returnContext):null);
  if (area.parentRegionKey&&worldRegions[area.parentRegionKey]) selectedRegionKey=area.parentRegionKey;
  selectedLocationNode=null;

  const hotspots=getMissionAreaHotspotProjections(area.areaId);
  if (hotspotId) selectedHotspotId=String(hotspotId);
  if (opportunityId) selectedOpportunityId=String(opportunityId);
  if (selectedHotspotId&&!hotspots.some(h=>h.hotspotId===selectedHotspotId)) {
    selectedHotspotId=null;
    selectedOpportunityId=null;
  }
  const selectedHotspot=selectedHotspotId?hotspots.find(h=>h.hotspotId===selectedHotspotId):null;
  if (selectedHotspot&&(!selectedOpportunityId||!selectedHotspot.opportunityIds.includes(selectedOpportunityId))) selectedOpportunityId=selectedHotspot.opportunityIds[0]||null;

  const overlay=typeof document!=="undefined"?document.getElementById("screen-overlay"):null;
  if (overlay) {
    overlay.style.display="flex";
    overlay.classList.add("region-map-open");
  }
  renderLocalMissionAreaUI(area.areaId);
  saveTestState();
  return {success:true,type:"mission_area",missionAreaId:area.areaId,visibleHotspotIds:hotspots.map(h=>h.hotspotId)};
}

function renderLocalMissionAreaHotspot(areaId,hotspot) {
  const hoverSide=getHotspotHoverSide(hotspot.anchor||{x:0,y:0});
  const visualClass=getHotspotPresentationClass(hotspot.presentationFamily);
  const label=hotspot.knownLabel||"???";
  const aggregateSuffix=hotspot.aggregationCount>1?` +${hotspot.aggregationCount-1}`:"";
  return `
    <button type="button" class="region-hotspot region-hotspot-image ${visualClass} ${hoverSide}" style="left:${hotspot.anchor.x}%;top:${hotspot.anchor.y}%;" onclick="selectLocalMissionAreaHotspot('${areaId}','${hotspot.hotspotId}')" aria-label="${label}">
      <span class="hotspot-icon-shell">${hotspot.icon?`<img src="${hotspot.icon}" alt="" class="hotspot-icon-image">`:getRegionSymbol(hotspot.presentationFamily)}</span>
      <span class="hotspot-nameplate">${label}${aggregateSuffix}</span>
      ${renderHotspotHoverCard(hotspot)}
    </button>
  `;
}

function renderLocalMissionAreaEventDrawer(areaId) {
  if (!selectedHotspotId) return "";
  const hotspot=getMissionAreaHotspotProjection(areaId,selectedHotspotId);
  if (!hotspot) return "";
  const selected=hotspot.opportunities.find(item=>item.opportunity_id===selectedOpportunityId)||hotspot.opportunities[0]||null;
  if (!selected) return "";
  selectedOpportunityId=selected.opportunity_id;
  const hasBattle=selected.legal_actions.some(action=>action.kind==="battle");
  const queue=hasBattle?getClanQueueReadModel():[];
  return `
    <aside class="region-event-drawer mission-area-event-drawer" style="position:absolute;right:2.5%;top:13%;width:min(390px,34vw);max-height:72%;overflow:auto;z-index:40;background:rgba(6,10,16,.95);border:1px solid rgba(203,161,79,.72);box-shadow:0 16px 45px rgba(0,0,0,.55);padding:16px;color:#e9dfc8;">
      <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;">
        <div><small style="opacity:.68;letter-spacing:.12em;">${selected.presentation_family}${selected.opportunity_category&&selected.opportunity_category!=="OTHER"?` • ${selected.opportunity_category.replaceAll("_"," ")}`:""}</small><h3 style="margin:4px 0 6px;">${selected.known_label}</h3></div>
        <button type="button" onclick="closeRegionEventDrawer()" aria-label="Close event drawer">✕</button>
      </div>
      ${selected.known_summary?`<p style="margin:6px 0 12px;line-height:1.45;">${selected.known_summary}</p>`:""}
      ${hotspot.aggregationCount>1?`<div style="margin:10px 0;"><small>OPPORTUNITIES AT THIS POINT</small><div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:6px;">${hotspot.opportunities.map(item=>`<button type="button" onclick="selectHotspotOpportunity('${item.opportunity_id}')" ${item.opportunity_id===selected.opportunity_id?'disabled':''}>${item.known_label}</button>`).join("")}</div></div>`:""}
      ${selected.tracking.tracked?`<div style="margin:8px 0;font-size:12px;">TRACKED${selected.tracking.mandatory?" • STORY":""}${selected.tracking.lead_state?` • ${selected.tracking.lead_state}`:""}</div>`:""}
      ${selected.actionability.known_blocker?`<div style="margin:8px 0;color:#d9b56f;">${selected.actionability.known_blocker}</div>`:""}
      ${hasBattle?`<div style="margin:12px 0;padding:10px;border:1px solid rgba(255,255,255,.12);"><small>MY CLAN BATTLE ORDER</small>${queue.map(slot=>`<div style="display:flex;justify-content:space-between;font-size:12px;margin-top:4px;"><span>${slot.label}</span><strong>${slot.name||"—"}</strong></div>`).join("")}</div>`:""}
      <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;">
        ${selected.legal_actions.length?selected.legal_actions.map(action=>`<button type="button" onclick="executeSelectedOpportunityAction('${action.actionId}')" ${action.available?'':'disabled'}>${action.label}</button>`).join(""):`<span style="opacity:.66;font-size:12px;">No authored interaction is currently available.</span>`}
      </div>
    </aside>
  `;
}

function renderLocalMissionAreaUI(areaId) {
  const area=getLocalMissionAreaDefinition(areaId);
  const container=typeof document!=="undefined"?document.getElementById("overlay-content-container"):null;
  if (!area||!container) return;
  const hotspots=getMissionAreaHotspotProjections(area.areaId);
  container.innerHTML=`
    <div class="region-screen-header mission-area-screen-header">
      <div><h2 class="region-screen-title">${area.name.toUpperCase()}</h2><p class="region-screen-description">${area.description}</p></div>
    </div>
    <div class="region-hub-container region-hub-full mission-area-hub">
      <div class="region-map-pane mission-area-map-pane">
        <img src="${area.mapImage}" alt="${area.name}" class="region-map-image mission-area-map-image">
        <button type="button" class="region-world-close" onclick="leaveLocalMissionArea()" aria-label="Leave mission area" title="Leave mission area">✕</button>
        ${hotspots.map(hotspot=>renderLocalMissionAreaHotspot(area.areaId,hotspot)).join("")}
        ${renderLocalMissionAreaEventDrawer(area.areaId)}
      </div>
    </div>`;
}

function selectLocalMissionAreaHotspot(areaId,hotspotId) {
  if (String(areaId||"")!==String(selectedMissionAreaId||"")) return null;
  const hotspot=getMissionAreaHotspotProjection(areaId,hotspotId);
  if (!hotspot) return null;
  selectedHotspotId=hotspot.hotspotId;
  selectedOpportunityId=hotspot.opportunityIds[0]||null;
  renderLocalMissionAreaUI(areaId);
  saveTestState();
  return hotspot;
}

function leaveLocalMissionArea() {
  const returnContext=selectedMissionAreaReturnContext?cloneProgressionData(selectedMissionAreaReturnContext):null;
  selectedMissionAreaId=null;
  selectedMissionAreaReturnContext=null;
  selectedHotspotId=null;
  selectedOpportunityId=null;
  if (returnContext) return resumeStorySceneReturnContext(returnContext);
  const overlay=typeof document!=="undefined"?document.getElementById("screen-overlay"):null;
  if (overlay) overlay.style.display="none";
  currentOverlayType=null;
  saveTestState();
  return {success:true,type:"mission_area_closed"};
}

// =========================================================
// BRICK 696 — MAP / OPPORTUNITY / ACQUISITION REGRESSION
// =========================================================
function runAlphaKnowledgeSensitiveMapDiagnostics() {
  const diagnosticLocationId="diagnostic_world_surface_location";
  const diagnosticHotspotId="diagnostic_world_surface_hotspot";
  const opportunityA="diagnostic_world_surface_a";
  const opportunityB="diagnostic_world_surface_b";
  const eventA="diagnostic_world_event_a";
  const runtime=ensureWorldEventRuntimeState();
  const saved={
    discoveryA:cloneProgressionData(runtime.observerDiscoveryByOpportunityId[opportunityA]||null),
    discoveryB:cloneProgressionData(runtime.observerDiscoveryByOpportunityId[opportunityB]||null),
    trackingA:cloneProgressionData(runtime.trackingByOpportunityId[opportunityA]||null)
  };

  registerWorldEventOpportunity({
    opportunityId:opportunityA,hotspotId:diagnosticHotspotId,eventId:eventA,locationId:diagnosticLocationId,regionKey:"diagnostic",sourceKind:"story",randomPoolEligible:true,defaultDiscoveryLevel:"undiscovered",
    presentation:{family:"Story",label:"Hidden Truth",summary:"Secret summary",showUnknownMarker:true},anchor:{x:40,y:40},
    hiddenPrerequisites:["secret_gate"],hiddenEnemyId:"secret_enemy",hiddenRewardId:"secret_reward",
    interactions:[{id:"inspect",label:"INSPECT",kind:"custom",resolve:()=>({success:true})}]
  });
  registerWorldEventOpportunity({
    opportunityId:opportunityB,hotspotId:diagnosticHotspotId,eventId:"diagnostic_world_event_b",locationId:diagnosticLocationId,regionKey:"diagnostic",sourceKind:"authored",defaultDiscoveryLevel:"discovered",
    presentation:{family:"Discovery",label:"Known Lead",summary:"Known summary"},anchor:{x:40,y:40},interactions:[]
  });

  const hiddenProjection=createObserverSafeOpportunityProjection(getRegisteredWorldEventOpportunity(opportunityA));
  ensureMandatoryStoryOpportunityDiscoverable(opportunityA,{save:false});
  const knownProjection=createObserverSafeOpportunityProjection(getRegisteredWorldEventOpportunity(opportunityA));
  const grouped=getRegionHotspotProjections("diagnostic",{locations:[]});
  const source=ensureWorldEventRuntimeState.toString()+createObserverSafeOpportunityProjection.toString();
  const routerSource=routeWorldOpportunityInteraction.toString();
  const recruitmentSource=commitRecruitmentOpportunity.toString();
  const result={
    noUniversalEventStatus:!source.includes("eventStatus"),
    independentDimensionStores:["worldLifecycleByEventId","observerDiscoveryByOpportunityId","actionabilityByOpportunityId","trackingByOpportunityId","resolutionByOpportunityId"].every(key=>Object.prototype.hasOwnProperty.call(runtime,key)),
    distinctStableIds:knownProjection&&knownProjection.hotspot_id!==knownProjection.location_id&&knownProjection.opportunity_id!==knownProjection.hotspot_id&&knownProjection.event_id!==knownProjection.opportunity_id,
    unknownProjectionHidesTruth:hiddenProjection&&hiddenProjection.known_label==="???"&&!JSON.stringify(hiddenProjection).includes("secret_enemy")&&!JSON.stringify(hiddenProjection).includes("secret_reward")&&!JSON.stringify(hiddenProjection).includes("secret_gate"),
    mandatoryStoryGuaranteedDiscovery:knownProjection&&knownProjection.discovery.known===true&&knownProjection.tracking.mandatory===true,
    storyNeverRandomPool:getRegisteredWorldEventOpportunity(opportunityA).randomPoolEligible===false,
    hotspotCanAggregateIndependentOpportunities:grouped.length===1&&grouped[0].aggregationCount===2&&new Set(grouped[0].opportunityIds).size===2,
    selectionIsNotCommit:selectMapNode.toString().includes("selectedHotspotId")&&!selectMapNode.toString().includes("routeWorldOpportunityInteraction"),
    genericRouterNotFightHardcode:routerSource.includes('case "battle"')&&routerSource.includes('case "recruit"')&&routerSource.includes('case "investigation"'),
    battleConsumesExistingClanOrder:routerSource.includes("getPersistentClanBattleQueueSlots")&&!routerSource.includes("teamSlots="),
    recruitmentUsesExistingAcquisitionAuthority:recruitmentSource.includes("commitCharacterAcquisition")&&!recruitmentSource.includes("grantCharacterRegistryOwnership"),
    discoveryDoesNotGrantOwnership:!setOpportunityDiscovery.toString().includes("commitCharacterAcquisition"),
    observerProjectionOmitsLegacyPLThreat:!renderHotspotHoverCard.toString().includes("getLocationThreat")&&!renderHotspotHoverCard.toString().includes("playerPowerLevel")
  };
  result.pass=Object.values(result).every(value=>value===true);
  console.table(result);

  unregisterWorldEventOpportunity(opportunityA);
  unregisterWorldEventOpportunity(opportunityB);
  if (saved.discoveryA) runtime.observerDiscoveryByOpportunityId[opportunityA]=saved.discoveryA; else delete runtime.observerDiscoveryByOpportunityId[opportunityA];
  if (saved.discoveryB) runtime.observerDiscoveryByOpportunityId[opportunityB]=saved.discoveryB; else delete runtime.observerDiscoveryByOpportunityId[opportunityB];
  if (saved.trackingA) runtime.trackingByOpportunityId[opportunityA]=saved.trackingA; else delete runtime.trackingByOpportunityId[opportunityA];
  return result;
}


// =========================================================
// BRICKS 729–748 — GENERIC DIALOGUE / STORY SCENE RUNTIME
// =========================================================
//
// One reusable scene consumer for Origins, world opportunities, Arena / Promotion,
// recruitment, main Story, post-Battle reactions and later CE-contextual dialogue.
//
// Hard boundaries:
// scene presentation != world truth
// dialogue line != automatic Chronicle fact
// speaker != physical participant
// Battle result != dialogue Knowledge
// choice selection != arbitrary state mutation
// story scene != parallel history store
//
// Current-state persistence lives in playerData.storySceneRuntime. Durable consequences
// must route through an existing domain authority or an authored resolver.
// =========================================================

const STORY_SCENE_PRESENTATION_MODES=Object.freeze([
  "dialogue",
  "internal_voice",
  "narration",
  "choice",
  "battle_transition",
  "post_battle"
]);

// =========================================================
// BRICKS 766–773 — ALPHA STORY SCENE ENVIRONMENT RESOLVER
// =========================================================
// Scene Environment is presentation authority, not world identity.
// location identity != Scene Environment asset != Battle presentation.
// No scene beat needs a bespoke image merely because dialogue exists.
// =========================================================
// =========================================================
// BRICK 791 — CANONICAL SCENE BACKDROP DIRECTORY
// =========================================================
// The folder now exists in the project. This is directory authority only:
// individual files are still registered only when approved assets actually exist.
const ALPHA_SCENE_BACKDROP_ASSET_DIRECTORY="Scene Backdrops/";

function getExpectedAlphaSceneBackdropAssetPath(assetId,extension="png") {
  if (!assetId||!ALPHA_SCENE_ENVIRONMENT_LIBRARY||!ALPHA_SCENE_ENVIRONMENT_LIBRARY[assetId]) return "";
  const ext=String(extension||"png").replace(/^\./,"");
  return `${ALPHA_SCENE_BACKDROP_ASSET_DIRECTORY}${assetId}.${ext}`;
}

const ALPHA_SCENE_ENVIRONMENT_LIBRARY=Object.freeze({
  konoha_academy_classroom_day:Object.freeze({assetId:"konoha_academy_classroom_day",locationAssociations:["konoha:academy:classroom"],status:"core_alpha",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_academy_courtyard_day:Object.freeze({assetId:"konoha_academy_courtyard_day",locationAssociations:["konoha:academy:courtyard","konoha:academy:exterior"],status:"core_alpha",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_village_street_day:Object.freeze({assetId:"konoha_village_street_day",locationAssociations:["konoha:village:street"],status:"core_alpha",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_forest_path_day:Object.freeze({assetId:"konoha_forest_path_day",locationAssociations:["konoha:forest:path"],status:"core_alpha",timeOfDay:"day",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_forest_path_night:Object.freeze({assetId:"konoha_forest_path_night",locationAssociations:["konoha:forest:path"],status:"core_alpha",timeOfDay:"night",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_forest_clearing_day:Object.freeze({assetId:"konoha_forest_clearing_day",locationAssociations:["konoha:forest:clearing"],status:"core_alpha",timeOfDay:"day",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_forest_clearing_night:Object.freeze({assetId:"konoha_forest_clearing_night",locationAssociations:["konoha:forest:clearing"],status:"core_alpha",timeOfDay:"night",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_training_grounds_day:Object.freeze({assetId:"konoha_training_grounds_day",locationAssociations:["konoha:training_grounds"],status:"core_alpha",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_hokage_administration_interior:Object.freeze({assetId:"konoha_hokage_administration_interior",locationAssociations:["konoha:hokage_administration:interior"],status:"core_alpha",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_arena_concourse:Object.freeze({assetId:"konoha_arena_concourse",locationAssociations:["konoha:arena:concourse"],status:"core_alpha",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_arena_ring:Object.freeze({assetId:"konoha_arena_ring",locationAssociations:["konoha:arena:ring"],status:"core_alpha",storyOnly:true,neverBattleSurface:true,aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35}),
  konoha_village_street_night:Object.freeze({assetId:"konoha_village_street_night",locationAssociations:["konoha:village:street"],status:"optional_variant",timeOfDay:"night",aspectRatio:"16:9",masterWidth:1920,masterHeight:1080,dialogueSafeLowerRatio:0.35})
});

const SCENE_LOCATION_ENVIRONMENT_CANDIDATES=Object.freeze(Object.values(ALPHA_SCENE_ENVIRONMENT_LIBRARY).reduce((map,definition)=>{
  (definition.locationAssociations||[]).forEach(locationId=>{if(!map[locationId])map[locationId]=[];map[locationId].push(definition.assetId);});
  return map;
},{}));

function normalizeStorySceneEnvironmentRef(ref) {
  if (!ref) return null;
  if (typeof ref==="string") return {mode:"authored_asset",assetId:String(ref),locationId:null,timeOfDay:null,presentationState:null};
  if (typeof ref!=="object") return null;
  const mode=["authored_asset","location_backdrop","inherit_current"].includes(ref.mode)?ref.mode:(ref.assetId?"authored_asset":(ref.locationId?"location_backdrop":"inherit_current"));
  return {mode,assetId:ref.assetId?String(ref.assetId):null,locationId:ref.locationId?String(ref.locationId):null,timeOfDay:ref.timeOfDay?String(ref.timeOfDay):null,presentationState:ref.presentationState?String(ref.presentationState):null};
}

function resolveSceneEnvironmentAssetForLocation(locationId,timeOfDay=null) {
  if (!locationId) return null;
  const candidates=(SCENE_LOCATION_ENVIRONMENT_CANDIDATES[String(locationId)]||[]).map(assetId=>ALPHA_SCENE_ENVIRONMENT_LIBRARY[assetId]).filter(Boolean);
  if (!candidates.length) return null;
  if (timeOfDay) {const exact=candidates.filter(item=>item.timeOfDay===String(timeOfDay));if(exact.length===1)return exact[0];}
  return candidates.length===1?candidates[0]:null; // never guess day/night
}

function resolveStorySceneEnvironmentProjection(authoredPresentation={},beat=null,definition=null,active=null) {
  const explicit=normalizeStorySceneEnvironmentRef(authoredPresentation.environmentRef||authoredPresentation.sceneEnvironmentRef||null);
  const beatRef=normalizeStorySceneEnvironmentRef(beat&&beat.environmentRef?beat.environmentRef:null);
  const sceneRef=normalizeStorySceneEnvironmentRef(definition&&definition.environmentRef?definition.environmentRef:null);
  const requested=explicit||beatRef||sceneRef;
  const locationId=(requested&&requested.locationId)||(beat&&beat.locationId)||(definition&&definition.locationId)||null;
  const timeOfDay=(requested&&requested.timeOfDay)||(authoredPresentation&&authoredPresentation.timeOfDay)||null;
  if (requested&&requested.mode==="inherit_current") return {mode:"inherit_current",asset_id:null,asset_path:null,location_id:locationId,world_identity_unchanged:true};
  let environment=null;
  if (requested&&requested.assetId) environment=ALPHA_SCENE_ENVIRONMENT_LIBRARY[requested.assetId]||null;
  if (!environment&&locationId) environment=resolveSceneEnvironmentAssetForLocation(locationId,timeOfDay);
  if (!environment) return {mode:"inherit_current",asset_id:null,asset_path:null,location_id:locationId,world_identity_unchanged:true,ambiguous_location_variant:!!(locationId&&(SCENE_LOCATION_ENVIRONMENT_CANDIDATES[locationId]||[]).length>1)};
  return {mode:"dedicated_backdrop",asset_id:environment.assetId,asset_path:getSceneBackdropAssetPath(environment.assetId)||null,location_id:locationId||((environment.locationAssociations||[])[0]||null),status:environment.status,aspect_ratio:environment.aspectRatio,master_resolution:{width:environment.masterWidth,height:environment.masterHeight},dialogue_safe_lower_ratio:environment.dialogueSafeLowerRatio,story_only:environment.storyOnly===true,never_battle_surface:environment.neverBattleSurface===true,world_identity_unchanged:true};
}

const STORY_SCENE_REGISTRY=new Map();

function createDefaultStorySceneRuntimeState() {
  return {
    version:1,
    sequence:0,
    active:null,
    lastFeedbackReceipt:null
  };
}

function normalizeStorySceneRuntimeState(savedState) {
  const source=savedState&&typeof savedState==="object"?savedState:{};
  const active=source.active&&typeof source.active==="object"?source.active:null;
  const normalizedActive=active&&typeof active.sceneId==="string"&&typeof active.beatId==="string"
    ? {
        instanceId:typeof active.instanceId==="string"?active.instanceId:null,
        sceneId:active.sceneId,
        beatId:active.beatId,
        startedAt:Number(active.startedAt)||null,
        sourceEventId:typeof active.sourceEventId==="string"?active.sourceEventId:null,
        sourceOpportunityId:typeof active.sourceOpportunityId==="string"?active.sourceOpportunityId:null,
        returnContext:active.returnContext&&typeof active.returnContext==="object"?cloneProgressionData(active.returnContext):null,
        presentationUnderlay:active.presentationUnderlay&&typeof active.presentationUnderlay==="object"?cloneProgressionData(active.presentationUnderlay):null,
        localContext:active.localContext&&typeof active.localContext==="object"?cloneProgressionData(active.localContext):{},
        processedConsequenceKeys:Array.isArray(active.processedConsequenceKeys)?[...new Set(active.processedConsequenceKeys.filter(Boolean))]:[],
        committedChoiceKeys:Array.isArray(active.committedChoiceKeys)?[...new Set(active.committedChoiceKeys.filter(Boolean))]:[],
        pendingBattle:active.pendingBattle&&typeof active.pendingBattle==="object"?cloneProgressionData(active.pendingBattle):null,
        battleResume:active.battleResume&&typeof active.battleResume==="object"?cloneProgressionData(active.battleResume):null
      }
    : null;
  return {
    version:1,
    sequence:Math.max(0,Number(source.sequence)||0),
    active:normalizedActive,
    lastFeedbackReceipt:source.lastFeedbackReceipt&&typeof source.lastFeedbackReceipt==="object"
      ? normalizeStorySceneFeedbackReceipt(source.lastFeedbackReceipt)
      : null
  };
}

function ensureStorySceneRuntimeState() {
  if (!playerData.storySceneRuntime||typeof playerData.storySceneRuntime!=="object") {
    playerData.storySceneRuntime=createDefaultStorySceneRuntimeState();
  } else {
    const state=playerData.storySceneRuntime;
    const structurallyReady=state.version===1&&Number.isFinite(Number(state.sequence))&&Object.prototype.hasOwnProperty.call(state,"active")&&Object.prototype.hasOwnProperty.call(state,"lastFeedbackReceipt");
    if (!structurallyReady) playerData.storySceneRuntime=normalizeStorySceneRuntimeState(state);
  }
  return playerData.storySceneRuntime;
}

function normalizeStorySceneSourceRef(sourceRef,mode="dialogue") {
  if (!sourceRef) return null;
  if (typeof sourceRef==="string") {
    return {
      sourceId:sourceRef,
      sourceType:"stable_source",
      physicalPresence:mode==="internal_voice"?false:null,
      displayName:null,
      portraitRef:null
    };
  }
  if (typeof sourceRef!=="object"||!sourceRef.sourceId) return null;
  return {
    sourceId:String(sourceRef.sourceId),
    sourceType:String(sourceRef.sourceType||"stable_source"),
    physicalPresence:sourceRef.physicalPresence===true?true:(sourceRef.physicalPresence===false?false:(mode==="internal_voice"?false:null)),
    displayName:sourceRef.displayName?String(sourceRef.displayName):null,
    portraitRef:sourceRef.portraitRef?cloneProgressionData(sourceRef.portraitRef):null
  };
}

function normalizeStorySceneParticipant(participant) {
  if (!participant) return null;
  if (typeof participant==="string") return {sourceId:participant,physicalPresence:true,visible:true,role:null,displayName:null,portraitRef:null};
  if (typeof participant!=="object"||!participant.sourceId) return null;
  return {
    sourceId:String(participant.sourceId),
    physicalPresence:participant.physicalPresence!==false,
    visible:participant.visible!==false,
    role:participant.role?String(participant.role):null,
    displayName:participant.displayName?String(participant.displayName):null,
    portraitRef:participant.portraitRef?cloneProgressionData(participant.portraitRef):null
  };
}

// =========================================================
// BRICKS 752–754 — STORY PRESENTATION / PORTRAIT BOUNDARIES
// =========================================================
const STORY_SCENE_UI_MODE_BY_RUNTIME_MODE=Object.freeze({
  dialogue:"character",
  internal_voice:"internal_or_remote_voice",
  narration:"narration_action",
  choice:"choice",
  battle_transition:"battle_transition",
  post_battle:"post_battle"
});

function normalizeStoryScenePortraitProjection(ref) {
  if (!ref) return null;
  if (typeof ref==="string") return {src:ref,kind:"authored_path",alt:null};
  if (typeof ref!=="object") return null;

  let src=ref.src||ref.path||null;
  const assetType=ref.assetType||ref.kind||null;
  const assetId=ref.assetId||ref.id||null;

  // Collectible-card fallback is NEVER automatic. Writing/UI must explicitly
  // author that fallback kind so card art is not silently treated as portrait art.
  if (!src&&assetType==="character_card"&&assetId) src=getCharacterCardAssetPath(assetId);
  // BRICK 1056 — entity collectible cards are resolved only when explicitly
  // authored as entity_card. They never become automatic uiPortrait fallback.
  if (!src&&assetType==="entity_card"&&assetId) src=getEntityCollectibleCardAssetPath(assetId);
  if (!src&&assetType==="hosted_entity"&&assetId) src=getHostedEntityAssetPath(assetId);
  if (!src&&assetType==="ui"&&assetId) src=getUIAssetPath(assetId);
  if (!src) return null;
  return {src:String(src),kind:String(assetType||"authored_path"),alt:ref.alt?String(ref.alt):null};
}

function resolveStoryScenePortraitProjection(authoredPresentation,beat,speakerRef) {
  const explicit=authoredPresentation&&authoredPresentation.portraitRef
    ? authoredPresentation.portraitRef
    : (speakerRef&&speakerRef.portraitRef?speakerRef.portraitRef:null);
  const uiFallback=beat&&beat.uiHints&&beat.uiHints.dialoguePortraitRef?beat.uiHints.dialoguePortraitRef:null;
  return normalizeStoryScenePortraitProjection(explicit||uiFallback);
}

function createStorySceneTransitionInstruction(beat) {
  if (!beat) return null;
  if (beat.mode==="choice") return {kind:"choice",requires_explicit_player_action:true};
  if (beat.mode==="battle_transition") return {kind:"battle",requires_explicit_player_action:true};
  if (beat.exitScene===true||!beat.nextBeatId) return {kind:"complete",requires_explicit_player_action:true};
  return {kind:"advance",requires_explicit_player_action:true};
}

function captureStoryScenePresentationUnderlay() {
  const overlay=typeof document!=="undefined"?document.getElementById("screen-overlay"):null;
  return {
    overlayType:currentOverlayType||null,
    overlayVisible:!!(overlay&&overlay.style.display!=="none"),
    regionKey:selectedRegionKey||null,
    missionAreaId:selectedMissionAreaId||null,
    missionAreaReturnContext:selectedMissionAreaReturnContext?cloneProgressionData(selectedMissionAreaReturnContext):null,
    hotspotId:selectedHotspotId||null,
    opportunityId:selectedOpportunityId||null
  };
}

function restoreStoryScenePresentationUnderlay(underlay) {
  if (!underlay||typeof underlay!=="object") return {success:true,type:"underlay_unchanged"};
  hideStoryScenePresentationLayer({preserveRuntime:true});

  if (underlay.overlayType==="mission_area"&&underlay.missionAreaId&&getLocalMissionAreaDefinition(underlay.missionAreaId)) {
    return openLocalMissionArea(underlay.missionAreaId,{
      returnContext:underlay.missionAreaReturnContext||null,
      hotspotId:underlay.hotspotId||null,
      opportunityId:underlay.opportunityId||null,
      restoring:true
    });
  }

  if (underlay.overlayType==="region"&&underlay.regionKey&&worldRegions[underlay.regionKey]) {
    openRegionHub(underlay.regionKey);
    selectedHotspotId=underlay.hotspotId||null;
    selectedOpportunityId=underlay.opportunityId||null;
    renderRegionHubUI(underlay.regionKey,worldRegions[underlay.regionKey]);
    return {success:true,type:"region"};
  }
  if (underlay.overlayType&&underlay.overlayType!=="story_scene") {
    openOverlay(underlay.overlayType);
    return {success:true,type:"overlay",overlayType:underlay.overlayType};
  }
  if (underlay.overlayVisible!==true) {
    const overlay=typeof document!=="undefined"?document.getElementById("screen-overlay"):null;
    if (overlay) overlay.style.display="none";
    currentOverlayType=null;
  }
  return {success:true,type:"world"};
}

function normalizeStorySceneChoice(choice,index=0) {
  if (!choice||typeof choice!=="object") return null;
  const authoredChoiceId=choice.choiceId||choice.id||null;
  if (!authoredChoiceId) return null;
  const choiceId=String(authoredChoiceId);
  return {
    choiceId,
    label:String(choice.label||choice.text||choiceId),
    nextBeatId:choice.nextBeatId?String(choice.nextBeatId):null,
    availability:typeof choice.availability==="function"?choice.availability:null,
    knownBlocker:choice.knownBlocker?String(choice.knownBlocker):null,
    consequenceRequests:Array.isArray(choice.consequenceRequests)?choice.consequenceRequests.map(item=>cloneStorySceneAuthoredValue(item)):[],
    contextPatch:choice.contextPatch&&typeof choice.contextPatch==="object"?cloneProgressionData(choice.contextPatch):null
  };
}

function cloneStorySceneAuthoredValue(value) {
  if (typeof value==="function") return value;
  if (Array.isArray(value)) return value.map(cloneStorySceneAuthoredValue);
  if (value&&typeof value==="object") {
    const out={};
    Object.entries(value).forEach(([key,item])=>{out[key]=cloneStorySceneAuthoredValue(item);});
    return out;
  }
  return value;
}

function normalizeStorySceneBattleContract(contract) {
  if (!contract||typeof contract!=="object") return null;
  return {
    enemyId:contract.enemyId?String(contract.enemyId):null,
    encounterId:contract.encounterId?String(contract.encounterId):null,
    // Authored encounter packages with their own exact participant/objective caller
    // may provide one launcher. This is still the same Story -> Battle -> same Story
    // bridge; it does not create a second Battle subsystem.
    launchResolver:typeof contract.launchResolver==="function"?contract.launchResolver:null,
    victoryBeatId:contract.victoryBeatId?String(contract.victoryBeatId):null,
    defeatBeatId:contract.defeatBeatId?String(contract.defeatBeatId):null,
    postBattleBeatId:contract.postBattleBeatId?String(contract.postBattleBeatId):null,
    resultProjector:typeof contract.resultProjector==="function"?contract.resultProjector:null,
    exposeFinisher:contract.exposeFinisher===true,
    actionLabel:String(contract.actionLabel||"BEGIN BATTLE")
  };
}

function normalizeStorySceneBeat(beat,index=0) {
  if (!beat||typeof beat!=="object") return null;
  const authoredBeatId=beat.beatId||beat.id||null;
  if (!authoredBeatId) return null;
  const beatId=String(authoredBeatId);
  const mode=STORY_SCENE_PRESENTATION_MODES.includes(beat.mode)?beat.mode:"dialogue";
  return {
    beatId,
    mode,
    speakerRef:normalizeStorySceneSourceRef(beat.speakerRef||beat.speakerSourceId||beat.speakerId||null,mode),
    speakerName:beat.speakerName?String(beat.speakerName):null,
    text:typeof beat.text==="string"?beat.text:"",
    locationId:beat.locationId?String(beat.locationId):null,
    environmentRef:normalizeStorySceneEnvironmentRef(beat.environmentRef||beat.sceneEnvironmentRef||null),
    presentationResolver:typeof beat.presentationResolver==="function"?beat.presentationResolver:null,
    nextBeatId:beat.nextBeatId?String(beat.nextBeatId):null,
    choices:Array.isArray(beat.choices)?beat.choices.map(normalizeStorySceneChoice).filter(Boolean):[],
    battle:normalizeStorySceneBattleContract(beat.battle||beat.battleContract||null),
    onEnterConsequences:Array.isArray(beat.onEnterConsequences)?beat.onEnterConsequences.map(cloneStorySceneAuthoredValue):[],
    onAdvanceConsequences:Array.isArray(beat.onAdvanceConsequences)?beat.onAdvanceConsequences.map(cloneStorySceneAuthoredValue):[],
    exitScene:beat.exitScene===true,
    allowPresentationClose:beat.allowPresentationClose===true,
    uiHints:beat.uiHints&&typeof beat.uiHints==="object"?cloneProgressionData(beat.uiHints):{}
  };
}

function normalizeStorySceneDefinition(definition) {
  if (!definition||typeof definition!=="object"||!definition.sceneId) return null;
  const beats=Array.isArray(definition.beats)?definition.beats.map(normalizeStorySceneBeat).filter(Boolean):[];
  if (!beats.length) return null;
  const beatIds=new Set();
  for (const beat of beats) {
    if (beatIds.has(beat.beatId)) return null;
    beatIds.add(beat.beatId);
  }
  const entryBeatId=definition.entryBeatId?String(definition.entryBeatId):beats[0].beatId;
  if (!beatIds.has(entryBeatId)) return null;
  return {
    sceneId:String(definition.sceneId),
    eventId:definition.eventId?String(definition.eventId):null,
    title:definition.title?String(definition.title):null,
    entryBeatId,
    locationId:definition.locationId?String(definition.locationId):null,
    environmentRef:normalizeStorySceneEnvironmentRef(definition.environmentRef||definition.sceneEnvironmentRef||null),
    participants:Array.isArray(definition.participants)?definition.participants.map(normalizeStorySceneParticipant).filter(Boolean):[],
    beats,
    beatMap:new Map(beats.map(beat=>[beat.beatId,beat])),
    defaultReturnContext:definition.defaultReturnContext&&typeof definition.defaultReturnContext==="object"?cloneProgressionData(definition.defaultReturnContext):null,
    contextResolver:typeof definition.contextResolver==="function"?definition.contextResolver:null,
    onCompleteConsequences:Array.isArray(definition.onCompleteConsequences)?definition.onCompleteConsequences.map(cloneStorySceneAuthoredValue):[]
  };
}

function registerStoryScene(definition) {
  const normalized=normalizeStorySceneDefinition(definition);
  if (!normalized) return {success:false,reason:"story_scene_definition_invalid"};
  STORY_SCENE_REGISTRY.set(normalized.sceneId,normalized);
  return {success:true,sceneId:normalized.sceneId,definition:normalized};
}

function unregisterStoryScene(sceneId) {
  return STORY_SCENE_REGISTRY.delete(String(sceneId||""));
}

function getStorySceneDefinition(sceneId) {
  return STORY_SCENE_REGISTRY.get(String(sceneId||""))||null;
}

function getActiveStorySceneRuntime() {
  const state=ensureStorySceneRuntimeState();
  return state.active||null;
}

function getActiveStorySceneDefinition() {
  const active=getActiveStorySceneRuntime();
  return active?getStorySceneDefinition(active.sceneId):null;
}

function getCurrentStorySceneBeat() {
  const active=getActiveStorySceneRuntime();
  const definition=getActiveStorySceneDefinition();
  return active&&definition?definition.beatMap.get(active.beatId)||null:null;
}

function createStorySceneInstanceId(sceneId,runtimeState=null) {
  const state=runtimeState&&typeof runtimeState==="object"?runtimeState:ensureStorySceneRuntimeState();
  state.sequence=Math.max(0,Number(state.sequence)||0)+1;
  return `story_scene_${String(sceneId||"scene")}_${state.sequence}_${Date.now()}`;
}

function getStorySceneRuntimeContext() {
  const active=getActiveStorySceneRuntime();
  const definition=getActiveStorySceneDefinition();
  const base={
    sceneId:active?active.sceneId:null,
    beatId:active?active.beatId:null,
    instanceId:active?active.instanceId:null,
    sourceEventId:active?active.sourceEventId:null,
    sourceOpportunityId:active?active.sourceOpportunityId:null,
    localContext:active?cloneProgressionData(active.localContext||{}):{},
    battleResume:active&&active.battleResume?cloneProgressionData(active.battleResume):null
  };
  if (definition&&typeof definition.contextResolver==="function") {
    const authored=definition.contextResolver({playerData,active:cloneProgressionData(active),base:cloneProgressionData(base)});
    if (authored&&typeof authored==="object") base.authoredContext=cloneProgressionData(authored);
  }
  return base;
}

function evaluateStorySceneChoiceAvailability(choice) {
  if (!choice) return {available:false,knownBlocker:null};
  if (typeof choice.availability!=="function") return {available:true,knownBlocker:null};
  const result=choice.availability(getStorySceneRuntimeContext());
  if (result===true) return {available:true,knownBlocker:null};
  if (result===false||result==null) return {available:false,knownBlocker:choice.knownBlocker||null};
  if (typeof result==="object") return {available:result.available===true,knownBlocker:result.knownBlocker?String(result.knownBlocker):null};
  return {available:false,knownBlocker:null};
}

function normalizeStorySceneFeedbackReceipt(receipt) {
  if (!receipt||typeof receipt!=="object") return null;
  return {
    receiptId:receipt.receiptId?String(receipt.receiptId):null,
    kind:receipt.kind?String(receipt.kind):"chronicle_update",
    label:receipt.label?String(receipt.label):"Chronicle Updated",
    timestamp:Number(receipt.timestamp)||Date.now()
  };
}

function emitStorySceneFeedbackReceipt(receipt) {
  const safe=normalizeStorySceneFeedbackReceipt(receipt);
  if (!safe) return null;
  ensureStorySceneRuntimeState().lastFeedbackReceipt=safe;
  savePlayerData();
  return cloneProgressionData(safe);
}

function getStorySceneFeedbackReceipt() {
  const receipt=ensureStorySceneRuntimeState().lastFeedbackReceipt;
  return receipt?cloneProgressionData(receipt):null;
}

function clearStorySceneFeedbackReceipt() {
  ensureStorySceneRuntimeState().lastFeedbackReceipt=null;
  savePlayerData();
  return true;
}

function processStorySceneConsequenceRequest(request,context={}) {
  if (!request||typeof request!=="object") return {success:false,reason:"scene_consequence_request_invalid"};
  const kind=String(request.kind||request.type||"custom");
  switch (kind) {
    case "character_acquisition":
      return commitCharacterAcquisition({
        variantId:request.variantId,
        route:request.route||"story_scene",
        sourceEventId:request.sourceEventId||context.sourceEventId||context.sceneId||null,
        context:request.context||{sceneId:context.sceneId||null,beatId:context.beatId||null},
        provenance:request.provenance||{authority:"authored_story_scene"},
        linkedChronicleEvidenceIds:Array.isArray(request.linkedChronicleEvidenceIds)?request.linkedChronicleEvidenceIds:[]
      });
    case "world_opportunity_resolution":
      if (!request.opportunityId&&!context.sourceOpportunityId) return {success:false,reason:"opportunity_id_missing"};
      setOpportunityResolution(request.opportunityId||context.sourceOpportunityId,request.patch||{},request.options||{});
      return {success:true,type:kind};
    case "world_opportunity_discovery":
      if (!request.opportunityId&&!context.sourceOpportunityId) return {success:false,reason:"opportunity_id_missing"};
      setOpportunityDiscovery(request.opportunityId||context.sourceOpportunityId,request.patch||{},request.options||{});
      return {success:true,type:kind};
    case "world_opportunity_tracking":
      if (!request.opportunityId&&!context.sourceOpportunityId) return {success:false,reason:"opportunity_id_missing"};
      setOpportunityTracking(request.opportunityId||context.sourceOpportunityId,request.patch||{},request.options||{});
      return {success:true,type:kind};
    case "activity": {
      const activity=executePlayerActivity(request.activityRequest||{});
      return {success:activity!==false,type:kind,activity};
    }
    case "feedback": {
      const receipt=emitStorySceneFeedbackReceipt({receiptId:request.receiptId||null,kind:request.feedbackKind||"chronicle_update",label:request.label||"Chronicle Updated"});
      return {success:!!receipt,type:kind,receipt};
    }
    case "custom":
    case "domain":
    case "chronicle":
      if (typeof request.resolve!=="function") return {success:false,reason:"authored_domain_resolver_missing"};
      return request.resolve({
        request,
        sceneContext:cloneProgressionData(context),
        playerData,
        currentBattle,
        activeScene:getActiveStorySceneRuntime()
      })||{success:false,reason:"authored_domain_resolver_no_result"};
    default:
      return {success:false,reason:"scene_consequence_route_unknown"};
  }
}

function processStorySceneConsequenceRequests(requests,phaseKey) {
  const active=getActiveStorySceneRuntime();
  if (!active) return {success:false,reason:"story_scene_not_active",results:[]};
  const list=Array.isArray(requests)?requests:[];
  const results=[];
  for (let index=0;index<list.length;index+=1) {
    const request=list[index];
    const stableKey=String((request&&request.requestId)||`${active.sceneId}:${active.beatId}:${phaseKey}:${index}`);
    if (active.processedConsequenceKeys.includes(stableKey)) {
      results.push({success:true,idempotent:true,requestKey:stableKey});
      continue;
    }
    const result=processStorySceneConsequenceRequest(request,{
      sceneId:active.sceneId,
      beatId:active.beatId,
      instanceId:active.instanceId,
      sourceEventId:active.sourceEventId,
      sourceOpportunityId:active.sourceOpportunityId,
      phase:phaseKey
    });
    results.push(result);
    if (!result||result.success!==true) return {success:false,reason:(result&&result.reason)||"scene_consequence_failed",results};
    active.processedConsequenceKeys.push(stableKey);
  }
  savePlayerData();
  return {success:true,results};
}

function createStorySceneObserverSafeProjection() {
  const active=getActiveStorySceneRuntime();
  const definition=getActiveStorySceneDefinition();
  const beat=getCurrentStorySceneBeat();
  if (!active||!definition||!beat) return null;

  const context=getStorySceneRuntimeContext();
  let authoredPresentation={};
  if (typeof beat.presentationResolver==="function") {
    const resolved=beat.presentationResolver(context);
    if (resolved&&typeof resolved==="object") authoredPresentation=resolved;
  }

  const speakerRef=normalizeStorySceneSourceRef(authoredPresentation.speakerRef||beat.speakerRef,beat.mode);
  const choices=beat.choices.map(choice=>{
    const availability=evaluateStorySceneChoiceAvailability(choice);
    return {
      choice_id:choice.choiceId,
      label:choice.label,
      available:availability.available===true,
      known_blocker:availability.knownBlocker||null
    };
  });
  const physicalParticipants=definition.participants
    .filter(participant=>participant.visible!==false&&participant.physicalPresence===true)
    .map(participant=>({
      source_id:participant.sourceId,
      role:participant.role||null,
      display_name:participant.displayName||null,
      portrait_ref:normalizeStoryScenePortraitProjection(participant.portraitRef)
    }));
  const portraitProjection=resolveStoryScenePortraitProjection(authoredPresentation,beat,speakerRef);
  const sceneEnvironment=resolveStorySceneEnvironmentProjection(authoredPresentation,beat,definition,active);

  return {
    scene_id:active.sceneId,
    scene_instance_id:active.instanceId,
    beat_id:active.beatId,
    mode:beat.mode,
    ui_mode:STORY_SCENE_UI_MODE_BY_RUNTIME_MODE[beat.mode]||"character",
    title:authoredPresentation.title?String(authoredPresentation.title):(definition.title||null),
    speaker_source_id:speakerRef?speakerRef.sourceId:null,
    speaker_source_type:speakerRef?speakerRef.sourceType:null,
    speaker_name:authoredPresentation.speakerName?String(authoredPresentation.speakerName):(beat.speakerName||(speakerRef&&speakerRef.displayName)||null),
    speaker_physically_present:speakerRef?speakerRef.physicalPresence:null,
    portrait_ref:portraitProjection,
    scene_environment:sceneEnvironment,
    text:typeof authoredPresentation.text==="string"?authoredPresentation.text:beat.text,
    physical_participants:physicalParticipants,
    choices,
    transition_instruction:createStorySceneTransitionInstruction(beat),
    has_next:!!beat.nextBeatId||beat.exitScene===true,
    battle_transition:beat.mode==="battle_transition"&&beat.battle?{
      available:!!beat.battle.enemyId||typeof beat.battle.launchResolver==="function",
      action_label:beat.battle.actionLabel,
      encounter_ref:beat.battle.encounterId||null
    }:null,
    post_battle_context:beat.mode==="post_battle"&&active.battleResume?cloneProgressionData(active.battleResume):null,
    ui_hints:cloneProgressionData(beat.uiHints||{}),
    feedback_receipt:getStorySceneFeedbackReceipt()
  };
}

function startStoryScene(sceneId,options={}) {
  const definition=getStorySceneDefinition(sceneId);
  if (!definition) return {success:false,reason:"story_scene_not_registered"};
  const entryBeatId=options.entryBeatId||definition.entryBeatId;
  if (!definition.beatMap.has(entryBeatId)) return {success:false,reason:"story_scene_entry_beat_missing"};
  const state=ensureStorySceneRuntimeState();
  const presentationUnderlay=captureStoryScenePresentationUnderlay();
  state.active={
    instanceId:createStorySceneInstanceId(sceneId,state),
    sceneId:definition.sceneId,
    beatId:entryBeatId,
    startedAt:Date.now(),
    sourceEventId:options.sourceEventId||definition.eventId||null,
    sourceOpportunityId:options.sourceOpportunityId||null,
    returnContext:options.returnContext?cloneProgressionData(options.returnContext):(definition.defaultReturnContext?cloneProgressionData(definition.defaultReturnContext):null),
    presentationUnderlay,
    localContext:options.context&&typeof options.context==="object"?cloneProgressionData(options.context):{},
    processedConsequenceKeys:[],
    committedChoiceKeys:[],
    pendingBattle:null,
    battleResume:null
  };
  const beat=getCurrentStorySceneBeat();
  const entered=processStorySceneConsequenceRequests(beat?beat.onEnterConsequences:[],"enter");
  if (!entered.success) return entered;
  savePlayerData();
  openOverlay("story_scene");
  return {success:true,type:"story_scene",sceneId:definition.sceneId,beatId:entryBeatId,instanceId:state.active.instanceId};
}

function setStorySceneBeat(beatId,options={}) {
  const active=getActiveStorySceneRuntime();
  const definition=getActiveStorySceneDefinition();
  if (!active||!definition) return {success:false,reason:"story_scene_not_active"};
  if (!definition.beatMap.has(beatId)) return {success:false,reason:"story_scene_beat_missing"};
  active.beatId=beatId;
  const beat=definition.beatMap.get(beatId);
  const entered=processStorySceneConsequenceRequests(beat.onEnterConsequences,"enter");
  if (!entered.success) return entered;
  savePlayerData();
  if (options.render!==false) openOverlay("story_scene");
  return {success:true,beatId};
}

function applyStorySceneChoice(choiceId) {
  const active=getActiveStorySceneRuntime();
  const beat=getCurrentStorySceneBeat();
  if (!active||!beat) return {success:false,reason:"story_scene_not_active"};
  const choice=beat.choices.find(item=>item.choiceId===choiceId)||null;
  if (!choice) return {success:false,reason:"story_choice_missing"};
  const availability=evaluateStorySceneChoiceAvailability(choice);
  if (!availability.available) return {success:false,reason:"story_choice_unavailable",knownBlocker:availability.knownBlocker||null};
  const choiceKey=`${active.instanceId}:${beat.beatId}:${choice.choiceId}`;
  if (active.committedChoiceKeys.includes(choiceKey)) return {success:false,reason:"story_choice_already_committed"};
  const consequences=processStorySceneConsequenceRequests(choice.consequenceRequests,`choice:${choice.choiceId}`);
  if (!consequences.success) return consequences;
  active.committedChoiceKeys.push(choiceKey);
  if (choice.contextPatch) active.localContext={...(active.localContext||{}),...cloneProgressionData(choice.contextPatch)};
  savePlayerData();
  if (choice.nextBeatId) return setStorySceneBeat(choice.nextBeatId);
  if (beat.nextBeatId) return setStorySceneBeat(beat.nextBeatId);
  return completeStoryScene({reason:"choice_terminal"});
}

function launchBattleWithReturnContext(enemyId,encounterId,returnContext) {
  const normalizedReturnContext=normalizeBattleReturnContext(returnContext);
  if (returnContext&&typeof returnContext==="object"&&!normalizedReturnContext) return {success:false,reason:"battle_return_context_invalid"};
  const battle=startEncounter(enemyId,null,encounterId||null);
  if (!battle) return {success:false,reason:"battle_launch_failed"};
  currentBattle.returnContext=normalizedReturnContext;
  currentBattle.observerSafeResultContext=null;
  saveTestState();
  return {success:true,battleId:currentBattle.battleId,encounterId:currentBattle.encounterId,returnContext:cloneBattleRuntimeValue(currentBattle.returnContext)};
}

function launchStorySceneBattle() {
  const active=getActiveStorySceneRuntime();
  const beat=getCurrentStorySceneBeat();
  if (!active||!beat) return {success:false,reason:"story_scene_not_active"};
  if (beat.mode!=="battle_transition"||!beat.battle) return {success:false,reason:"story_beat_not_battle_transition"};
  if (!beat.battle.enemyId&&typeof beat.battle.launchResolver!=="function") return {success:false,reason:"story_battle_enemy_authority_missing"};
  if (active.pendingBattle&&active.pendingBattle.battleId) return {success:false,reason:"story_battle_already_pending"};

  const returnContext={
    type:"story_scene",
    sceneId:active.sceneId,
    sceneInstanceId:active.instanceId,
    sourceBeatId:beat.beatId,
    victoryBeatId:beat.battle.victoryBeatId,
    defeatBeatId:beat.battle.defeatBeatId,
    postBattleBeatId:beat.battle.postBattleBeatId,
    exposeFinisher:beat.battle.exposeFinisher===true,
    resultProjector:beat.battle.resultProjector||null
  };
  // Functions cannot survive save serialization; keep executable authored resolvers
  // on the registered beat and persist only stable routing fields.
  const saveableReturnContext={...returnContext};
  delete saveableReturnContext.resultProjector;
  hideStoryScenePresentationLayer({preserveRuntime:true});

  let launched=null;
  if (typeof beat.battle.launchResolver==="function") {
    launched=beat.battle.launchResolver({
      active:cloneProgressionData(active),
      beatId:beat.beatId,
      returnContext:cloneProgressionData(saveableReturnContext),
      sceneContext:getStorySceneRuntimeContext(),
      playerData,
      currentBattle
    })||{success:false,reason:"story_battle_authored_launcher_no_result"};
  } else {
    launched=launchBattleWithReturnContext(beat.battle.enemyId,beat.battle.encounterId||active.sourceEventId||active.sceneId,saveableReturnContext);
  }
  if (!launched||launched.success!==true) {
    restoreStoryScenePresentationUnderlay(active.presentationUnderlay);
    openOverlay("story_scene");
    return launched||{success:false,reason:"story_battle_launch_failed"};
  }
  active.pendingBattle={
    battleId:launched.battleId||currentBattle.battleId||null,
    encounterId:launched.encounterId||currentBattle.encounterId||beat.battle.encounterId||null,
    sourceBeatId:beat.beatId,
    victoryBeatId:beat.battle.victoryBeatId,
    defeatBeatId:beat.battle.defeatBeatId,
    postBattleBeatId:beat.battle.postBattleBeatId
  };
  savePlayerData();
  saveTestState();
  return {success:true,type:"battle_transition",battleId:active.pendingBattle.battleId,encounterId:active.pendingBattle.encounterId};
}

function getStorySceneBattleResultProjector(returnContext) {
  if (!returnContext||returnContext.type!=="story_scene") return null;
  const definition=getStorySceneDefinition(returnContext.sceneId);
  const beat=definition&&definition.beatMap?definition.beatMap.get(returnContext.sourceBeatId):null;
  return beat&&beat.battle&&typeof beat.battle.resultProjector==="function"?beat.battle.resultProjector:null;
}

function createObserverSafeStoryBattleResult(returnContext) {
  const outcome=currentBattle.outcome&&typeof currentBattle.outcome==="object"?currentBattle.outcome:null;
  if (!outcome) return null;
  const safe={
    outcome:outcome.type==="victory"?"victory":"defeat",
    battle_id:currentBattle.battleId||null,
    encounter_id:currentBattle.encounterId||null,
    completed_at:Number(outcome.completedAt)||Number(currentBattle.completedAt)||null
  };
  if (returnContext&&returnContext.exposeFinisher===true&&outcome.type==="victory"&&outcome.finishingShinobiId) {
    safe.finishing_shinobi_id=outcome.finishingShinobiId;
  }
  const projector=getStorySceneBattleResultProjector(returnContext);
  if (projector) {
    const projected=projector({
      outcome:cloneBattleRuntimeValue(outcome),
      battleId:currentBattle.battleId,
      encounterId:currentBattle.encounterId,
      getEvidence:()=>cloneBattleRuntimeValue((currentBattle.runtime&&currentBattle.runtime.evidence)||[]),
      getRemainingBattlePL:(side,participantId)=>getBattleRemainingPL(side,participantId)
    });
    if (projected&&typeof projected==="object") safe.authored=cloneBattleRuntimeValue(projected);
  }
  return safe;
}

function resumeStorySceneFromBattle(returnContext) {
  if (!returnContext||returnContext.type!=="story_scene") return {success:false,reason:"story_return_context_missing"};
  const active=getActiveStorySceneRuntime();
  if (!active||active.sceneId!==returnContext.sceneId||active.instanceId!==returnContext.sceneInstanceId) {
    return {success:false,reason:"story_return_instance_mismatch"};
  }
  const safeResult=createObserverSafeStoryBattleResult(returnContext);
  if (!safeResult) return {success:false,reason:"story_battle_result_missing"};
  currentBattle.observerSafeResultContext=cloneBattleRuntimeValue(safeResult);
  active.battleResume=cloneProgressionData(safeResult);
  active.pendingBattle=null;

  const outcome=safeResult.outcome;
  const nextBeatId=returnContext.postBattleBeatId||(outcome==="victory"?returnContext.victoryBeatId:returnContext.defeatBeatId)||null;
  if (!nextBeatId) return {success:false,reason:"story_post_battle_continuation_missing"};
  const definition=getActiveStorySceneDefinition();
  if (!definition||!definition.beatMap.has(nextBeatId)) return {success:false,reason:"story_post_battle_beat_missing"};
  active.beatId=nextBeatId;
  const entered=processStorySceneConsequenceRequests(definition.beatMap.get(nextBeatId).onEnterConsequences,"enter");
  if (!entered.success) return entered;
  currentBattle.returnContext=null;
  savePlayerData();
  saveTestState();
  restoreStoryScenePresentationUnderlay(active.presentationUnderlay);
  openOverlay("story_scene");
  return {success:true,type:"story_scene_resumed",beatId:nextBeatId,result:cloneProgressionData(safeResult)};
}


// =========================================================
// BRICKS 1500–1508 — REGION HOTSPOT BATTLE RETURN / RE-EVALUATION
// =========================================================
// Victory CLAIM remains separate. CONTINUE restores the exact region/hotspot
// caller, then recomputes the observer-safe opportunity projection from the
// current authoritative World / Knowledge / history state.
//
// The previously selected opportunity is retained only if it still projects.
// Otherwise the first currently visible opportunity at the same hotspot is
// selected. No completion counter, forced next encounter, or omniscient reveal
// is manufactured here.
// =========================================================
function resumeRegionHotspotFromBattle(returnContext,outcomeType=null) {
  if (!returnContext||returnContext.type!=="region_hotspot") {
    return {success:false,reason:"region_hotspot_return_context_missing"};
  }
  const regionKey=returnContext.regionKey?String(returnContext.regionKey):null;
  const hotspotId=returnContext.hotspotId?String(returnContext.hotspotId):null;
  if (!regionKey||!worldRegions[regionKey]) {
    return {success:false,reason:"region_hotspot_return_region_missing"};
  }
  if (!hotspotId) {
    return {success:false,reason:"region_hotspot_return_hotspot_missing"};
  }

  // Re-open the same regional map surface. This is the existing map engine,
  // not a new activity or sub-map instance.
  const opened=openRegionHub(regionKey);
  if (opened&&opened.success===false) return opened;

  // Re-evaluate after Battle consequences/claim have already committed.
  const hotspot=getHotspotProjection(regionKey,hotspotId);
  selectedRegionKey=regionKey;
  selectedHotspotId=hotspotId;
  selectedLocationNode=hotspot?getWorldRegionLocation(regionKey,hotspot.locationId):null;

  const priorOpportunityId=returnContext.opportunityId?String(returnContext.opportunityId):null;
  const stillVisible=!!(hotspot&&priorOpportunityId&&hotspot.opportunities.some(item=>item.opportunity_id===priorOpportunityId));
  selectedOpportunityId=stillVisible
    ? priorOpportunityId
    : (hotspot&&hotspot.opportunityIds.length?hotspot.opportunityIds[0]:null);

  currentBattle.returnContext=null;
  savePlayerData();
  saveTestState();
  renderRegionHubUI(regionKey,worldRegions[regionKey]);

  return {
    success:true,
    type:"region_hotspot_resumed",
    outcomeType:outcomeType||null,
    regionKey,
    hotspotId,
    previousOpportunityId:priorOpportunityId,
    selectedOpportunityId:selectedOpportunityId||null,
    opportunityStillVisible:stillVisible,
    visibleOpportunityIds:hotspot?hotspot.opportunityIds.slice():[]
  };
}

function resumeMissionAreaHotspotFromBattle(returnContext,outcomeType=null) {
  if (!returnContext||returnContext.type!=="mission_area_hotspot") return {success:false,reason:"mission_area_return_context_missing"};
  const areaId=returnContext.missionAreaId?String(returnContext.missionAreaId):null;
  const hotspotId=returnContext.hotspotId?String(returnContext.hotspotId):null;
  const area=areaId?getLocalMissionAreaDefinition(areaId):null;
  if (!area) return {success:false,reason:"mission_area_return_area_missing"};
  if (!hotspotId) return {success:false,reason:"mission_area_return_hotspot_missing"};

  const opened=openLocalMissionArea(areaId,{returnContext:selectedMissionAreaReturnContext,restoring:true});
  if (!opened.success) return opened;
  const hotspot=getMissionAreaHotspotProjection(areaId,hotspotId);
  selectedHotspotId=hotspotId;
  const priorOpportunityId=returnContext.opportunityId?String(returnContext.opportunityId):null;
  const stillVisible=!!(hotspot&&priorOpportunityId&&hotspot.opportunities.some(item=>item.opportunity_id===priorOpportunityId));
  selectedOpportunityId=stillVisible?priorOpportunityId:(hotspot&&hotspot.opportunityIds.length?hotspot.opportunityIds[0]:null);
  currentBattle.returnContext=null;
  savePlayerData();
  saveTestState();
  renderLocalMissionAreaUI(areaId);
  return {
    success:true,type:"mission_area_hotspot_resumed",outcomeType:outcomeType||null,missionAreaId:areaId,hotspotId,
    previousOpportunityId:priorOpportunityId,selectedOpportunityId:selectedOpportunityId||null,opportunityStillVisible:stillVisible,
    visibleOpportunityIds:hotspot?hotspot.opportunityIds.slice():[]
  };
}

function resumeBattleCallerAfterCompletion(outcomeType=null) {
  const returnContext=normalizeBattleReturnContext(currentBattle.returnContext);
  if (!returnContext) return {success:false,reason:currentBattle.returnContext?"battle_return_context_invalid":"battle_return_context_absent"};
  if (returnContext.type==="story_scene") return resumeStorySceneFromBattle(returnContext);
  if (returnContext.type==="field_readiness_assessment") return resumeFieldReadinessAssessmentFromBattle(returnContext);
  if (returnContext.type==="region_hotspot") return resumeRegionHotspotFromBattle(returnContext,outcomeType);
  if (returnContext.type==="mission_area_hotspot") return resumeMissionAreaHotspotFromBattle(returnContext,outcomeType);
  return {success:false,reason:"battle_return_context_type_unhandled",type:returnContext.type||null,outcomeType};
}

function advanceStoryScene(choiceId=null) {
  const active=getActiveStorySceneRuntime();
  const beat=getCurrentStorySceneBeat();
  if (!active||!beat) return {success:false,reason:"story_scene_not_active"};
  if (beat.mode==="choice") {
    if (!choiceId) return {success:false,reason:"story_choice_required"};
    return applyStorySceneChoice(choiceId);
  }
  if (beat.mode==="battle_transition") return launchStorySceneBattle();
  const consequences=processStorySceneConsequenceRequests(beat.onAdvanceConsequences,"advance");
  if (!consequences.success) return consequences;
  if (beat.exitScene===true||!beat.nextBeatId) return completeStoryScene({reason:"scene_terminal_beat"});
  return setStorySceneBeat(beat.nextBeatId);
}

function resumeStorySceneReturnContext(returnContext) {
  if (!returnContext||typeof returnContext!=="object") {
    const overlay=document.getElementById("screen-overlay");
    if (overlay) overlay.style.display="none";
    currentOverlayType=null;
    return {success:true,type:"overlay_closed"};
  }
  switch (returnContext.type) {
    // =====================================================
    // BRICKS 1609–1611 — LOCAL AREA → ACTIVE STORY CALLER
    // =====================================================
    // The Story runtime remains authoritative and active while a contained
    // area is presented. Returning restores the exact same authored scene/beat.
    case "story_scene": {
      const active=getActiveStorySceneRuntime();
      if (!active) return {success:false,reason:"story_return_scene_missing"};
      if (returnContext.sceneId&&String(returnContext.sceneId)!==String(active.sceneId)) return {success:false,reason:"story_return_scene_mismatch"};
      if (returnContext.instanceId&&String(returnContext.instanceId)!==String(active.instanceId)) return {success:false,reason:"story_return_instance_mismatch"};
      if (returnContext.beatId&&String(returnContext.beatId)!==String(active.beatId)) return {success:false,reason:"story_return_beat_mismatch"};
      openOverlay("story_scene");
      saveTestState();
      return {success:true,type:"story_scene",sceneId:active.sceneId,beatId:active.beatId,instanceId:active.instanceId};
    }
    case "mission_area_hotspot": {
      const areaId=returnContext.missionAreaId||null;
      if (!areaId||!getLocalMissionAreaDefinition(areaId)) return {success:false,reason:"story_return_mission_area_missing"};
      return openLocalMissionArea(areaId,{
        returnContext:selectedMissionAreaReturnContext,
        hotspotId:returnContext.hotspotId||null,
        opportunityId:returnContext.opportunityId||null,
        restoring:true
      });
    }
    case "region_hotspot":
      if (!returnContext.regionKey||!worldRegions[returnContext.regionKey]) return {success:false,reason:"story_return_region_missing"};
      openRegionHub(returnContext.regionKey);
      if (returnContext.hotspotId) {
        selectedHotspotId=returnContext.hotspotId;
        selectedOpportunityId=returnContext.opportunityId||null;
        renderRegionHubUI(returnContext.regionKey,worldRegions[returnContext.regionKey]);
      }
      return {success:true,type:"region_hotspot"};
    case "overlay":
      if (!returnContext.overlayType) return {success:false,reason:"story_return_overlay_missing"};
      openOverlay(returnContext.overlayType);
      return {success:true,type:"overlay",overlayType:returnContext.overlayType};
    case "region":
      if (!returnContext.regionKey) return {success:false,reason:"story_return_region_missing"};
      openRegionHub(returnContext.regionKey);
      return {success:true,type:"region"};
    case "none":
      return {success:true,type:"none"};
    default:
      if (typeof returnContext.resolve==="function") return returnContext.resolve({playerData,currentBattle})||{success:false,reason:"story_return_resolver_no_result"};
      return {success:false,reason:"story_return_context_unhandled"};
  }
}

function completeStoryScene(options={}) {
  const state=ensureStorySceneRuntimeState();
  const active=state.active;
  const definition=active?getStorySceneDefinition(active.sceneId):null;
  if (!active||!definition) return {success:false,reason:"story_scene_not_active"};
  if (active.pendingBattle) return {success:false,reason:"story_scene_battle_pending"};
  const completion=processStorySceneConsequenceRequests(definition.onCompleteConsequences,"complete");
  if (!completion.success) return completion;
  const returnContext=active.returnContext?cloneProgressionData(active.returnContext):null;
  const receipt={success:true,type:"story_scene_complete",sceneId:active.sceneId,instanceId:active.instanceId,reason:options.reason||"complete"};
  state.active=null;
  hideStoryScenePresentationLayer({preserveRuntime:true});
  savePlayerData();
  if (isAcademyTeamFormationJourneyBlockingFreePlay()) {
    const formationPresentation=openAcademyTeamFormationUI({showChronicleBegins:true});
    saveTestState();
    return {...receipt,returnResult:{success:true,type:"academy_team_formation_required"},formationPresentation};
  }
  const returned=resumeStorySceneReturnContext(returnContext);
  saveTestState();
  return {...receipt,returnResult:returned};
}

function exitActiveStoryScene(options={}) {
  const active=getActiveStorySceneRuntime();
  const beat=getCurrentStorySceneBeat();
  if (!active) return {success:false,reason:"story_scene_not_active"};
  if (active.pendingBattle) return {success:false,reason:"story_scene_battle_pending"};
  if (beat&&beat.allowPresentationClose!==true&&options.force!==true) {
    return {success:false,reason:"story_scene_close_not_authored"};
  }
  const returnContext=active.returnContext?cloneProgressionData(active.returnContext):null;
  ensureStorySceneRuntimeState().active=null;
  hideStoryScenePresentationLayer({preserveRuntime:true});
  savePlayerData();
  const returned=resumeStorySceneReturnContext(returnContext);
  saveTestState();
  return {success:true,type:"story_scene_exited",returnResult:returned};
}

// =========================================================
// BRICKS 755–763 — ALPHA STORY SCENE UI SURFACE
// =========================================================
let lastStorySceneFeedbackReceiptPresented=null;

function escapeStorySceneHTML(value) {
  return String(value==null?"":value)
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;")
    .replace(/'/g,"&#039;");
}

function ensureStoryScenePresentationStyles() {
  if (typeof document==="undefined"||!document.head) return false;
  if (document.getElementById("sc-story-scene-runtime-style")) return true;
  const style=document.createElement("style");
  style.id="sc-story-scene-runtime-style";
  style.textContent=`
    #story-scene-presentation-layer{position:fixed;inset:0;z-index:12000;display:flex;align-items:flex-end;justify-content:center;pointer-events:auto;background:linear-gradient(180deg,rgba(2,5,9,.05) 0%,rgba(2,5,9,.18) 45%,rgba(2,5,9,.56) 100%);font-family:inherit;color:#eadfc9;overflow:hidden;}
    #story-scene-presentation-layer .sc-story-environment{position:absolute;inset:0;z-index:-2;background-position:center center;background-repeat:no-repeat;background-size:cover;pointer-events:none;}
    #story-scene-presentation-layer .sc-story-environment-scrim{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(2,5,9,.02) 0%,rgba(2,5,9,.10) 48%,rgba(2,5,9,.50) 100%);pointer-events:none;}
    #story-scene-presentation-layer .sc-story-shell{width:min(1120px,calc(100vw - 56px));margin:0 28px 34px;padding:0;display:grid;grid-template-columns:minmax(0,1fr);filter:drop-shadow(0 22px 42px rgba(0,0,0,.58));}
    #story-scene-presentation-layer .sc-story-panel{position:relative;min-height:188px;border:1px solid rgba(197,151,66,.78);background:linear-gradient(180deg,rgba(8,13,19,.94),rgba(3,7,12,.97));box-shadow:inset 0 0 0 1px rgba(255,225,157,.08);padding:22px 24px 20px 190px;overflow:hidden;}
    #story-scene-presentation-layer .sc-story-panel.no-portrait{padding-left:28px;}
    #story-scene-presentation-layer .sc-story-portrait{position:absolute;left:18px;bottom:0;width:150px;height:170px;display:flex;align-items:flex-end;justify-content:center;overflow:hidden;border-right:1px solid rgba(197,151,66,.24);}
    #story-scene-presentation-layer .sc-story-portrait img{max-width:100%;max-height:100%;object-fit:contain;object-position:center bottom;}
    #story-scene-presentation-layer .sc-story-kicker{font-size:10px;letter-spacing:.18em;color:#b6904e;text-transform:uppercase;opacity:.9;}
    #story-scene-presentation-layer .sc-story-name{font-size:17px;letter-spacing:.12em;font-weight:700;color:#72d9e7;margin-top:6px;text-transform:uppercase;}
    #story-scene-presentation-layer[data-ui-mode="internal_or_remote_voice"] .sc-story-name{color:#c891ff;}
    #story-scene-presentation-layer[data-ui-mode="narration_action"] .sc-story-name{display:none;}
    #story-scene-presentation-layer .sc-story-text{font-size:17px;line-height:1.62;margin-top:10px;white-space:pre-wrap;text-shadow:0 1px 1px #000;}
    #story-scene-presentation-layer .sc-story-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px;}
    #story-scene-presentation-layer .sc-story-action{appearance:none;border:1px solid rgba(195,151,68,.72);background:rgba(14,19,25,.92);color:#eadfc9;padding:10px 18px;cursor:pointer;letter-spacing:.05em;}
    #story-scene-presentation-layer .sc-story-action:hover:not(:disabled){border-color:#e5bd69;background:rgba(38,31,20,.94);}
    #story-scene-presentation-layer .sc-story-action:disabled{opacity:.44;cursor:not-allowed;}
    #story-scene-presentation-layer .sc-story-choice{width:100%;text-align:left;}
    #story-scene-presentation-layer .sc-story-close{position:absolute;right:12px;top:10px;border:0;background:transparent;color:#d3b77e;font-size:18px;cursor:pointer;}
    #story-scene-presentation-layer .sc-story-result{margin-top:12px;font-size:11px;letter-spacing:.08em;color:#c9b487;opacity:.86;}
    #story-scene-feedback-toast{position:fixed;left:28px;bottom:246px;z-index:12010;border:1px solid rgba(202,162,78,.72);background:rgba(6,11,16,.96);color:#e2c47e;padding:11px 15px;box-shadow:0 12px 28px rgba(0,0,0,.45);font-size:12px;letter-spacing:.07em;}
    @media(max-width:720px){#story-scene-presentation-layer .sc-story-shell{width:calc(100vw - 20px);margin:0 10px 12px;}#story-scene-presentation-layer .sc-story-panel{padding:18px 18px 18px 118px;min-height:156px;}#story-scene-presentation-layer .sc-story-portrait{width:98px;height:140px;left:10px;}#story-scene-presentation-layer .sc-story-text{font-size:15px;}}
  `;
  document.head.appendChild(style);
  return true;
}

function getStoryScenePresentationLayer() {
  if (typeof document==="undefined"||!document.body) return null;
  let layer=document.getElementById("story-scene-presentation-layer");
  if (!layer) {
    layer=document.createElement("div");
    layer.id="story-scene-presentation-layer";
    layer.setAttribute("role","dialog");
    layer.setAttribute("aria-modal","true");
    layer.setAttribute("aria-live","polite");
    document.body.appendChild(layer);
  }
  return layer;
}

function isStoryScenePresentationVisible() {
  if (typeof document==="undefined") return false;
  const layer=document.getElementById("story-scene-presentation-layer");
  return !!(layer&&layer.style.display!=="none"&&layer.childNodes.length>0);
}

function hideStoryScenePresentationLayer(options={}) {
  if (typeof document==="undefined") return true;
  const layer=document.getElementById("story-scene-presentation-layer");
  if (layer) {
    layer.style.display="none";
    layer.innerHTML="";
  }
  if (options.preserveRuntime!==true&&ensureStorySceneRuntimeState().active) {
    // Presentation hiding is not a world/history mutation. Runtime is preserved by default
    // in all authoritative callers; this branch exists only for explicit cleanup tooling.
  }
  return true;
}

function renderStorySceneFeedbackToast(receipt) {
  if (!receipt||!receipt.receiptId||typeof document==="undefined"||!document.body) return false;
  if (lastStorySceneFeedbackReceiptPresented===receipt.receiptId) return false;
  lastStorySceneFeedbackReceiptPresented=receipt.receiptId;
  let toast=document.getElementById("story-scene-feedback-toast");
  if (!toast) {
    toast=document.createElement("div");
    toast.id="story-scene-feedback-toast";
    toast.setAttribute("role","status");
    document.body.appendChild(toast);
  }
  toast.textContent=receipt.label||"Chronicle Updated";
  toast.style.display="block";
  if (typeof setTimeout==="function") setTimeout(()=>{if(toast) toast.style.display="none";},2200);
  return true;
}

function renderStorySceneOverlay(container) {
  if (!container) return false;
  const model=createStorySceneObserverSafeProjection();
  if (!model) {
    container.innerHTML="";
    container.style.display="none";
    return false;
  }

  ensureStoryScenePresentationStyles();
  const speaker=model.speaker_name||model.speaker_source_id||"";
  const portrait=model.portrait_ref&&model.portrait_ref.src?model.portrait_ref:null;
  const hasPortrait=!!portrait&&model.ui_mode!=="narration_action";
  const closeAllowed=!!(getCurrentStorySceneBeat()&&getCurrentStorySceneBeat().allowPresentationClose===true);
  const modeLabel=(model.ui_mode||model.mode||"character").replace(/_/g," ").toUpperCase();
  const postBattle=model.post_battle_context;
  const sceneEnvironment=model.scene_environment||{mode:"inherit_current",asset_path:null};
  const dedicatedBackdrop=sceneEnvironment.mode==="dedicated_backdrop"&&sceneEnvironment.asset_path;

  const choices=model.mode==="choice"
    ? `<div class="sc-story-actions">${model.choices.map(choice=>`<button type="button" class="sc-story-action sc-story-choice" onclick="advanceStoryScene('${escapeStorySceneHTML(choice.choice_id)}')" ${choice.available?"":"disabled"}>${escapeStorySceneHTML(choice.label)}${!choice.available&&choice.known_blocker?` — ${escapeStorySceneHTML(choice.known_blocker)}`:""}</button>`).join("")}</div>`
    : "";

  let primaryAction="";
  if (model.mode==="battle_transition"&&model.battle_transition) {
    primaryAction=`<div class="sc-story-actions"><button type="button" class="sc-story-action" onclick="advanceStoryScene()" ${model.battle_transition.available?"":"disabled"}>${escapeStorySceneHTML(model.battle_transition.action_label)}</button></div>`;
  } else if (model.mode!=="choice") {
    const label=model.transition_instruction&&model.transition_instruction.kind==="complete"?"CONTINUE":"CONTINUE";
    primaryAction=`<div class="sc-story-actions"><button type="button" class="sc-story-action" onclick="advanceStoryScene()">${label}</button></div>`;
  }

  container.style.display="flex";
  container.dataset.sceneId=model.scene_id;
  container.dataset.beatId=model.beat_id;
  container.dataset.mode=model.mode;
  container.dataset.uiMode=model.ui_mode||"character";
  container.setAttribute("aria-label",speaker?`${speaker} dialogue`:"Story scene");
  container.innerHTML=`
    ${dedicatedBackdrop?`<div class="sc-story-environment" data-scene-environment-id="${escapeStorySceneHTML(sceneEnvironment.asset_id||"")}" style="background-image:url('${escapeStorySceneHTML(sceneEnvironment.asset_path)}')"></div><div class="sc-story-environment-scrim"></div>`:""}
    <div class="sc-story-shell">
      <section class="sc-story-panel ${hasPortrait?"":"no-portrait"}">
        ${closeAllowed?`<button type="button" class="sc-story-close" onclick="exitActiveStoryScene({reason:'ui_close'})" aria-label="Close scene">✕</button>`:""}
        ${hasPortrait?`<div class="sc-story-portrait" aria-hidden="true"><img src="${escapeStorySceneHTML(portrait.src)}" alt=""></div>`:""}
        <div class="sc-story-kicker">${escapeStorySceneHTML(modeLabel)}${model.title?` · ${escapeStorySceneHTML(model.title)}`:""}</div>
        ${speaker&&model.ui_mode!=="narration_action"?`<div class="sc-story-name">${escapeStorySceneHTML(speaker)}</div>`:""}
        <div class="sc-story-text">${escapeStorySceneHTML(model.text)}</div>
        ${postBattle?`<div class="sc-story-result">BATTLE RESULT · ${escapeStorySceneHTML(String(postBattle.outcome||"resolved").toUpperCase())}</div>`:""}
        ${choices}
        ${primaryAction}
      </section>
    </div>`;

  if (model.feedback_receipt) renderStorySceneFeedbackToast(model.feedback_receipt);
  return true;
}

function renderStoryScenePresentationLayer() {
  const layer=getStoryScenePresentationLayer();
  if (!layer) return false;
  return renderStorySceneOverlay(layer);
}

