// =========================================================
// PL NUMBER FORMATTING
// =========================================================

function formatPL(value) {

  return Number(
    value || 0
  ).toLocaleString();

}

// =========================================================
// BRICK 320 — BATTLE POWER CAPACITY
// DAMAGE / STAMINA v1 ALIGNMENT
// =========================================================
//
// Remaining Battle PL capacity is derived from authoritative
// PL only.
//
// Stamina is NOT added to Battle PL capacity.
//
// Stamina participates later, once per mechanical damage
// packet, at the canonical mitigation stage:
//
// resolved attack PL
// → Stamina mitigation
// → final PL damage
// → Remaining Battle PL
//
// Legacy encounter-type capacity multipliers and random Battle-entry
// variation are retired for Alpha. Battle-entry underlying Battle PL
// is deterministic from current authoritative PL.
//
// =========================================================

function calculateBattlePower(
  character,
  encounterType = "standard"
) {
  if (!character) return 0;

  const isPlayerCharacter = character.basePL !== undefined;
  let pl=0;
  if (isPlayerCharacter) {
    pl=calculateEffectivePL(character);
  } else if (hasCanonicalSevenStats(character.encounterEffectiveStats)) {
    pl=Math.round(calculateRawPLFromStats(character.encounterEffectiveStats));
  } else if (Number.isFinite(Number(character.calibratedBasePL))) {
    pl=Math.round(Number(character.calibratedBasePL));
  } else {
    pl=Number(character.power)||0;
  }

  // BRICK 873 — Alpha authority: Battle-entry underlying Battle PL is
  // deterministic. Legacy encounter multipliers and ±10% random variation
  // are retired. encounterType remains a compatibility argument only.
  // Stamina is deliberately absent here; it mitigates incoming PL damage.
  void encounterType;
  return Math.max(1,Math.round(pl));
}


// =========================================================
// SELECT / ENTER HOTSPOT
// BRICK 695 — SELECTION IS PRESENTATION, NOT COMMITMENT
// =========================================================

function selectMapNode(regionKey,hotspotOrLocationId) {
  const region=worldRegions[regionKey];
  if (!region) return null;
  const hotspot=getHotspotProjection(regionKey,hotspotOrLocationId);
  if (!hotspot) return null;
  selectedRegionKey=regionKey;
  selectedHotspotId=hotspot.hotspotId;
  selectedLocationNode=getWorldRegionLocation(regionKey,hotspot.locationId);
  selectedOpportunityId=hotspot.opportunityIds[0]||null;
  renderRegionHubUI(regionKey,region);
  return hotspot;
}

// =========================================================
// RETURN TO WORLD MAP
// =========================================================

function returnToWorldMap() {
  const overlay=document.getElementById("screen-overlay");
  if (!overlay) return;
  overlay.style.display="none";
  overlay.classList.remove("region-map-open");
  selectedRegionKey=null;
  selectedLocationNode=null;
  selectedHotspotId=null;
  selectedOpportunityId=null;
  selectedMissionAreaId=null;
  selectedMissionAreaReturnContext=null;
  regionInfoOpen=false;
}

// =========================================================
// LOCATION NAVIGATION
// BRICK 312 — BATTLE LOCATION AVAILABILITY BOUNDARY
// BRICK 556 — MISSION LOCATION AVAILABILITY BOUNDARY
// =========================================================

function handleNodeNavigation() {


  if (
    !selectedLocationNode
  ) {

    return;
  }


  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  if (
    overlay
  ) {


    overlay.classList.remove(
      "region-map-open"
    );
  }


  console.log(
    "LOCATION ENTERED:",
    selectedLocationNode
  );


  switch (
    selectedLocationNode.type
  ) {


    case "village":


      openOverlay(
        "village"
      );


      break;


    case "training":


      executePlayerActivity({

        type:
          "training",

        stage:
          "available",

        location:
          selectedLocationNode.id

      });


      openOverlay(
        "training"
      );


      break;


    case "battle":


      // =======================================
      // Entering a Battle location exposes
      // Battle opportunities only.
      //
      // It is NOT Battle completion.
      // No rewards or progression resolve here.
      // =======================================

      executePlayerActivity({

        type:
          "battle",

        stage:
          "available",

        location:
          selectedLocationNode.id

      });


      openOverlay(
        "battle"
      );


      break;


    case "mission":


      // =======================================
      // Entering a Mission location exposes
      // Mission opportunities only.
      //
      // It is NOT Mission completion.
      // No rewards, progression or history resolve here.
      // =======================================

      executePlayerActivity({

        type:
          "mission",

        stage:
          "available",

        location:
          selectedLocationNode.id

      });


      openOverlay(
        "missions"
      );


      break;


    case "outpost":


      openOverlay(
        "battle"
      );


      break;


    case "activity":


      openOverlay(
        "missions"
      );


      break;


    case "secret":


      openOverlay(
        "battle"
      );


      break;


    default:


      openOverlay(
        "battle"
      );


      break;

  }

}

