// CHECK LOCATION ACTION
// =========================================================

function canPerformLocationAction(
  action
) {


  const actions =
    getAvailableLocationActions();


  return actions.includes(
    action
  );


}

// =========================================
// LOCATION DISCOVERY STATE
// =========================================


let discoveredLocations = [];



// =========================================================
// DISCOVER LOCATION
// =========================================================

function discoverLocation(
  locationId
) {


  if (
    !getLocationData(locationId)
  ) {

    console.log(
      "Invalid location:",
      locationId
    );

    return false;

  }


  if (
    !discoveredLocations.includes(
      locationId
    )
  ) {


    discoveredLocations.push(
      locationId
    );


    console.log(
      "Location discovered:",
      locationId
    );


  }


  return true;


}



// =========================================================
// CHECK DISCOVERY
// =========================================================

function isLocationDiscovered(
  locationId
) {


  return discoveredLocations.includes(
    locationId
  );


}

