// =========================================
// CONTENT REGISTRATION
// =========================================


function registerLocation(
  location
) {


  if (
    !location ||
    !location.id
  ) {


    return false;


  }



  LOCATION_DATABASE[
    location.id
  ] = location;



  return true;


}
// =========================================
// ACTIVITY EXISTENCE VALIDATION
// =========================================


function validateActivity(
  activityId
) {


  const activity =
    getActivityData(
      activityId
    );



  if (!activity) {


    return false;


  }



  return true;


}

// =========================================================
// BRICK 122 — LOCATION ACTIVITY VALIDATION
// =========================================================
//
// Validates location actions against
// their mapped Activity Engine identity.
//
// Location Action
// ↓
// Activity Mapping
// ↓
// Activity Validation
//
// =========================================================


function validateLocationActivity(
  locationId,
  action
) {


  const location =
    getLocationData(
      locationId
    );



  if (
    !location
  ) {


    return false;


  }



  if (
    !Array.isArray(
      location.actions
    ) ||
    !location.actions.includes(
      action
    )
  ) {


    return false;


  }



  const activityId =
    getLocationActivity(
      locationId,
      action
    );



  if (
    !activityId
  ) {


    return false;


  }



  return validateActivity(
    activityId
  );


}

