// =========================================================
// BRICK 190 — LOCATION ACTION ACCESS CHECK
// =========================================================
//
// Location validity
// ↓
// Activity validity
// ↓
// Chronicle content access
//
// =========================================================


function canLaunchLocationAction(
  locationId,
  action
) {


  if (
    !validateLocationActivity(
      locationId,
      action
    )
  ) {


    return false;


  }


  const locationAccess =
    getLocationActionAccessStatus(
      locationId,
      action
    );


  if (
    !locationAccess.accessible
  ) {


    console.log(
      "Location action locked:",
      locationId,
      action,
      locationAccess
    );


    return false;


  }


  const activityId =
    getLocationActivity(
      locationId,
      action
    );


  if (
    !activityId
  ) {


    return false;


  }


  const activityAccess =
    getActivityAccessStatus(
      activityId
    );


  if (
    !activityAccess.accessible
  ) {


    console.log(
      "Activity locked:",
      activityId,
      activityAccess
    );


    return false;


  }


  return true;


}



