// =========================================================
// BRICK 124 — LOCATION ACTIVITY EXECUTION ROUTER
// =========================================================
//
// Routes the player's current location action
// into the Activity Engine.
//
// Preserves character identity through:
// Location
// ↓
// Activity
// ↓
// Progression
//
// =========================================================


function executeLocationAction(
  action,
  characterId
) {


  const locationId =
    getPlayerLocation();



  if (
    !locationId
  ) {


    console.log(
      "No active player location."
    );


    return false;


  }



  if (
    !characterId ||
    !getPlayerCharacter(
      characterId
    )
  ) {


    console.log(
      "Invalid location activity character:",
      characterId
    );


    return false;


  }



  if (
    !canLaunchLocationAction(
      locationId,
      action
    )
  ) {


    console.log(
      "Action unavailable:",
      action
    );


    return false;


  }



  return launchLocationAction(
    locationId,
    action,
    characterId
  );


}

