// =========================================================
// LOCATION COMPLETION CHECK
// =========================================================

function isLocationComplete(
  locationId
) {


  const progress =
    getPlayerLocationProgress(
      locationId
    );


  if (
    !progress
  ) {

    return false;

  }


  return (
    progress.state ===
    "completed"
  );

}

