// =========================================================

function getLocationDiscoveryCount() {


  const locations =
    Object.keys(
      LOCATION_DATABASE
    );


  const discovered =
    locations.filter(
      locationId =>
        isLocationDiscovered(
          locationId
        )
    );


  return {

    total:
      locations.length,

    discovered:
      discovered.length

  };

}

