// =========================================================
// BRICK 196 — KONOHA SERVICE ACCESS
// =========================================================
//
// Routes access checks to the correct Engine.
//
// Activity services:
// Location → Activity → Content Access
//
// Training:
// Training Engine → Content Access
//
// Shop:
// Not implemented yet.
//
// =========================================================


function evaluateKonohaServiceAccess(
  serviceId
) {


  const service =
    getKonohaService(
      serviceId
    );


  if (
    !service
  ) {


    return {

      exists:
        false,

      accessible:
        false,

      implemented:
        false,

      reason:
        "unknown_konoha_service"

    };


  }


  const location =
    getLocationData(
      "konoha"
    );


  const actionListed =
    !!(
      location &&
      Array.isArray(
        location.actions
      ) &&
      location.actions.includes(
        service.action
      )
    );


  if (
    service.implemented !==
      true
  ) {


    return {

      exists:
        true,

      accessible:
        false,

      implemented:
        false,

      actionListed:
        actionListed,

      service:
        service,

      reason:
        "service_not_implemented"

    };


  }


  // =========================================
  // ACTIVITY ROUTE
  // =========================================


  if (
    service.routeType ===
      "activity"
  ) {


    const accessible =
      canLaunchLocationAction(
        "konoha",
        service.action
      );


    return {

      exists:
        true,

      accessible:
        accessible,

      implemented:
        true,

      actionListed:
        actionListed,

      routeType:
        service.routeType,

      activityId:
        service.activityId,

      service:
        service

    };


  }


  // =========================================
  // TRAINING ROUTE
  // =========================================


  if (
    service.routeType ===
      "training"
  ) {


    const trainingAccess =
      getTrainingAccessStatus(
        service.trainingId
      );


    return {

      exists:
        true,

      accessible:
        (
          actionListed &&
          trainingAccess.accessible
        ),

      implemented:
        true,

      actionListed:
        actionListed,

      routeType:
        service.routeType,

      trainingId:
        service.trainingId,

      access:
        trainingAccess,

      service:
        service

    };


  }


  return {

    exists:
      true,

    accessible:
      false,

    implemented:
      service.implemented ===
        true,

    actionListed:
      actionListed,

    routeType:
      service.routeType,

    service:
      service,

    reason:
      "unsupported_service_route"

  };


}



// =========================================================
// BRICK 197 — KONOHA SERVICE PRESENTATION DATA
// =========================================================
//
// UI-safe service card data.
//
// =========================================================


function getKonohaServicePresentation(
  serviceId
) {


  const access =
    evaluateKonohaServiceAccess(
      serviceId
    );


  if (
    !access.exists ||
    !access.service
  ) {


    return null;


  }


  const service =
    access.service;


  return {

    id:
      service.id,

    title:
      service.title,

    description:
      service.description,

    routeType:
      service.routeType,

    action:
      service.action,

    implemented:
      access.implemented,

    accessible:
      access.accessible,

    locked:
      access.accessible !==
        true,

    reason:
      access.reason ||
      null

  };


}



// =========================================================
// BRICK 198 — KONOHA HUB DATA
// =========================================================
//
// Complete non-rendered Konoha UI model.
//
// =========================================================


function getKonohaHubData() {


  const location =
    getLocationData(
      "konoha"
    );


  if (
    !location
  ) {


    return null;


  }


  return {

    id:
      location.id,

    name:
      location.name,

    type:
      location.type,

    discovered:
      isLocationDiscovered(
        "konoha"
      ),

    difficulty:
      playerData &&
      playerData.progression
        ? playerData.progression
            .currentDifficulty
        : null,

    ryo:
      Number(
        playerData &&
        playerData.ryo
      ) || 0,

    exp:
      Number(
        playerData &&
        playerData.exp
      ) || 0,

    services:
      getKonohaServices()
        .map(
          service =>
            getKonohaServicePresentation(
              service.id
            )
        )
        .filter(
          service =>
            !!service
        )

  };


}



// =========================================================
// BRICK 199 — KONOHA CHARACTER ACTIVITY DATA
// =========================================================
//
// Creates the character-specific data required by
// Exam and Practical screens.
//
// =========================================================


function getKonohaCharacterActivityData(
  activityId,
  characterId
) {


  const activity =
    getActivityData(
      activityId
    );


  const character =
    getPlayerCharacter(
      characterId
    );


  if (
    !activity ||
    !character
  ) {


    return null;


  }


  const rewards =
    Array.isArray(
      activity.rewards
    )
      ? activity.rewards
      : [];


  const disciplines =
    rewards
      .filter(
        reward =>
          reward &&
          reward.type ===
            "discipline"
      )
      .map(
        reward => {


          const discipline =
            getShinobiDiscipline(
              reward.id
            );


          const progression =
            getCharacterDisciplineProgression(
              characterId,
              reward.id
            );


          if (
            !discipline ||
            !progression
          ) {


            return null;


          }


          return {

            id:
              discipline.id,

            name:
              discipline.name,

            level:
              progression.level,

            exp:
              progression.exp,

            expRequired:
              getDisciplineExpRequired(
                progression.level
              ),

            rewardExp:
              Number(
                reward.amount
              ) || 0

          };


        }
      )
      .filter(
        discipline =>
          !!discipline
      );


  const access =
    getActivityAccessStatus(
      activityId
    );


  return {

    activityId:
      activity.id,

    activityName:
      activity.name,

    character: {

      id:
        character.id,

      name:
        character.name,

      rank:
        character.rank,

      currentPL:
        calculateCurrentPL(
          character
        )

    },

    accessible:
      access.accessible,

    disciplines:
      disciplines

  };


}



