// =========================================================
// BRICK 229 — EXAM CHARACTER SELECTION INTERACTION
// =========================================================
//
// Changing shinobi immediately retires temporary Exam
// result presentation.
//
// Persistent progression and Special Notifications remain.
//
// =========================================================

function changeKonohaExamCharacter(
  direction
) {


  clearKonohaExamResultPresentation(
    false
  );


  const character =
    cycleKonohaSelectedCharacter(
      direction
    );


  if (!character) {

    return false;

  }


  renderKonohaExamVisualScreen();


  console.log(
    "EXAM SHINOBI SELECTED:",
    character.id
  );


  return true;

}


// =========================================================
// EXAM PRESENTATION RETIREMENT BOUNDARY
// =========================================================
//
// Dedicated Eligibility presentation is retired.
//
// Eligibility/access remains owned by gameplay/data systems.
// The active Exam interaction runtime begins below.
//
// =========================================================

// =========================================================
// BRICK 264 — EXAM ATTEMPT STATE
// =========================================================
//
// Runtime interaction state for the active Exam UI.
//
// Permanent progression remains elsewhere.
//
// Result presentation is temporary:
//
// - appears after an Exam batch
// - animates briefly
// - automatically retires
// - disappears immediately on character change
// - is replaced by the next Exam result
//
// =========================================================

const KONOHA_EXAM_ATTEMPT_STATE = {

  disciplineId:
    "nin",

  batchSize:
    1,

  lastBatch:
    [],

  lastBatchMeta:
    null,

  activeSpecialNotifications:
    [],

  specialNotificationHistory:
    [],

  specialNotificationHistoryOpen:
    false,

  resultVisible:
    false,

  resultPresentationToken:
    0,

  resultDismissTimer:
    null

};


// =========================================================
// CLEAR EXAM RESULT PRESENTATION
// =========================================================

function clearKonohaExamResultPresentation(
  rerender = false
) {


  if (
    KONOHA_EXAM_ATTEMPT_STATE
      .resultDismissTimer !==
    null
  ) {


    clearTimeout(
      KONOHA_EXAM_ATTEMPT_STATE
        .resultDismissTimer
    );


    KONOHA_EXAM_ATTEMPT_STATE
      .resultDismissTimer =
        null;

  }


  KONOHA_EXAM_ATTEMPT_STATE
    .resultPresentationToken +=
      1;


  KONOHA_EXAM_ATTEMPT_STATE
    .resultVisible =
      false;


  if (rerender) {

    renderKonohaExamVisualScreen();

  }


  return true;

}


// =========================================================
// SHOW TEMPORARY EXAM RESULT
// =========================================================
//
// CSS owns:
// - letter bounce
// - linger
// - exit animation
//
// JS owns:
// - actual presentation lifetime
// - stale timer protection
//
// =========================================================

function showKonohaExamResultPresentation(
  duration = 2800
) {


  if (
    KONOHA_EXAM_ATTEMPT_STATE
      .resultDismissTimer !==
    null
  ) {


    clearTimeout(
      KONOHA_EXAM_ATTEMPT_STATE
        .resultDismissTimer
    );

  }


  KONOHA_EXAM_ATTEMPT_STATE
    .resultPresentationToken +=
      1;


  const token =
    KONOHA_EXAM_ATTEMPT_STATE
      .resultPresentationToken;


  KONOHA_EXAM_ATTEMPT_STATE
    .resultVisible =
      true;


  KONOHA_EXAM_ATTEMPT_STATE
    .resultDismissTimer =
      setTimeout(
        () => {


          if (
            KONOHA_EXAM_ATTEMPT_STATE
              .resultPresentationToken !==
            token
          ) {

            return;

          }


          KONOHA_EXAM_ATTEMPT_STATE
            .resultVisible =
              false;


          KONOHA_EXAM_ATTEMPT_STATE
            .resultDismissTimer =
              null;


          renderKonohaExamVisualScreen();


        },
        Math.max(
          800,
          Number(
            duration
          ) || 2800
        )
      );


  return true;

}

// =========================================================
// BRICK 265 — EXAM DISCIPLINE SELECTION
// =========================================================
//
// Owns selection of the discipline being examined.
//
// Presentation may visually react to this state,
// but visual feedback does not own the selection.
//
// =========================================================

function getKonohaExamSelectedDisciplineId() {

  const validDisciplines = [
    "nin",
    "gen",
    "fuin"
  ];


  if (
    !validDisciplines.includes(
      KONOHA_EXAM_ATTEMPT_STATE
        .disciplineId
    )
  ) {

    KONOHA_EXAM_ATTEMPT_STATE
      .disciplineId =
        "nin";

  }


  return KONOHA_EXAM_ATTEMPT_STATE
    .disciplineId;

}


function selectKonohaExamDiscipline(
  disciplineId
) {

  const validDisciplines = [
    "nin",
    "gen",
    "fuin"
  ];


  if (
    !validDisciplines.includes(
      disciplineId
    )
  ) {

    console.log(
      "Invalid Exam discipline:",
      disciplineId
    );


    return false;

  }


  /*
     Clear any PASS / FAIL presentation belonging
     to the previously selected discipline before
     rendering the newly selected discipline.
  */

  clearKonohaExamResultPresentation(
    false
  );


  KONOHA_EXAM_ATTEMPT_STATE
    .disciplineId =
      disciplineId;


  renderKonohaExamVisualScreen();


  console.log(
    "EXAM DISCIPLINE SELECTED:",
    disciplineId
  );


  return true;

}



// =========================================================
// BRICK 266 — EXAM ATTEMPT CONTEXT
// =========================================================
//
// Creates the normalized snapshot used to resolve ONE Exam.
//
// Player/UI chooses:
// - character
// - discipline
//
// Context captures:
// - current discipline mastery
// - current discipline EXP
// - current natural discipline stat
// - attempt timestamp
//
// Context does NOT determine:
// - difficulty
// - outcome
// - rewards
// - Chronicle consequences
//
// =========================================================

function createKonohaExamAttemptContext(
  characterId,
  disciplineId
) {

  const character =
    getPlayerCharacter(
      characterId
    );


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  const progression =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  if (
    !character ||
    !discipline ||
    !progression
  ) {

    return null;

  }


  const statValue =
    Number(
      character.stats[
        disciplineId
      ]
    ) || 0;


  return {

    activity:
      "exam",

    characterId:
      character.id,

    disciplineId:
      discipline.id,

    disciplineName:
      discipline.name,

    disciplineLevel:
      Number(
        progression.level
      ) || 1,

    disciplineExp:
      Number(
        progression.exp
      ) || 0,

    statValue:
      statValue,

    createdAt:
      Date.now()

  };

}

// =========================================================
// BRICK 267 — HIDDEN EXAM DIFFICULTY
// =========================================================
//
// Exam difficulty is intentionally hidden from the player.
//
// Difficulty rises with discipline mastery so Exams remain
// meaningful rather than becoming automatic forever.
//
// =========================================================

function getKonohaExamHiddenDifficulty(
  context
) {

  if (!context) {

    return null;

  }


  const level =
    Math.max(
      1,
      Number(
        context.disciplineLevel
      ) || 1
    );


  const baseDifficulty =
    44;


  const levelPressure =
    Math.min(
      28,
      Math.floor(
        (level - 1) * 1.75
      )
    );


  return Math.min(
    82,
    baseDifficulty +
      levelPressure
  );

}


// =========================================================
// BRICK 268 — EXAM HISTORY PRESSURE
// =========================================================
//
// Chronicle evidence affects future Exam resolution.
//
// Repeated failure creates learning pressure.
// Repeated success creates confidence, but does not make
// success permanently guaranteed.
//
// This prevents pure RNG from trapping a character in an
// endless failure streak.
//
// =========================================================

function getKonohaExamHistoryPressure(
  characterId,
  disciplineId
) {

  const history =
    getActivityHistory()
      .filter(
        entry =>
          entry &&
          entry.activity ===
            "exam" &&
          entry.character ===
            characterId &&
          entry.exam &&
          entry.exam.disciplineId ===
            disciplineId
      )
      .slice(
        -5
      );


  let consecutiveFailures =
    0;


  for (
    let index =
      history.length - 1;
    index >= 0;
    index -= 1
  ) {

    if (
      history[index].success ===
        false
    ) {

      consecutiveFailures +=
        1;

    }
    else {

      break;

    }

  }


  const totalSuccesses =
    history.filter(
      entry =>
        entry.success ===
          true
    ).length;


  return {

    recentAttempts:
      history.length,

    consecutiveFailures:
      consecutiveFailures,

    recentSuccesses:
      totalSuccesses,

    failureAssist:
      Math.min(
        24,
        consecutiveFailures * 8
      ),

    confidenceBonus:
      Math.min(
        6,
        totalSuccesses * 2
      )

  };

}


// =========================================================
// BRICK 269 — EXAM OUTCOME RESOLVER
// =========================================================
//
// One Exam attempt.
//
// Character ability matters.
// Discipline mastery matters.
// Recent history matters.
// Randomness creates uncertainty but does not own the system.
//
// =========================================================

function resolveKonohaExamAttempt(
  context
) {

  if (!context) {

    return null;

  }


  const difficulty =
    getKonohaExamHiddenDifficulty(
      context
    );


  const history =
    getKonohaExamHistoryPressure(
      context.characterId,
      context.disciplineId
    );


  const statContribution =
    Math.min(
      34,
      context.statValue * 0.34
    );


  const masteryContribution =
    Math.min(
      24,
      context.disciplineLevel * 2.4
    );


  const randomContribution =
    Math.random() * 42;


  const score =
    statContribution +
    masteryContribution +
    history.failureAssist +
    history.confidenceBonus +
    randomContribution;


  const passed =
    score >= difficulty;


  return {

    passed:
      passed,

    outcome:
      passed
        ? "pass"
        : "fail",

    difficulty:
      difficulty,

    score:
      Number(
        score.toFixed(
          2
        )
      ),

    history:
      history

  };

}


// =========================================================
// BRICK 270 — EXAM ATTEMPT CHRONICLE RECORD
// =========================================================
//
// IMPORTANT CHRONICLE RULE:
//
// "The activity occurred" and "the desired outcome succeeded"
// are separate facts.
//
// Failed Exam attempts therefore remain historical evidence.
//
// =========================================================

function recordKonohaExamAttempt(
  context,
  resolution,
  rewardExp
) {

  if (
    !context ||
    !resolution
  ) {

    return false;

  }


  const successful =
    resolution.passed ===
      true;


  const progressionRewards =
    successful &&
    rewardExp > 0

      ? [
          {
            type:
              "discipline",

            id:
              context.disciplineId,

            amount:
              rewardExp
          }
        ]

      : [];


  activityHistory.push({

    activity:
      "exam",

    character:
      context.characterId,

    completed:
      true,

    success:
      successful,

    outcome:
      resolution.outcome,

    exam: {

      disciplineId:
        context.disciplineId,

      disciplineName:
        context.disciplineName,

      disciplineLevel:
        context.disciplineLevel,

      statValue:
        context.statValue

    },

    rewards: {

      exp:
        0,

      ryo:
        0,

      items:
        [],

      progression:
        progressionRewards

    },

    timestamp:
      Date.now()

  });


  syncActivityHistory();

  savePlayerData();


  console.log(
    "EXAM CHRONICLE ATTEMPT RECORDED:",
    {
      character:
        context.characterId,

      discipline:
        context.disciplineId,

      outcome:
        resolution.outcome
    }
  );


  return true;

}


// =========================================================
// BRICK 271 — SINGLE DISCIPLINE EXAM EXECUTION
// =========================================================
//
// Resolves one genuine Exam attempt.
//
// In addition to the existing result contract, this brick
// now snapshots Discipline Mastery / EXP before and after
// the attempt.
//
// These snapshots do NOT create progression.
// They only expose real progression consequences to later
// presentation systems such as Special Notifications.
//
// =========================================================


function executeKonohaExamAttempt(
  characterId,
  disciplineId
) {


  const context =
    createKonohaExamAttemptContext(
      characterId,
      disciplineId
    );


  if (!context) {


    return {

      success:
        false,

      completed:
        false,

      reason:
        "exam_context_invalid"

    };

  }


  // =========================================
  // PRE-ATTEMPT DISCIPLINE SNAPSHOT
  // =========================================

  const disciplineLevelBefore =
    Number(
      context.disciplineLevel
    ) || 1;


  const disciplineExpBefore =
    Number(
      context.disciplineExp
    ) || 0;


  const resolution =
    resolveKonohaExamAttempt(
      context
    );


  if (!resolution) {


    return {

      success:
        false,

      completed:
        false,

      reason:
        "exam_resolution_failed"

    };

  }


  const activity =
    getActivityData(
      "exam"
    );


  const rewardDefinition =
    activity &&
    Array.isArray(
      activity.rewards
    )

      ? activity.rewards.find(
          reward =>
            reward &&
            reward.type ===
              "discipline" &&
            reward.id ===
              disciplineId
        )

      : null;


  const rewardExp =
    rewardDefinition

      ? Number(
          rewardDefinition.amount
        ) || 0

      : 0;


  if (
    resolution.passed ===
      true
  ) {


    const progressionApplied =
      addDisciplineExp(
        characterId,
        disciplineId,
        rewardExp,
        "exam"
      );


    if (!progressionApplied) {


      return {

        success:
          false,

        completed:
          false,

        reason:
          "exam_progression_failed"

      };

    }


  }


  const recorded =
    recordKonohaExamAttempt(
      context,
      resolution,
      resolution.passed
        ? rewardExp
        : 0
    );


  if (!recorded) {


    return {

      success:
        false,

      completed:
        false,

      reason:
        "exam_history_failed"

    };

  }


  // =========================================
  // POST-ATTEMPT DISCIPLINE SNAPSHOT
  // =========================================

  const progressionAfter =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  const disciplineLevelAfter =
    progressionAfter

      ? Number(
          progressionAfter.level
        ) || disciplineLevelBefore

      : disciplineLevelBefore;


  const disciplineExpAfter =
    progressionAfter

      ? Number(
          progressionAfter.exp
        ) || 0

      : disciplineExpBefore;


  return {

    success:
      resolution.passed,

    completed:
      true,

    outcome:
      resolution.outcome,

    characterId:
      characterId,

    disciplineId:
      disciplineId,

    rewardExp:
      resolution.passed
        ? rewardExp
        : 0,

    disciplineLevelBefore:
      disciplineLevelBefore,

    disciplineLevelAfter:
      disciplineLevelAfter,

    disciplineExpBefore:
      disciplineExpBefore,

    disciplineExpAfter:
      disciplineExpAfter

  };

}

// =========================================================
// BRICK 294 — EXAM BATCH + RESULT STAGE
// =========================================================
//
// Supported Exam batch sizes:
//
// ×1  — single attempt
// ×5  — five sequential attempts
// ×10 — ten sequential attempts
//
// Each attempt remains a genuine independent Exam resolution.
//
// Existing authorities still own:
//
// - PASS / FAIL resolution
// - discipline EXP awards
// - Chronicle recording
// - stat progression
// - Current PL derivation
//
// This brick owns:
//
// - batch execution
// - before / after PL snapshot
// - compact result summary
// - Exam Result Stage presentation contract
//
// =========================================================


function setKonohaExamBatchSize(
  batchSize
) {


  const requested =
    Number(
      batchSize
    );


  const normalized =
    [
      1,
      5,
      10
    ].includes(
      requested
    )

      ? requested

      : 1;


  KONOHA_EXAM_ATTEMPT_STATE
    .batchSize =
      normalized;


  renderKonohaExamVisualScreen();


  return true;

}


// =========================================================
// EXAM BATCH EXECUTION
// =========================================================
//
// Canonical batch lifecycle:
//
// 1. Snapshot persistent Current PL.
// 2. Execute ×1 / ×5 / ×10 genuine Exam attempts.
// 3. Snapshot resulting Current PL.
// 4. Store ordinary Exam result authority.
// 5. Derive and record meaningful Special Notifications.
// 6. Return the completed attempt results.
//
// Special Notification recording happens only AFTER
// lastBatch and lastBatchMeta are complete because
// BRICK 302 derives consequences from those authorities.
//
// =========================================================

function executeKonohaExamBatch(
  characterId,
  disciplineId,
  batchSize = 1
) {


  const count =
    [
      1,
      5,
      10
    ].includes(
      Number(
        batchSize
      )
    )

      ? Number(
          batchSize
        )

      : 1;


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {

    return [];

  }


  // =========================================
  // PRE-EXAM PL SNAPSHOT
  // =========================================

  const beforePL =
    getCharacterPLProgress(
      character
    );


  const results =
    [];


  // =========================================
  // EXECUTE GENUINE ATTEMPTS
  // =========================================

  for (
    let index = 0;
    index < count;
    index += 1
  ) {


    const result =
      executeKonohaExamAttempt(
        characterId,
        disciplineId
      );


    results.push(
      result
    );


    if (
      !result ||
      result.completed !==
        true
    ) {


      break;

    }


  }


  // =========================================
  // POST-EXAM PL SNAPSHOT
  // =========================================

  const afterPL =
    getCharacterPLProgress(
      character
    );


  // =========================================
  // ORDINARY RESULT AUTHORITY
  // =========================================

  KONOHA_EXAM_ATTEMPT_STATE
    .lastBatch =
      results;


  // =========================================
  // RESULT-STAGE META
  // =========================================
  //
  // Stored separately so lastBatch remains the
  // existing array authority expected by
  // gameplay / regression systems.
  // =========================================

  KONOHA_EXAM_ATTEMPT_STATE
    .lastBatchMeta = {

      characterId:
        characterId,

      disciplineId:
        disciplineId,

      requestedBatchSize:
        count,

      beforePL: {

        rawPL:
          beforePL.rawPL,

        displayedPL:
          beforePL.displayedPL,

        nextPL:
          beforePL.nextPL,

        progressPercent:
          beforePL.progressPercent

      },

      afterPL: {

        rawPL:
          afterPL.rawPL,

        displayedPL:
          afterPL.displayedPL,

        nextPL:
          afterPL.nextPL,

        progressPercent:
          afterPL.progressPercent

      }

    };


  // =========================================
  // SPECIAL NOTIFICATION CONSEQUENCES
  // =========================================
  //
  // IMPORTANT:
  //
  // This must happen AFTER lastBatch and
  // lastBatchMeta are written.
  //
  // BRICK 302 reads those two authorities to
  // determine whether:
  //
  // - Discipline Mastery increased
  // - Current PL increased
  //
  // Ordinary PASS / FAIL is projected into the same
  // Special Notifications feed by Post-1990.
  // =========================================

  recordKonohaExamSpecialNotifications(
    characterId
  );


  return results;

}

// =========================================================
// EXAM RESULT ANIMATED LETTERS
// =========================================================

function renderKonohaExamAnimatedResultText(
  text
) {


  return Array.from(
    String(
      text || ""
    )
  )
    .map(
      (
        character,
        index
      ) => {


        const visibleCharacter =
          character === " "
            ? "&nbsp;"
            : character;


        return `

          <span
            class="
              exam-result-letter
            "
            style="
              --exam-result-letter-index:
              ${index};
            "
            aria-hidden="
              true
            "
          >
            ${visibleCharacter}
          </span>

        `;

      }
    )
    .join("");

}


// =========================================================
// EXAM RESULT STAGE RENDERER
// =========================================================

function renderKonohaExamResultStrip() {


  if (
    KONOHA_EXAM_ATTEMPT_STATE
      .resultVisible !==
    true
  ) {

    return "";

  }


  const results =
    KONOHA_EXAM_ATTEMPT_STATE
      .lastBatch;


  const meta =
    KONOHA_EXAM_ATTEMPT_STATE
      .lastBatchMeta ||
      null;


  if (
    !Array.isArray(
      results
    ) ||
    results.length ===
      0
  ) {

    return "";

  }


  // =========================================
  // PREVENT STALE RESULT BETWEEN CHARACTERS
  // =========================================

  const session =
    getKonohaActivityUISessionState();


  if (
    meta &&
    meta.characterId &&
    session.characterId !==
      meta.characterId
  ) {

    return "";

  }


  const completedResults =
    results.filter(
      result =>
        result &&
        result.completed ===
          true
    );


  const passes =
    completedResults.filter(
      result =>
        result.success ===
          true
    );


  const fails =
    completedResults.filter(
      result =>
        result.success !==
          true
    );


  const errors =
    results.length -
    completedResults.length;


  const totalRewardExp =
    passes.reduce(
      (
        total,
        result
      ) =>
        total +
        (
          Number(
            result.rewardExp
          ) || 0
        ),
      0
    );


  const disciplineId =
    completedResults[0]
      ? completedResults[0]
          .disciplineId
      : (
          meta
            ? meta.disciplineId
            : null
        );


  const discipline =
    disciplineId
      ? getShinobiDiscipline(
          disciplineId
        )
      : null;


  const disciplineName =
    discipline
      ? discipline.name
      : "Exam";


  const isSingle =
    completedResults.length ===
      1 &&
    results.length ===
      1;


  // =========================================
  // PRIMARY RESULT
  // =========================================

  let primaryResult =
    "ERROR";


  let resultClass =
    "error";


  if (isSingle) {


    const single =
      completedResults[0];


    if (single) {


      if (
        single.success ===
          true
      ) {


        primaryResult =
          "PASS";


        resultClass =
          "pass";


      }
      else {


        primaryResult =
          "FAIL";


        resultClass =
          "fail";


      }


    }


  }
  else if (
    completedResults.length >
      0
  ) {


    primaryResult =
      `${passes.length} PASS · ${fails.length} FAIL`;


    resultClass =
      fails.length ===
        0

        ? "pass"

        : (
            passes.length ===
              0

              ? "fail"

              : "mixed"
          );


  }


  // =========================================
  // POWER DEVELOPMENT CONSEQUENCE
  // =========================================

  let powerResult =
    "";


  let powerResultClass =
    "progress";


  if (
    meta &&
    meta.beforePL &&
    meta.afterPL
  ) {


    const beforeDisplayed =
      Number(
        meta.beforePL
          .displayedPL
      ) || 0;


    const afterDisplayed =
      Number(
        meta.afterPL
          .displayedPL
      ) || 0;


    if (
      afterDisplayed >
      beforeDisplayed
    ) {


      powerResult =
        `POWER LEVEL ${beforeDisplayed} → ${afterDisplayed}`;


      powerResultClass =
        "level-up";


    }
    else {


      const beforeRaw =
        Number(
          meta.beforePL
            .rawPL
        ) || 0;


      const afterRaw =
        Number(
          meta.afterPL
            .rawPL
        ) || 0;


      const rawDifference =
        Math.max(
          0,
          afterRaw -
          beforeRaw
        );


      const progressGain =
        rawDifference *
        100;


      if (
        progressGain >
          0
      ) {


        powerResult =
          `PL PROGRESS +${progressGain.toFixed(
            2
          )}%`;


      }
      else {


        powerResult =
          "NO PL DEVELOPMENT";


      }


    }


  }


  return `

    <div
      class="
        exam-result-zone
        ${resultClass}
      "
    >

      <div
        class="
          exam-result-primary
          ${resultClass}
        "
        aria-label="
          ${primaryResult}
        "
      >
        ${renderKonohaExamAnimatedResultText(
          primaryResult
        )}
      </div>


      <div
        class="
          exam-result-reward
        "
      >
        +${totalRewardExp}
        ${disciplineName.toUpperCase()}
        EXP
      </div>


      ${
        powerResult
          ? `

            <div
              class="
                exam-result-power
                ${powerResultClass}
              "
            >
              ${powerResult}
            </div>

          `
          : ""
      }


      ${
        errors > 0
          ? `

            <div
              class="
                exam-result-error
              "
            >
              ${errors}
              INCOMPLETE
            </div>

          `
          : ""
      }


    </div>

  `;

}


// =========================================================
// BEGIN EXAM FROM UI
// =========================================================
//
// Every new Exam retires the previous temporary result
// before producing the next one.
//
// =========================================================

function beginKonohaExamFromUI() {


  const session =
    getKonohaActivityUISessionState();


  if (
    session.serviceId !==
      "exams" ||
    !session.characterId
  ) {


    return {

      success:
        false,

      completed:
        false,

      reason:
        "exam_ui_session_invalid"

    };

  }


  const screenData =
    getKonohaExamUIScreenData(
      session.characterId
    );


  if (
    !screenData ||
    screenData.canExecute !==
      true
  ) {


    return {

      success:
        false,

      completed:
        false,

      reason:
        "exam_not_eligible"

    };

  }


  // =========================================
  // RETIRE PREVIOUS RESULT
  // =========================================

  clearKonohaExamResultPresentation(
    false
  );


  const disciplineId =
    getKonohaExamSelectedDisciplineId();


  const requestedBatchSize =
    Number(
      KONOHA_EXAM_ATTEMPT_STATE
        .batchSize
    );


  const batchSize =
    [
      1,
      5,
      10
    ].includes(
      requestedBatchSize
    )

      ? requestedBatchSize

      : 1;


  const results =
    executeKonohaExamBatch(
      session.characterId,
      disciplineId,
      batchSize
    );


  // =========================================
  // POST-1990 RESULT PRESENTATION
  // =========================================
  //
  // Ordinary PASS / FAIL now lives in Special Notifications.
  // The historical floating result-stage state remains retired.
  // =========================================

  KONOHA_EXAM_ATTEMPT_STATE
    .resultVisible =
      false;


  renderKonohaExamVisualScreen();


  return {

    success:
      results.length > 0 &&
      results.every(
        result =>
          result &&
          result.completed ===
            true
      ),

    completed:
      results.length > 0,

    characterId:
      session.characterId,

    disciplineId:
      disciplineId,

    batchSize:
      batchSize,

    results:
      results

  };

}


// =========================================================
// BRICK 273 — EXAM GAMEPLAY REGRESSION
// =========================================================
//
// Validates:
//
// - Exam attempt state
// - discipline selection
// - hidden difficulty
// - history pressure
// - activity authority
// - single attempt execution
// - batch execution
// - x1 / x5 / x10 support
// - Chronicle recording
// - result notification projection
// - Special Notification rendering
//
// =========================================================

function validateKonohaExamGameplaySystem() {


  const selectedDiscipline =
    getKonohaExamSelectedDisciplineId();


  const context =
    createKonohaExamAttemptContext(
      "naruto",
      selectedDiscipline
    );


  const difficulty =
    context
      ? getKonohaExamHiddenDifficulty(
          context
        )
      : null;


  const history =
    context
      ? getKonohaExamHistoryPressure(
          context.characterId,
          context.disciplineId
        )
      : null;


  const activity =
    getActivityData(
      "exam"
    );


  const supportedBatchSizes = [
    1,
    5,
    10
  ];


  const checks = {

    attemptState:
      !!KONOHA_EXAM_ATTEMPT_STATE,

    selectedDiscipline:
      [
        "nin",
        "gen",
        "fuin"
      ].includes(
        selectedDiscipline
      ),

    context:
      !!context,

    hiddenDifficulty:
      Number.isFinite(
        difficulty
      ),

    historyPressure:
      !!(
        history &&
        Number.isFinite(
          history.failureAssist
        )
      ),

    activityAuthority:
      !!activity,

    singleExecution:
      typeof executeKonohaExamAttempt ===
        "function",

    batchExecution:
      typeof executeKonohaExamBatch ===
        "function",

    supportedBatchSizes:
      supportedBatchSizes.every(
        batchSize =>
          [
            1,
            5,
            10
          ].includes(
            batchSize
          )
      ),

    chronicleRecording:
      typeof recordKonohaExamAttempt ===
        "function",

    resultRenderer:
      typeof buildKonohaExamBatchResultNotification ===
        "function",

    specialNotificationRenderer:
      typeof renderKonohaExamSpecialNotifications ===
        "function"

  };


  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );


  console.log(
    "KONOHA EXAM GAMEPLAY HEALTH:",
    checks
  );


  return checks;

}


// =========================================================
// BRICK 303 — EXAM SIGNIFICANT HISTORY FEED
// =========================================================
//
// The baked SPECIAL NOTIFICATIONS panel now behaves as a
// passive recent-history feed.
//
// There is no:
// - ACKNOWLEDGE
// - ACKNOWLEDGE ALL
// - HISTORY button
// - CLOSE HISTORY
// - open / closed history mode
//
// The panel simply displays the most recent meaningful
// Exam consequences for the currently selected shinobi.
//
// IMPORTANT:
//
// The feed now also owns ordinary Exam batch-result feedback.
//
// Current supported entries:
//
// - PASS / FAIL / mixed Exam batch outcome
// - Discipline EXP gained
// - PL increase / PL progress projection
//
// Discipline Mastery increases are still NOT retained here.
// Their live value remains visible in the Exam progression UI.
//
// Future systems may add genuinely significant events such as:
//
// - Breakthrough available
// - Technique learned
// - Specialist path discovered
// - Promotion condition discovered
// - Rare training consequence
//
// Those events must come from their real gameplay authority.
// This renderer must never invent them.
//
// =========================================================


function buildKonohaExamBatchResultNotification(
  characterId
) {


  const results =
    Array.isArray(
      KONOHA_EXAM_ATTEMPT_STATE
        .lastBatch
    )

      ? KONOHA_EXAM_ATTEMPT_STATE
          .lastBatch

      : [];


  const meta =
    KONOHA_EXAM_ATTEMPT_STATE
      .lastBatchMeta ||
      null;


  if (
    !meta ||
    meta.characterId !==
      characterId ||
    results.length ===
      0
  ) {


    return null;


  }


  const completedResults =
    results.filter(
      result =>
        result &&
        result.completed ===
          true
    );


  const passedResults =
    completedResults.filter(
      result =>
        result.success ===
          true
    );


  const failedResults =
    completedResults.filter(
      result =>
        result.success !==
          true
    );


  const incompleteCount =
    Math.max(
      0,
      results.length -
      completedResults.length
    );


  let title =
    "ERROR";


  let type =
    "result-error";


  if (
    completedResults.length ===
      1 &&
    results.length ===
      1
  ) {


    if (
      passedResults.length ===
        1
    ) {


      title =
        "PASS";


      type =
        "result-pass";


    }
    else {


      title =
        "FAIL";


      type =
        "result-fail";


    }


  }
  else if (
    completedResults.length >
      0
  ) {


    title =
      `${passedResults.length} PASS · ${failedResults.length} FAIL`;


    type =
      failedResults.length ===
        0

        ? "result-pass"

        : (
            passedResults.length ===
              0

              ? "result-fail"

              : "result-mixed"
          );


  }


  const totalRewardExp =
    passedResults.reduce(
      (
        total,
        result
      ) =>
        total +
        (
          Number(
            result.rewardExp
          ) || 0
        ),
      0
    );


  const disciplineId =
    completedResults[0]
      ? completedResults[0]
          .disciplineId
      : meta.disciplineId;


  const discipline =
    disciplineId
      ? getShinobiDiscipline(
          disciplineId
        )
      : null;


  const disciplineName =
    String(
      discipline &&
      discipline.name
        ? discipline.name
        : (
            disciplineId ||
            "Exam"
          )
    ).toUpperCase();


  const detailParts = [


    totalRewardExp >
      0

      ? `+${totalRewardExp} ${disciplineName} EXP`

      : `0 ${disciplineName} EXP`


  ];


  if (
    meta.beforePL &&
    meta.afterPL
  ) {


    const beforeDisplayed =
      Number(
        meta.beforePL
          .displayedPL
      ) || 0;


    const afterDisplayed =
      Number(
        meta.afterPL
          .displayedPL
      ) || beforeDisplayed;


    if (
      afterDisplayed >
        beforeDisplayed
    ) {


      detailParts.push(
        `POWER LEVEL ${beforeDisplayed} → ${afterDisplayed}`
      );


    }
    else {


      const beforeRaw =
        Number(
          meta.beforePL
            .rawPL
        ) || 0;


      const afterRaw =
        Number(
          meta.afterPL
            .rawPL
        ) || beforeRaw;


      const rawDifference =
        Math.max(
          0,
          afterRaw -
          beforeRaw
        );


      const progressGain =
        rawDifference *
        100;


      detailParts.push(
        progressGain >
          0

          ? `PL PROGRESS +${progressGain.toFixed(
              2
            )}%`

          : "NO PL DEVELOPMENT"
      );


    }


  }


  if (
    incompleteCount >
      0
  ) {


    detailParts.push(
      `${incompleteCount} INCOMPLETE`
    );


  }


  return {

    id:
      `exam-result-${characterId}-${meta.disciplineId}-${Date.now()}`,

    characterId:
      characterId,

    type:
      type,

    significance:
      "activity-result",

    title:
      title,

    detail:
      detailParts.join(
        " · "
      ),

    timestamp:
      Date.now()

  };


}


// =========================================================
// POST-1990 — EXAM RESULT → SPECIAL NOTIFICATIONS
// =========================================================
//
// Routine Exam PASS / FAIL feedback now lives in the existing
// Special Notifications history feed rather than floating over
// the authored Exam artwork.
//
// PASS / FAIL resolution, reward EXP, PL derivation and Chronicle
// recording remain owned by their existing gameplay authorities.
//
// The batch notification carries the same useful result payload
// previously shown by the floating result stage:
//
// - PASS / FAIL / mixed batch count
// - Discipline EXP gained
// - PL increase or PL progress
// - incomplete attempt count when applicable
//
// A separate POWER LEVEL INCREASED notification is no longer
// emitted for the same batch because that would duplicate the
// batch result notification.
// =========================================================


function buildKonohaExamSpecialNotifications(
  characterId
) {


  const notifications =
    [];


  const batchResult =
    buildKonohaExamBatchResultNotification(
      characterId
    );


  if (batchResult) {


    notifications.push(
      batchResult
    );


  }


  return notifications;


}

// =========================================================
// RECORD SIGNIFICANT EXAM HISTORY
// =========================================================
//
// The feed retains the newest 10 significant notifications
// PER CHARACTER.
//
// activeSpecialNotifications is cleared because the old
// acknowledgement lifecycle is retired.
//
// =========================================================


function recordKonohaExamSpecialNotifications(
  characterId
) {


  const notifications =
    buildKonohaExamSpecialNotifications(
      characterId
    );


  // =========================================
  // RETIRE OLD ACTIVE-NOTIFICATION STATE
  // =========================================


  KONOHA_EXAM_ATTEMPT_STATE
    .activeSpecialNotifications =
      [];


  KONOHA_EXAM_ATTEMPT_STATE
    .specialNotificationHistoryOpen =
      false;


  if (
    notifications.length ===
      0
  ) {

    return [];

  }


  // =========================================
  // EXISTING HISTORY AUTHORITY
  // =========================================


  const existingHistory =
    Array.isArray(
      KONOHA_EXAM_ATTEMPT_STATE
        .specialNotificationHistory
    )

      ? KONOHA_EXAM_ATTEMPT_STATE
          .specialNotificationHistory

      : [];


  // =========================================
  // ADD NEWEST FIRST
  // =========================================


  KONOHA_EXAM_ATTEMPT_STATE
    .specialNotificationHistory = [

      ...notifications,

      ...existingHistory

    ];


  // =========================================
  // KEEP LAST 10 PER CHARACTER
  // =========================================


  const characterHistory =
    KONOHA_EXAM_ATTEMPT_STATE
      .specialNotificationHistory
      .filter(
        notification =>
          notification &&
          notification.characterId ===
            characterId
      )
      .slice(
        0,
        10
      );


  const otherCharacterHistory =
    KONOHA_EXAM_ATTEMPT_STATE
      .specialNotificationHistory
      .filter(
        notification =>
          notification &&
          notification.characterId !==
            characterId
      );


  KONOHA_EXAM_ATTEMPT_STATE
    .specialNotificationHistory = [

      ...characterHistory,

      ...otherCharacterHistory

    ];


  return notifications;

}


// =========================================================
// RETIRED ACKNOWLEDGEMENT COMPATIBILITY BRIDGE
// =========================================================
//
// Kept temporarily so any stale external caller does not
// throw an error.
//
// It performs no UI state transition because acknowledgement
// no longer exists.
//
// =========================================================


function acknowledgeKonohaExamSpecialNotifications() {


  KONOHA_EXAM_ATTEMPT_STATE
    .activeSpecialNotifications =
      [];


  return true;

}


// =========================================================
// RETIRED HISTORY TOGGLE COMPATIBILITY BRIDGE
// =========================================================
//
// History is permanently visible inside the baked panel.
// There is therefore nothing to open or close.
//
// =========================================================


function toggleKonohaExamSpecialNotificationHistory() {


  KONOHA_EXAM_ATTEMPT_STATE
    .specialNotificationHistoryOpen =
      false;


  return true;

}


// =========================================================
// SIGNIFICANT HISTORY FEED RENDERER
// =========================================================
//
// The baked artwork already owns the:
//
// SPECIAL NOTIFICATIONS
//
// heading.
//
// DOM text is rendered invisibly over the artwork until
// entries exist, then occupies only the baked notification
// square.
//
// Newest event appears first.
//
// =========================================================


function renderKonohaExamSpecialNotifications(
  characterId
) {


  const history =
    (
      Array.isArray(
        KONOHA_EXAM_ATTEMPT_STATE
          .specialNotificationHistory
      )

        ? KONOHA_EXAM_ATTEMPT_STATE
            .specialNotificationHistory

        : []
    )
      .filter(
        notification =>
          notification &&
          notification.characterId ===
            characterId
      )
      .slice(
        0,
        10
      );


  // =========================================
  // EMPTY FEED
  // =========================================
  //
  // Intentionally render an empty live layer.
  //
  // The baked SPECIAL NOTIFICATIONS artwork remains
  // completely unobstructed.
  // =========================================


  if (
    history.length ===
      0
  ) {


    return `

      <div
        class="
          exam-special-feed
          empty
        "
        aria-live="
          polite
        "
      >
      </div>

    `;

  }


  // =========================================
  // LIVE HISTORY FEED
  // =========================================


  return `

    <div
      class="
        exam-special-feed
      "
      aria-live="
        polite
      "
    >

      ${history
        .map(
          (
            notification,
            index
          ) => `

            <div
              class="
                exam-special-feed-entry
                ${notification.type || ""}
                ${
                  index === 0
                    ? "newest"
                    : ""
                }
              "
            >

              <div
                class="
                  exam-special-feed-title
                "
              >
                ${notification.title}
              </div>

              <div
                class="
                  exam-special-feed-detail
                "
              >
                ${notification.detail}
              </div>

            </div>

          `
        )
        .join("")}

    </div>

  `;

}
