function getNarutoV2InstabilityState(actor) {
  if (!actor||getCharacterRegistryId(actor)!=="naruto_v2") return null;
  return findBattleTransientState({stateKey:"naruto_v2_instability",targetSide:"player",targetParticipantId:actor.id})||ensureDedicatedRepresentationLifecycleState(actor);
}
function advanceNarutoV2InstabilityAfterCompletedSkill(actor,skill,envelope,resolution,options={}) {
  if (!actor||!skill||!resolution||resolution.resolved!==true||getCharacterRegistryId(actor)!=="naruto_v2") return null;
  const state=getNarutoV2InstabilityState(actor); if(!state||!state.data)return null;
  const order=["stable","strained","breached"]; const before=order.includes(state.data.instabilityState)?state.data.instabilityState:"stable";
  let shouldAdvance=!!(skill.instability&&skill.instability.advanceOnCompleted===true);
  if(skill.instability&&skill.instability.advanceWhenState===before) shouldAdvance=skill.instability.requiresAuthoredEscalationConfirmation===true?options.confirmInstabilityEscalation===true:true;
  if(!shouldAdvance){if(skill.instability&&skill.instability.advanceWhenState===before)recordBattleEvidence({eventType:"naruto_v2_instability_escalation_available",actionId:envelope.actionId,actorRef:envelope.actorRef,skillId:skill.id,stateRefs:[state.stateId],data:{before,requiresAuthoredEscalationConfirmation:true,hiddenStatCreated:false,automaticBattlePLDamage:0}});return {advanced:false,before,after:before,stateId:state.stateId};}
  const index=Math.max(0,order.indexOf(before)); const after=order[Math.min(order.length-1,index+Math.max(1,Number(skill.instability&&skill.instability.steps)||1))];
  state.data.instabilityState=after;
  recordBattleEvidence({eventType:"naruto_v2_instability_advanced",actionId:envelope.actionId,actorRef:envelope.actorRef,skillId:skill.id,stateRefs:[state.stateId],data:{before,after,categorical:true,hiddenStatCreated:false,battlePLDamage:0,injury:false,staminaLoss:0,forcedTransformation:false}});
  return {advanced:after!==before,before,after,stateId:state.stateId};
}
function recordBaryonContactErosionOccurrence(definition={}) {
  const actorSide=definition.actorSide||"player",actorParticipantId=definition.actorParticipantId||null,targetSide=definition.targetSide||null,targetParticipantId=definition.targetParticipantId||null;
  if(!actorParticipantId||!targetSide||!targetParticipantId)return {success:false,reason:"baryon_participant_refs_missing"};
  const actor=getBattleParticipantByIdentity(actorSide,actorParticipantId); if(!actor||getCharacterRegistryId(actor)!=="baryon_mode")return {success:false,reason:"actor_not_baryon_representation"};
  if(definition.qualifyingContactConfirmed!==true)return {success:false,reason:"qualifying_baryon_contact_not_confirmed"};
  const opportunityIndex=getBattleActionOpportunityIndex(actorSide,actorParticipantId),runtime=ensureBattleRuntimeState();
  const duplicate=runtime.evidence.find(record=>record&&record.eventType==="baryon_contact_erosion"&&record.actorRef&&record.actorRef.side===actorSide&&record.actorRef.participantId===actorParticipantId&&record.targetRef&&record.targetRef.side===targetSide&&record.targetRef.participantId===targetParticipantId&&record.data&&Number(record.data.actorOpportunityIndex)===Number(opportunityIndex));
  if(duplicate)return {success:true,idempotent:true,evidence:duplicate};
  const evidence=recordBattleEvidence({eventType:"baryon_contact_erosion",actionId:definition.actionId||null,actorRef:createBattleParticipantRef(actorSide,actorParticipantId),targetRef:createBattleParticipantRef(targetSide,targetParticipantId),skillId:definition.skillId||null,sourceRefs:[{type:"character_registry",id:"baryon_mode",role:"active_representation"},...(definition.skillId?[{type:"skill",id:definition.skillId,role:"qualifying_contact_action"}]:[])],data:{actorOpportunityIndex:opportunityIndex,qualifyingContactConfirmed:true,attackPLContribution:0,battlePLDamage:0,poison:false,burning:false,injury:false,lifespanStatCreated:false,permanentStatReduction:false,causalConsequenceEvidenceOnly:true}});
  return evidence?{success:true,evidence}:{success:false,reason:"baryon_contact_erosion_evidence_commit_failed"};
}

// =========================================================
// BRICK 634 — KURAMA SOVEREIGN OVERLOAD OPPORTUNITY COST
// =========================================================
function applyKuramaSovereignOverloadOpportunityCost(side,participantId,actionId) {
  if (side!=="player") return null;
  const actor=getBattleParticipantByIdentity(side,participantId);
  if (!actor||getCharacterRegistryId(actor)!=="kurama_sovereign") return null;
  const overload=getKuramaSovereignOverload(actor);
  if (overload>=4) {
    const backlash=absorbBattleDamageBearingCapacity("player",participantId,12);
    const crown=findBattleTransientState({stateKey:"crown_of_the_usurper",targetSide:"player",targetParticipantId:participantId});
    if (crown) removeBattleTransientState(crown.stateId);
    setKuramaSovereignOverload(actor,2,{actionId,sourceRefs:[{type:"character_registry",id:"kurama_sovereign",role:"overload_authority"}]});
    recordBattleEvidence({eventType:"sovereign_overload_backlash",actionId,actorRef:createBattleParticipantRef("player",participantId),sourceRefs:[{type:"character_registry",id:"kurama_sovereign",role:"overload_authority"}],data:{overloadBefore:overload,staminaBypassed:true,backlashBattlePL:12,absorbedPL:backlash.absorbedPL,crownTerminated:!!crown,overloadResetTo:2,selfDamageStatInvented:false}});
    let zeroResult=null;
    if (backlash.totalCapacityAfter<=0) zeroResult=handleBattleParticipantAtZeroPL("player",participantId,actor,{actionId});
    return {overloadBefore:overload,backlash:12,overloadAfter:2,zeroResult};
  }
  if (overload===3) {
    const before=getBattleRemainingPL("player",participantId);
    const after=Math.max(0,before-5);
    setBattleRemainingPL("player",participantId,after);
    recordBattleEvidence({eventType:"sovereign_overload_underlying_battle_pl_deterioration",actionId,actorRef:createBattleParticipantRef("player",participantId),sourceRefs:[{type:"character_registry",id:"kurama_sovereign",role:"overload_authority"}],data:{overload,underlyingBattlePLBefore:before,underlyingBattlePLAfter:after,underlyingBattlePLLoss:before-after,staminaBypassed:true,temporaryCapacityUnaffected:true}});
    let zeroResult=null;
    if (after<=0&&getBattleTemporaryCapacity("player",participantId)<=0) zeroResult=handleBattleParticipantAtZeroPL("player",participantId,actor,{actionId});
    return {overloadBefore:overload,underlyingLoss:before-after,overloadAfter:overload,zeroResult};
  }
  return {overloadBefore:overload,noDeterioration:true,overloadAfter:overload};
}

function consumeBattleActionOpportunity(
  side,
  participantId,
  actionId,
  reason = "valid_action_completed"
) {
  // End-of-opportunity authored effects resolve after the action's own
  // mechanics. This permits a successfully used Antidote to remove Poison
  // before its pending end tick. Burning already resolved at opportunity start.
  const endEffects=resolveBattleEndOfActionOpportunityEffects(side,participantId,actionId);
  const threeTailRegeneration=applyThreeTailEndOpportunityRegeneration(side,participantId,actionId);
  const blackGoldDeterioration=applyBlackGoldSaturationOpportunityDeterioration(side,participantId,actionId);

  const durationConditions=getBattleParticipantConditions(side,participantId)
    .filter(condition=>condition.data&&Number.isFinite(Number(condition.data.remainingActionOpportunities)));
  durationConditions.forEach(condition=>{
    condition.data.remainingActionOpportunities=Math.max(0,Number(condition.data.remainingActionOpportunities)-1);
    recordBattleEvidence({eventType:"condition_duration_advanced",actionId,actorRef:createBattleParticipantRef(side,participantId),conditionRefs:[condition.conditionId],sourceRefs:getBattleConditionCausalSourceRefs(condition),data:{conditionKey:condition.conditionKey,remainingActionOpportunities:condition.data.remainingActionOpportunities}});
    if (condition.data.remainingActionOpportunities<=0) removeBattleCondition(condition.conditionId,{reason:"action_opportunity_duration_expired",actionId,targetRef:createBattleParticipantRef(side,participantId)});
  });

  const expiringConditions=getBattleParticipantConditions(side,participantId)
    .filter(condition=>condition.data&&condition.data.expiry==="next_action_opportunity");
  const removedConditionIds=[];
  expiringConditions.forEach(condition=>{
    if (removeBattleCondition(condition.conditionId,{reason:"next_action_opportunity_expired",actionId,targetRef:createBattleParticipantRef(side,participantId)})) {
      removedConditionIds.push(condition.conditionId);
    }
  });

  consumeBattleEffectiveStateActionOpportunity(side,participantId,actionId,reason);
  advanceBattleTransientStateActionOpportunity(side,participantId,actionId,reason);
  advanceBattleActionOpportunityIndex(side,participantId);
  const sovereignOverload=applyKuramaSovereignOverloadOpportunityCost(side,participantId,actionId);
  const representationLifecycle=consumeDedicatedRepresentationLifecycleActionOpportunity(side,participantId,actionId);
  return {removedConditionIds,endEffects,threeTailRegeneration,blackGoldDeterioration,sovereignOverload,representationLifecycle};
}

function cleanupBattleParticipantRuntimeState(
  side,
  participantId,
  reason = "participant_left_battle"
) {


  const runtime =
    ensureBattleRuntimeState();

  // BRICK 883 — committed Planetary Devastation Stage 1 remains history even
  // when Deva becomes invalid before the forced Stage 2 opportunity.
  const pendingPlanetary=runtime.transientStates.find(state=>state&&state.stateKey==="planetary_core_formation"&&state.sourceRef&&state.sourceRef.side===side&&state.sourceRef.participantId===participantId);
  if (pendingPlanetary) recordBattleEvidence({eventType:"planetary_devastation_pending_invalidated",committedOccurrence:true,actorRef:createBattleParticipantRef(side,participantId),skillId:"akatsuki_deva_planetary_devastation",stateRefs:[pendingPlanetary.stateId],data:{reason,phantomCollapse:false,stage1HistoryPreserved:true}});


  const removedStateIds =
    [];


  const removedConditionIds =
    [];


  runtime.transientStates =
    runtime.transientStates.filter(
      state => {


        const targetsParticipant =
          state.targetRef &&
          state.targetRef.side ===
            side &&
          state.targetRef.participantId ===
            participantId;


        if (
          targetsParticipant
        ) {

          removedStateIds.push(
            state.stateId
          );

          return false;
        }


        return true;
      }
    );

  const cleanupConditionIds=runtime.conditions
    .filter(condition=>condition&&condition.targetRef&&condition.targetRef.side===side&&condition.targetRef.participantId===participantId)
    .map(condition=>condition.conditionId);

  cleanupConditionIds.forEach(conditionId=>{
    if (removeBattleCondition(conditionId,{reason,cleanupOnly:true,removerRef:createBattleParticipantRef(side,participantId)})) {
      removedConditionIds.push(conditionId);
    }
  });


  const removedProjections = getBattleParticipantEffectiveStateProjections(side, participantId);
  removedProjections.forEach(projection => {
    removeBattleEffectiveStateProjection(projection.projectionKey, side, participantId, reason);
  });

  if (runtime.temporaryCapacity[side]) delete runtime.temporaryCapacity[side][participantId];
  if (runtime.attachedSummons[side]) delete runtime.attachedSummons[side][participantId];
  if (runtime.actionOpportunityState&&runtime.actionOpportunityState.counters&&runtime.actionOpportunityState.counters[side]) delete runtime.actionOpportunityState.counters[side][participantId];

  if (
    removedStateIds.length > 0 ||
    removedConditionIds.length > 0 ||
    removedProjections.length > 0
  ) {


    recordBattleEvidence({

      eventType:
        "participant_runtime_cleanup",

      actorRef:
        createBattleParticipantRef(
          side,
          participantId
        ),

      stateRefs:
        removedStateIds,

      conditionRefs:
        removedConditionIds,

      data: {

        reason:
          reason

      }

    });
  }


  return {

    removedStateIds:
      removedStateIds,

    removedConditionIds:
      removedConditionIds,

    removedProjectionKeys:
      removedProjections.map(projection => projection.projectionKey)

  };
}

