// BRICK 304 — SHARED BATTLE ACTION ENVELOPE
// BRICK 344 — ITEM IDENTITY THROUGH SHARED ACTION EVIDENCE
// BRICK 624 — ACTION ENVELOPE PRESERVES TYPED SOURCE ROLES
// =========================================================
//
// Both manual input and future Smart AI should create the
// same semantic action request.
//
// This layer validates the request.
//
// It does NOT calculate final damage.
//
// =========================================================

function createBattleActionEnvelope(
  definition
) {


  const runtime =
    ensureBattleRuntimeState();


  if (
    !definition
  ) {

    return null;
  }


  runtime.actionSequence +=
    1;


  return {

    actionId:
      createBattleRuntimeRecordId(
        "action"
      ),


    battleId:
      currentBattle.battleId,


    sequence:
      runtime.actionSequence,


    actorRef:
      createBattleParticipantRef(
        definition.actorSide,
        definition.actorParticipantId
      ),


    targetRef:
      createBattleParticipantRef(
        definition.targetSide,
        definition.targetParticipantId
      ),


    actionClass:
      definition.actionClass ||
      null,


    skillId:
      definition.skillId ||
      null,


    itemId:
      definition.itemId ||
      null,


    sourceRefs:
      Array.isArray(
        definition.sourceRefs
      )

        ? definition.sourceRefs
            .filter(
              ref =>
                ref &&
                ref.type &&
                (ref.id || (ref.side && ref.participantId))
            )
            .map(
              ref =>
                cloneBattleRuntimeValue(ref)
            )
            .filter(Boolean)

        : [],


    data:
      definition.data
        ? cloneBattleRuntimeValue(
            definition.data
          )
        : {},


    createdAt:
      Date.now()

  };
}


function getBattleActiveParticipantId(
  side
) {


  const slot =
    getBattleDeploymentSlot(
      side,
      1
    );


  return (
    slot &&
    slot.participantId

      ? slot.participantId

      : null
  );
}


function validateBattleActionEnvelope(
  envelope
) {


  if (
    !envelope
  ) {


    return {

      valid:
        false,

      reason:
        "missing_action"

    };
  }


  if (
    !currentBattle.active
  ) {


    return {

      valid:
        false,

      reason:
        "battle_not_active"

    };
  }


  if (
    currentBattle.battleOver
  ) {


    return {

      valid:
        false,

      reason:
        "battle_complete"

    };
  }


  if (
    !envelope.actorRef ||
    !envelope.actorRef.side ||
    !envelope.actorRef
      .participantId
  ) {


    return {

      valid:
        false,

      reason:
        "missing_actor"

    };
  }


  if (
    !envelope.actionClass
  ) {


    return {

      valid:
        false,

      reason:
        "missing_action_class"

    };
  }


  const activeParticipantId =
    getBattleActiveParticipantId(
      envelope.actorRef.side
    );


  if (
    !activeParticipantId ||
    activeParticipantId !==
      envelope.actorRef
        .participantId
  ) {


    return {

      valid:
        false,

      reason:
        "actor_not_active"

    };
  }


  const blockingConditions =
    getBattleBlockingConditions(
      envelope.actorRef.side,
      envelope.actorRef
        .participantId,
      envelope.actionClass,
      envelope.data &&
      Array.isArray(
        envelope.data.traits
      )
        ? envelope.data.traits
        : []
    );


  if (
    blockingConditions.length >
      0
  ) {


    return {

      valid:
        false,

      reason:
        "blocked_by_condition",

      blockingConditionIds:
        blockingConditions.map(
          condition =>
            condition.conditionId
        )

    };
  }


  return {

    valid:
      true,

    reason:
      null,

    blockingConditionIds:
      []

  };
}


