function completeBattleVictoryFromDamage(
  finishingShinobi,
  envelope = null,
  defeatedParticipantId = null
) {
  if (currentBattle.battleOver===true) return currentBattle.rewards;
  const rewardSource=getBattleEncounterEnemy()||currentBattle.enemy||selectedEnemy||null;
  currentBattle.battleOver=true;
  currentBattle.active=false;
  currentBattle.completedAt=Date.now();
  currentBattle.outcome={
    type:"victory",
    committed:true,
    completedAt:currentBattle.completedAt,
    finishingShinobiId:finishingShinobi?finishingShinobi.id:null,
    defeatedParticipantId:defeatedParticipantId||null,
    rewardAuthorityEnemyId:rewardSource?rewardSource.id:null
  };
  currentBattle.defeat=null;
  markEncounterReservationFromBattleOutcome("victory");
  const rewards=generateBattleRewards(rewardSource,finishingShinobi);
  const mvp=calculateBattleMVP();
  if (rewards&&mvp) rewards.mvp=mvp;
  recordBattleEvidence({
    eventType:"battle_victory",
    actionId:envelope?envelope.actionId:null,
    actorRef:finishingShinobi?createBattleParticipantRef("player",finishingShinobi.id):null,
    targetRef:defeatedParticipantId?createBattleParticipantRef("enemy",defeatedParticipantId):null,
    data:{enemyRemainingBattlePL:0,finishingShinobiId:finishingShinobi?finishingShinobi.id:null,enemyDeploymentExhausted:true,rewardAuthorityEnemyId:rewardSource?rewardSource.id:null,outcomeCommitted:true}
  });
  // Victory presentation still expects an enemy compatibility object.
  currentBattle.enemy=rewardSource;
  if (typeof finalizeArc1M1UnknownOperativeConfrontationFromBattleOutcome === "function") {
    finalizeArc1M1UnknownOperativeConfrontationFromBattleOutcome("victory",{
      finishingShinobiId:finishingShinobi?finishingShinobi.id:null,
      defeatedParticipantId:defeatedParticipantId||null
    });
  }
  if (typeof finalizeArc1M7SanitisationEncounterFromBattleOutcome === "function") {
    finalizeArc1M7SanitisationEncounterFromBattleOutcome("victory",{
      finishingShinobiId:finishingShinobi?finishingShinobi.id:null,
      defeatedParticipantId:defeatedParticipantId||null
    });
  }
  if (typeof finalizeArc1M5FemaleOperatorEncounterFromBattleOutcome === "function") {
    finalizeArc1M5FemaleOperatorEncounterFromBattleOutcome("victory",{
      finishingShinobiId:finishingShinobi?finishingShinobi.id:null,
      defeatedParticipantId:defeatedParticipantId||null
    });
  }
  saveTestState();
  openOverlay("victory");
  return rewards;
}

function completeBattleDefeat(defeatedParticipantId=null,envelope=null,reason="player_deployment_exhausted") {
  if (currentBattle.battleOver===true) return currentBattle.outcome;
  const completedAt=Date.now();
  currentBattle.battleOver=true;
  currentBattle.active=false;
  currentBattle.completedAt=completedAt;
  currentBattle.claimedAt=null;
  currentBattle.completionRecorded=false;
  currentBattle.outcome={
    type:"defeat",
    committed:true,
    completedAt,
    reason,
    defeatedParticipantId:defeatedParticipantId||null,
    rewardsGenerated:false,
    rewardClaimAvailable:false,
    historyPreserved:true
  };
  currentBattle.defeat=cloneBattleRuntimeValue(currentBattle.outcome);
  markEncounterReservationFromBattleOutcome("defeat");

  if (Array.isArray(currentBattle.battleLog)) {
    currentBattle.battleLog.push("All deployed shinobi have reached 0 Battle PL. DEFEAT.");
  }

  recordBattleEvidence({
    eventType:"battle_defeat",
    actionId:envelope&&envelope.actionId?envelope.actionId:null,
    targetRef:defeatedParticipantId?createBattleParticipantRef("player",defeatedParticipantId):null,
    data:{
      reason,
      playerDeploymentExhausted:true,
      outcomeCommitted:true,
      rewardsGenerated:false,
      rewardClaimAvailable:false,
      historyRollback:false
    }
  });

  if (typeof finalizeArc1M1UnknownOperativeConfrontationFromBattleOutcome === "function") {
    finalizeArc1M1UnknownOperativeConfrontationFromBattleOutcome("defeat",{
      defeatedParticipantId:defeatedParticipantId||null,
      reason
    });
  }
  if (typeof finalizeArc1M7SanitisationEncounterFromBattleOutcome === "function") {
    finalizeArc1M7SanitisationEncounterFromBattleOutcome("defeat",{
      defeatedParticipantId:defeatedParticipantId||null,
      reason
    });
  }
  if (typeof finalizeArc1M5FemaleOperatorEncounterFromBattleOutcome === "function") {
    finalizeArc1M5FemaleOperatorEncounterFromBattleOutcome("defeat",{
      defeatedParticipantId:defeatedParticipantId||null,
      reason
    });
  }

  saveTestState();

  // BRICKS 1723–1726 — caller-owned defeat returns through the same reusable
  // continuation architecture. Ordinary Battles remain unchanged because they
  // have no returnContext. Defeat never manufactures a next opportunity.
  if (currentBattle.returnContext) {
    resumeBattleCallerAfterCompletion("defeat");
  }

  return currentBattle.outcome;
}

function handleBattleParticipantAtZeroPL(
  side,
  participantId,
  actor,
  envelope
) {
  if (!side||!participantId) return null;
  const slotNumber=getBattleDeploymentParticipantSlotNumber(side,participantId);
  if (!slotNumber) return null;

  if (side==="enemy") {
    if (typeof recordArc1M7SanitisationOperativeNeutralized === "function") {
      recordArc1M7SanitisationOperativeNeutralized(participantId,envelope||null);
    }
    if (typeof recordArc1M5FemaleOperatorNeutralized === "function") {
      recordArc1M5FemaleOperatorNeutralized(participantId,envelope||null);
    }
    const bossTransition=tryAdvanceAuthoritativeBossStage(participantId,envelope||null);
    if (bossTransition&&bossTransition.success===true) return bossTransition;

    const transition=advanceBattleParticipantAtZeroPL(side,participantId);
    if (hasBattleDeploymentParticipants("enemy")) return transition;
    return completeBattleVictoryFromDamage(actor,envelope,participantId);
  }

  if (side==="player") {
    const transition=advanceBattleParticipantAtZeroPL(side,participantId);
    if (hasBattleDeploymentParticipants("player")) return transition;
    completeBattleDefeat(participantId,envelope||null,"player_deployment_exhausted");
    return transition||currentBattle.outcome;
  }

  return advanceBattleParticipantAtZeroPL(side,participantId);
}

function resolveSingleBattleDamageSegment(definition, segmentIndex = 0) {
  if (!definition || !definition.actorSide || !definition.actorParticipantId || !definition.targetSide || !definition.targetParticipantId || !definition.output) return null;
  const targetRecord=getBattleRemainingPLRecord(definition.targetSide,definition.targetParticipantId);
  if (!targetRecord) return null;
  const preDefense=resolveBattlePreStaminaDefense({attackPL:definition.output.attackPL,mitigable:definition.mitigable===true,targetSide:definition.targetSide,targetParticipantId:definition.targetParticipantId,primaryDiscipline:definition.output.primaryDiscipline||null,skillId:definition.skill&&definition.skill.id||null,actionId:definition.envelope&&definition.envelope.actionId||null,sourceSide:definition.actorSide||null,sourceParticipantId:definition.actorParticipantId||null,qualifyingDirectAttackPLPacket:!(definition.output&&definition.output.perTarget===true)&&!(definition.skill&&Array.isArray(definition.skill.traits)&&definition.skill.traits.includes("one_authored_area_action"))});
  const effectiveStamina=getBattleEffectiveStamina(definition.targetSide,definition.targetParticipantId);
  const staminaResolution=calculateBattleStaminaMitigationV1(preDefense.resolvedAttackPL,effectiveStamina);
  const absorption=absorbBattleDamageBearingCapacity(definition.targetSide,definition.targetParticipantId,staminaResolution.finalDamage);
  const stateRefs=[...(Array.isArray(definition.stateRefs)?definition.stateRefs:[]),...preDefense.consumedStateIds];
  const evidence=recordBattleEvidence({
    eventType:"damage_resolved",actionId:definition.envelope?definition.envelope.actionId:null,
    actorRef:createBattleParticipantRef(definition.actorSide,definition.actorParticipantId),
    targetRef:createBattleParticipantRef(definition.targetSide,definition.targetParticipantId),
    skillId:definition.skill?definition.skill.id:null,
    sourceRefs:definition.envelope&&Array.isArray(definition.envelope.sourceRefs)?definition.envelope.sourceRefs:[],stateRefs,
    data:{
      excessDamageSegmentIndex:segmentIndex,
      continuationSegment:segmentIndex>0,
      primaryDiscipline:definition.output.primaryDiscipline,
      primaryDisciplineStatKey:definition.output.statKey,
      effectivePrimaryDiscipline:definition.output.effectivePrimaryDiscipline,
      authoredCoefficient:segmentIndex===0?definition.output.coefficient:null,
      branch:segmentIndex===0?definition.output.branch:"excess_damage_continuation",
      branchMultiplier:segmentIndex===0?definition.output.branchMultiplier:null,
      authoredPreExecutionMagnitude:segmentIndex===0?definition.output.authoredPreExecutionMagnitude:null,
      weaponExecutionMultiplier:segmentIndex===0?definition.output.weaponExecutionMultiplier:null,
      preDefenseAttackMagnitude:definition.output.preDefenseAttackMagnitude,
      preDefenseAttackPL:definition.output.attackPL,
      guardingStepParticipated:preDefense.guardingStep.participated,
      guardingStepActualReduction:preDefense.guardingStep.actualReduction,
      enmaGuardParticipated:preDefense.enmaGuard.participated,
      enmaGuardActualReduction:preDefense.enmaGuard.actualReduction,
      flatGuards:Array.isArray(preDefense.flatGuards)?cloneBattleRuntimeValue(preDefense.flatGuards):[],
      ratioGuards:Array.isArray(preDefense.ratioGuards)?cloneBattleRuntimeValue(preDefense.ratioGuards):[],
      resolvedAttackPL:preDefense.resolvedAttackPL,
      effectiveStamina:staminaResolution.effectiveStamina,
      staminaPivot:staminaResolution.pivot,
      staminaMitigationAmount:staminaResolution.mitigationAmount,
      finalDamage:staminaResolution.finalDamage,
      temporaryCapacityBefore:absorption.temporaryCapacityBefore,
      temporaryCapacityAbsorbed:absorption.temporaryCapacityAbsorbed,
      temporaryCapacityAfter:absorption.temporaryCapacityAfter,
      remainingBattlePLBefore:absorption.underlyingBattlePLBefore,
      remainingBattlePLAfter:absorption.underlyingBattlePLAfter,
      absorbedPL:absorption.absorbedPL,
      residualAttackPL:absorption.residualAttackPL,
      mechanicalPacketCount:definition.skill&&definition.skill.mechanicalPacketCount?definition.skill.mechanicalPacketCount:1
    }
  });
  const actor=getBattleParticipantByIdentity(definition.actorSide,definition.actorParticipantId);
  if (definition.actorSide==="player"&&definition.targetSide==="enemy"&&actor) recordBattleContribution(actor,absorption.absorbedPL,definition.output.statKey);
  currentBattle.lastDamage=absorption.absorbedPL;
  if (Array.isArray(currentBattle.battleLog)) {
    const g=preDefense.guardingStep.participated?` Guard blocked ${preDefense.guardingStep.actualReduction}.`:"";
    const e=preDefense.enmaGuard.participated?` Enma blocked ${preDefense.enmaGuard.actualReduction}.`:"";
    const f=Array.isArray(preDefense.flatGuards)&&preDefense.flatGuards.some(guard=>guard.participated)?` Flat guard prevented ${preDefense.flatGuards.reduce((sum,guard)=>sum+(Number(guard.actualReduction)||0),0)}.`:"";
    const r=Array.isArray(preDefense.ratioGuards)&&preDefense.ratioGuards.some(guard=>guard.participated)?` Ratio guard reduced to ${preDefense.resolvedAttackPL}.`:"";
    const t=absorption.temporaryCapacityAbsorbed>0?` Temporary capacity absorbed ${absorption.temporaryCapacityAbsorbed}.`:"";
    currentBattle.battleLog.push(`Attack ${definition.output.attackPL}.${g}${e}${f}${r} Stamina blocked ${staminaResolution.mitigationAmount}.${t} ${absorption.absorbedPL} capacity lost.`);
  }
  let zeroResult=null;
  if (absorption.totalCapacityAfter<=0) zeroResult=handleBattleParticipantAtZeroPL(definition.targetSide,definition.targetParticipantId,actor,definition.envelope||null);
  return {evidence,output:definition.output,preDefense,stamina:staminaResolution,absorption,
    finalDamage:staminaResolution.finalDamage,absorbedPL:absorption.absorbedPL,residualAttackPL:absorption.residualAttackPL,
    remainingBattlePLBefore:absorption.underlyingBattlePLBefore,remainingBattlePLAfter:absorption.underlyingBattlePLAfter,zeroResult};
}

function resolveBattleDamagePacket(definition) {
  if (!definition||!definition.output) return null;

  const primary=resolveSingleBattleDamageSegment(definition,0);
  if (!primary) return null;

  const segments=[primary];
  const excessContract=definition.excess||(definition.skill&&definition.skill.excess)||null;
  const excessEligible=!!(excessContract&&excessContract.eligible===true);
  let excessResolution=null;

  if (excessEligible) {
    const capRatio=Math.max(0,Math.min(1,Number(excessContract.capRatio)||0));
    const authoredPrimaryAttackPL=Math.max(0,Math.round(Number(definition.output.attackPL)||0));
    const rawExcess=Math.max(0,Math.round(Number(primary.residualAttackPL)||0));
    const ratioCapAmount=Math.max(0,Math.floor(authoredPrimaryAttackPL*capRatio));
    const absoluteCap=Number.isFinite(Number(excessContract.absoluteCap))?Math.max(0,Math.floor(Number(excessContract.absoluteCap))):null;
    const capAmount=absoluteCap===null?ratioCapAmount:Math.min(ratioCapAmount,absoluteCap);
    let cappedExcess=Math.min(rawExcess,capAmount);
    const transition=primary.zeroResult&&primary.zeroResult.type==="withdrawal_queue_advance"?primary.zeroResult:null;
    const continuationTargetId=transition&&transition.replacementParticipantId?transition.replacementParticipantId:null;

    excessResolution={
      eligible:true,
      capRatio,
      ratioCapAmount,
      absoluteCap,
      capAmount,
      rawExcess,
      cappedExcess,
      primaryTargetParticipantId:definition.targetParticipantId,
      continuationTargetParticipantId:continuationTargetId,
      continued:false,
      nonRecursive:true
    };

    if (cappedExcess>0&&continuationTargetId&&!currentBattle.battleOver) {
      const continuationOutput={
        ...definition.output,
        attackPL:cappedExcess,
        preDefenseAttackMagnitude:cappedExcess,
        coefficient:null,
        branch:"capped_excess_continuation",
        branchMultiplier:null,
        authoredPreExecutionMagnitude:null,
        weaponExecutionMultiplier:null
      };
      const continuation=resolveSingleBattleDamageSegment({...definition,targetParticipantId:continuationTargetId,output:continuationOutput,excess:null},1);
      if (continuation) {
        segments.push(continuation);
        excessResolution.continued=true;
        excessResolution.continuationAbsorbedPL=continuation.absorbedPL;
        excessResolution.continuationFinalDamage=continuation.finalDamage;
      }
    }

    recordBattleEvidence({
      eventType:"capped_excess_damage_resolved",
      actionId:definition.envelope?definition.envelope.actionId:null,
      actorRef:createBattleParticipantRef(definition.actorSide,definition.actorParticipantId),
      targetRef:createBattleParticipantRef(definition.targetSide,definition.targetParticipantId),
      skillId:definition.skill?definition.skill.id:null,
      sourceRefs:definition.envelope&&Array.isArray(definition.envelope.sourceRefs)?definition.envelope.sourceRefs:[],
      data:{...excessResolution,crossTargetPooling:false,reappliedTechniqueCoefficient:false,reappliedSourceCost:false,recursiveContinuation:false}
    });
  }

  const last=segments[segments.length-1];
  return {
    ...primary,
    segments,
    excessResolution,
    remainingBattlePLAfter:last.remainingBattlePLAfter,
    residualAttackPL:last.residualAttackPL
  };
}

