function attemptAcademyMenmaYinChakraMantle() {
  if (!currentBattle.active || currentBattle.battleOver) return {success:false,reason:"battle_not_active"};
  const actor=getBattleDeploymentParticipant("player",1);
  if (!actor || actor.id!=="academy_menma") return {success:false,reason:"academy_menma_not_active"};
  const access=evaluateAttachedSummonAccess(actor.id,"menma_nine_tails",{requireCooperative:true,expressionId:"limited_yin_kurama_chakra"});
  if (!access.available) return {success:false,reason:access.reason,access};
  const key=createEffectiveStateProjectionKey("academy_menma","yin_chakra_mantle_academy","active_transformation");
  if (getBattleEffectiveStateProjection(key,"player",actor.id)) return {success:false,reason:"mantle_already_active"};
  const envelope=createBattleActionEnvelope({actorSide:"player",actorParticipantId:actor.id,targetSide:"player",targetParticipantId:actor.id,
    actionClass:"positive_self_enhancement",skillId:"yin_chakra_mantle_academy",
    sourceRefs:[{type:"attached_summon",id:"menma_nine_tails"},{type:"transformation_package",id:"yin_chakra_mantle_academy"}],
    data:{traits:["chakra_dependent_positive_self_enhancement","active_transformation"]}});
  const entry=beginBattleActionResolution(envelope);
  if (!entry.accepted) return {success:false,reason:entry.validation.reason,validation:entry.validation};
  const activated=activateBattleEffectiveStatePackage({side:"player",participantId:actor.id,sourceId:"academy_menma",exactPackageId:"yin_chakra_mantle_academy",
    expressionStateId:"active_transformation",activationActionId:envelope.actionId,durationActionOpportunities:2,
    activationOwner:{type:"transformation",id:"yin_chakra_mantle_academy"},expirationOwner:{type:"action_opportunity",count:2}});
  if (!activated.success) return activated;
  recordBattleEvidence({eventType:"transformation_activated",actionId:envelope.actionId,actorRef:envelope.actorRef,sourceRefs:envelope.sourceRefs,
    data:{transformationId:"yin_chakra_mantle_academy",durationActionOpportunities:2,temporaryCapacityOverlay:4}});
  consumeBattleActionOpportunity("player",actor.id,envelope.actionId,"transformation_activation_completed");
  saveTestState();
  openOverlay("combat");
  return {success:true,envelope,projection:activated.projection,effectiveStats:getDevelopedEffectiveCharacterStats(actor),effectivePL:calculateEffectivePL(actor),temporaryCapacity:getBattleTemporaryCapacity("player",actor.id)};
}

function findAcademyConditionalState(
  skill,
  actor,
  target
) {


  if (
    !skill ||
    !skill.conditional ||
    !skill.conditional.stateKey ||
    !actor ||
    !target
  ) {

    return null;
  }


  const targetSide =
    skill.targetMode ===
      "self"

      ? "player"

      : "enemy";


  let matchingState =
    findBattleTransientState({

      stateKey:
        skill.conditional.stateKey,

      sourceSide:
        "player",

      sourceParticipantId:
        skill.conditional.sourceMustBeActor

          ? actor.id

          : undefined,

      targetSide:
        targetSide,

      targetParticipantId:
        target.id

    });


  if (
    !matchingState &&
    Array.isArray(
      skill.traits
    )
  ) {


    const selfState =
      findBattleTransientState({

        stateKey:
          skill.conditional.stateKey,

        sourceSide:
          "player",

        sourceParticipantId:
          skill.conditional.sourceMustBeActor

          ? actor.id

          : undefined,

        targetSide:
          "player",

        targetParticipantId:
          actor.id

      });


    const compatibleTrait =
      selfState &&
      selfState.data

        ? selfState.data.compatibleConsumerTrait ||
          null

        : null;


    if (
      selfState &&
      compatibleTrait &&
      skill.traits.includes(
        compatibleTrait
      )
    ) {

      matchingState =
        selfState;
    }
  }


  if (
    !matchingState ||
    !canBattleParticipantConsumeTransientState(
      matchingState,
      "player",
      actor.id
    )
  ) {

    return null;
  }


  return matchingState;
}


function applyAcademySealStrikeCondition(
  skill,
  envelope,
  actor,
  target
) {


  if (
    !skill ||
    !skill.conditional ||
    !skill.conditional.deferredCondition ||
    !target
  ) {

    return null;
  }


  const definition =
    skill.conditional.deferredCondition;


  const condition =
    addBattleCondition({

      conditionKey:
        definition.conditionKey,

      sourceSide:
        "player",

      sourceParticipantId:
        actor.id,

      sourceRefs:
        Array.isArray(envelope.sourceRefs)
          ? envelope.sourceRefs
          : [],

      sourceSkillId:
        skill.id,

      actionId:
        envelope.actionId,

      targetSide:
        envelope.targetRef.side,

      targetParticipantId:
        target.id,

      blockedActionClasses:
        definition.blockedActionClasses ||
        [],

      blockedActionTraits:
        definition.blockedActionTraits ||
        [],

      data: {

        expiry:
          definition.expiry ||
          "next_action_opportunity",

        appliedBySkillId:
          skill.id

      }

    });


  if (
    condition
  ) {


    recordBattleEvidence({

      eventType:
        "condition_applied",

      actionId:
        envelope.actionId,

      actorRef:
        envelope.actorRef,

      targetRef:
        envelope.targetRef,

      skillId:
        skill.id,

      sourceRefs:
        envelope.sourceRefs,

      conditionRefs: [
        condition.conditionId
      ],

      data: {

        conditionKey:
          condition.conditionKey,

        expiry:
          condition.data.expiry

      }

    });
  }


  return condition;
}


function resolveAcademyBattleSkillSemantics(
  skill,
  envelope,
  actor,
  target
) {


  const stateRefs =
    [];


  // =======================================================
  // SETUP / SELF-STATE SKILLS
  // =======================================================

  if (
    skill.resolutionKind ===
      "transient_state" &&
    skill.state
  ) {


    const stateTarget =
      skill.targetMode ===
        "self"

        ? actor

        : target;


    const upsert =
      upsertAcademyBattleSkillState(
        skill,
        actor,
        stateTarget
      );


    if (
      !upsert
    ) {


      return {

        resolved:
          false,

        reason:
          "state_creation_failed"

      };
    }


    stateRefs.push(
      upsert.state.stateId
    );


    recordBattleEvidence({

      eventType:
        upsert.refreshed

          ? "transient_state_refreshed"

          : "transient_state_created",

      actionId:
        envelope.actionId,

      actorRef:
        envelope.actorRef,

      targetRef:
        envelope.targetRef,

      skillId:
        skill.id,

      sourceRefs:
        envelope.sourceRefs,

      stateRefs:
        stateRefs,

      data: {

        stateKey:
          upsert.state.stateKey,

        ownerRef:
          upsert.state.ownerRef ||
          null

      }

    });


    currentBattle.battleLog.push(
      `${actor.name} used ${skill.displayName}.`
    );


    currentBattle.battleLog.push(
      `${upsert.state.stateKey} ${
        upsert.refreshed
          ? "refreshed"
          : "created"
      }.`
    );


    return {

      resolved:
        true,

      branch:
        "setup",

      stateRefs:
        stateRefs,

      conditionRefs:
        [],

      damageApplied:
        false

    };
  }


  // =======================================================
  // DIRECT DAMAGE SKILLS
  // =======================================================

  const conditionalState =
    findAcademyConditionalState(
      skill,
      actor,
      target
    );


  const branch =
    conditionalState

      ? skill.conditional.enhancedBranch ||
        "enhanced"

      : "normal";


  const output =
    calculateAcademySkillAttackOutput(
      skill,
      actor,
      branch
    );


  if (
    !output
  ) {


    return {

      resolved:
        false,

      reason:
        "damage_output_unavailable"

    };
  }


  const damage =
    resolveBattleDamagePacket({

      envelope:
        envelope,

      skill:
        skill,

      actorSide:
        "player",

      actorParticipantId:
        actor.id,

      targetSide:
        envelope.targetRef.side,

      targetParticipantId:
        target.id,

      output:
        output,

      mitigable:
        skill.staminaMitigation ===
          true,

      stateRefs:
        conditionalState
          ? [
              conditionalState.stateId
            ]
          : []

    });


  if (
    !damage
  ) {


    return {

      resolved:
        false,

      reason:
        "damage_resolution_failed"

    };
  }


  let consumedState =
    null;


  if (
    conditionalState &&
    skill.conditional.consume ===
      true
  ) {


    consumedState =
      consumeBattleTransientState(
        conditionalState.stateId,
        "player",
        actor.id
      );


    if (
      consumedState
    ) {

      stateRefs.push(
        consumedState.stateId
      );
    }
  }


  let appliedCondition =
    null;


  if (
    branch ===
      "sealed_chakra_flow" &&
    damage.remainingBattlePLAfter >
      0 &&
    skill.conditional &&
    skill.conditional.deferredCondition
  ) {


    appliedCondition =
      applyAcademySealStrikeCondition(
        skill,
        envelope,
        actor,
        target
      );
  }


  currentBattle.battleLog.push(
    `${actor.name} used ${skill.displayName}${
      branch !== "normal"
        ? ` [${branch}]`
        : ""
    }.`
  );


  return {

    resolved:
      true,

    branch:
      branch,

    stateRefs:
      stateRefs,

    conditionRefs:
      appliedCondition
        ? [
            appliedCondition.conditionId
          ]
        : [],

    consumedStateId:
      consumedState
        ? consumedState.stateId
        : null,

    damageApplied:
      true,

    damage:
      damage,

    finalDamage:
      damage.finalDamage,

    remainingBattlePLBefore:
      damage.remainingBattlePLBefore,

    remainingBattlePLAfter:
      damage.remainingBattlePLAfter

  };
}


