// BRICK 310 — SHARED SKILL ACTION ENTRY
// =========================================================

function attemptAcademyBattleSkill(
  skillId
) {


  const actor =
    getBattleDeploymentParticipant(
      "player",
      1
    );


  const enemyTarget =
    getBattleDeploymentParticipant(
      "enemy",
      1
    );


  const skill =
    getAcademyBattleSkillDefinition(
      skillId
    );


  const availability =
    evaluateAcademyBattleSkillAvailability(
      skill,
      actor,
      enemyTarget
    );


  if (
    !availability.available
  ) {


    console.log(
      "Skill unavailable:",
      availability.reason
    );


    return {

      success:
        false,

      reason:
        availability.reason

    };
  }


  const resolvedTarget =
    skill.targetMode ===
      "self"

      ? actor

      : enemyTarget;


  const envelope =
    createBattleActionEnvelope({

      actorSide:
        "player",

      actorParticipantId:
        actor.id,

      targetSide:
        skill.targetMode ===
          "self"

          ? "player"

          : "enemy",

      targetParticipantId:
        resolvedTarget
          ? resolvedTarget.id
          : null,

      actionClass:
        skill.actionClass,

      skillId:
        skill.id,

      sourceRefs:
        getAcademyBattleSkillSourceRefs(
          availability
        ),

      data: {

        type:
          skill.type,

        primaryDiscipline:
          skill.primaryDiscipline,

        executionTags: [
          ...skill.executionTags
        ],

        traits: [
          ...skill.traits
        ]

      }

    });


  const entry =
    beginBattleActionResolution(
      envelope
    );


  if (
    !entry.accepted
  ) {


    return {

      success:
        false,

      reason:
        entry.validation.reason,

      validation:
        entry.validation

    };
  }


  const resolution =
    resolveAcademyBattleSkillSemantics(
      skill,
      envelope,
      actor,
      resolvedTarget
    );


  recordBattleEvidence({

    eventType:
      "skill_action_completed",

    committedOccurrence:
      true,

    actionId:
      envelope.actionId,

    actorRef:
      envelope.actorRef,

    targetRef:
      envelope.targetRef,

    skillId:
      skill.id,

    sourceRefs:
      envelope.sourceRefs,

    stateRefs:
      resolution &&
      Array.isArray(
        resolution.stateRefs
      )

        ? resolution.stateRefs

        : [],

    conditionRefs:
      resolution &&
      Array.isArray(
        resolution.conditionRefs
      )

        ? resolution.conditionRefs

        : [],

    data: {

      resolved:
        !!(
          resolution &&
          resolution.resolved
        ),

      branch:
        resolution
          ? resolution.branch ||
            null
          : null,

      damageApplied:
        !!(
          resolution &&
          resolution.damageApplied
        ),

      finalDamage:
        resolution &&
        typeof resolution.finalDamage ===
          "number"
          ? resolution.finalDamage
          : 0,

      remainingBattlePLAfter:
        resolution &&
        typeof resolution.remainingBattlePLAfter ===
          "number"
          ? resolution.remainingBattlePLAfter
          : null

    }

  });


  if (
    resolution &&
    resolution.resolved ===
      true
  ) {


    consumeBattleActionOpportunity(
      "player",
      actor.id,
      envelope.actionId,
      "valid_action_completed"
    );
  }


  saveTestState();


  if (
    currentBattle.battleOver !==
      true
  ) {


    openOverlay(
      "combat"
    );
  }


  return {

    success:
      true,

    envelope:
      envelope,

    resolution:
      resolution

  };
}

