// =========================================================
// CORE ENGINE — GAME INITIALISATION
// =========================================================

window.addEventListener(
  "load",
  async () => {

    // BRICK 1364 — fail-closed startup proof for the ratified 14 portrait binaries.
    // Source admission is atomic at 116; if any approved binary cannot decode or is
    // not exactly 1024x1024, core game initialisation is withheld rather than
    // operating a partially validated production gate.
    const final116BinaryQA=await runAlphaFinal116PortraitBinaryQADiagnostics();
    window.__SC_FINAL116_BINARY_QA__=final116BinaryQA;
    if (!final116BinaryQA.pass) {
      console.error("SC Final-116 startup blocked: portrait binary QA failed.",final116BinaryQA);
      document.documentElement.setAttribute("data-sc-final116-binary-qa","failed");
      return;
    }
    document.documentElement.setAttribute("data-sc-final116-binary-qa","green");

    // BRICKS 1603–1604 — supplemental accepted portrait binary proof.
    // Ten live supersessions are startup-critical. The four Assets-ready but
    // non-live identities are QA'd and reported without collapsing Assets-ready
    // into production admission.
    const supplemental14BinaryQA=await runAlphaSupplemental14PortraitBinaryQADiagnostics();
    window.__SC_SUPPLEMENTAL14_BINARY_QA__=supplemental14BinaryQA;
    document.documentElement.setAttribute("data-sc-supplemental14-binary-qa",supplemental14BinaryQA.pass?"green":"failed");
    if (!supplemental14BinaryQA.liveTenDecodeAndDimensions||!supplemental14BinaryQA.liveTenExactResolvers) {
      console.error("SC startup blocked: live supplemental portrait QA failed.",supplemental14BinaryQA);
      document.documentElement.setAttribute("data-sc-supplemental10-live-portrait-qa","failed");
      return;
    }
    document.documentElement.setAttribute("data-sc-supplemental10-live-portrait-qa","green");

    // BRICKS 1775–1779 — cheap source-level RC status at startup. Full 116
    // binary reconciliation remains an explicit manual/browser diagnostic so
    // normal startup does not re-download the entire portrait catalogue.
    window.__SC_LIVE116_PORTRAIT_STATIC_QA__=runAlphaLive116UIPortraitManifestDiagnostics();
    window.__SC_POST1779_RC_STATIC__={
      portraitStatic:window.__SC_LIVE116_PORTRAIT_STATIC_QA__,
      enemyPaths:runAlphaEnemyPresentationPathDiagnostics(),
      whisperMap:getArc1M1WhisperWoodsMapBindingAuthorityPreflight()
    };

    // BRICKS 1788–1797 — area-local production asset QA. A failure blocks
    // Whisper Woods entry, not unrelated Alpha startup. No placeholder/fallback.
    const whisperMapBinaryQA=await runAlphaWhisperWoodsMapBinaryQADiagnostics();
    window.__SC_WHISPER_WOODS_MAP_BINARY_QA__=whisperMapBinaryQA;
    document.documentElement.setAttribute("data-sc-whisper-woods-map-qa",whisperMapBinaryQA.pass?"green":"failed");
    if (!whisperMapBinaryQA.pass) console.error("SC Whisper Woods map QA failed; local-area entry will remain blocked.",whisperMapBinaryQA);

    syncCharacterEquipmentFromSave();
    restoreTestState();

    // BRICK 962 — authoritative reload resumption wins over stale ordinary
    // overlay/session presentation while formation remains mandatory.
    resumeAcademyTeamFormationJourneyAfterLoad();

  }
);

